typedef struct {
    int valid;
    int logical_tier;
    const void *model_map;
    uint32_t layer;
    uint32_t n_total_expert;
    uint32_t slot_count;
    uint32_t compact_count;
    uint64_t gate_offset;
    uint64_t up_offset;
    uint64_t down_offset;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    char *gate_ptr;      /* device pointer (VRAM or mapped pinned) */
    char *up_ptr;
    char *down_ptr;
    uint64_t gate_capacity;
    uint64_t up_capacity;
    uint64_t down_capacity;
    char *gate_host;     /* host pointer when pinned (DS4_CUDA_SLOT_PINNED) */
    char *up_host;
    char *down_host;
    int32_t *slot_selected_ptr;
    int32_t *slot_selected_host;
    uint64_t slot_selected_capacity;
    ds4_gpu_tensor slot_selected_tensor;
    /* Incremental residency (Windows/8GB fusion port): the compact table
     * persists across layers; the expert -> slot map is keyed by GLOBAL
     * expert id (layer * n_total_expert + eu) because expert ids RESTART
     * per layer (each layer has its own n_total_expert experts at its own
     * gate/up/down offsets). A per-layer key collides across layers:
     * layer L+1's routed expert eu would falsely hit layer L's resident
     * row and skip its copy, silently running layer L's weights — a
     * deterministic wrong-output bug that only fires when the resident
     * budget lets the map survive across layers.
     * resident_experts counts rows currently held.
     * (DS4_SLOT_MAX_EXPERT = per-layer bound for the local remap only;
     * this TU does not see the ds4.c enum.) */
#define DS4_SLOT_MAX_EXPERT 384
    int32_t *host_expert_to_slot;   /* dynamic: [layers x n_total_expert] */
    uint32_t host_expert_map_entries;
    uint32_t host_expert_per_layer; /* n_total_expert the map is keyed for */
    uint32_t resident_experts;
    /* Reverse map for whole-table verification (DS4_CUDA_SLOT_VERIFY). */
    uint64_t *slot_gate_src;        /* dynamic: [resident slots] */
    uint32_t slot_gate_src_entries;
    /* Peak per-layer union footprint since the last ds4_gpu_slot_peak_reset
     * (the adaptive sub-batch scheduler measures bytes-per-token from it). */
    uint64_t peak_union_bytes;
} cuda_stream_selected_cache;

static cuda_stream_selected_cache g_stream_selected_cache;

/* DS4_CUDA_SLOT_PINNED=1 homes the compact slot table in pinned system RAM
 * (cudaHostAllocMapped, driver pinned pool — NOT cudaHostRegister) so the
 * 8GB VRAM budget stops limiting incremental residency. The GPU reads the
 * table zero-copy over PCIe (~25GB/s; verified correct by test_pinned10/11). */
static int cuda_slot_pinned(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_SLOT_PINNED");
        cached = (env && env[0] == '1') ? 1 : 0;
        if (cached) {
            fprintf(stderr,
                    "ds4: CUDA slot table pinned in system RAM (zero-copy PCIe reads)\n");
        }
    }
    return cached;
}

static void cuda_stream_selected_cache_invalidate(void) {
    g_stream_selected_cache.valid = 0;
}

static void cuda_stream_selected_cache_release(void) {
    const int tier = g_stream_selected_cache.logical_tier;
    if (tier >= 0 && tier < g_n_gpus) {
        (void)ds4_gpu_set_current_device(tier);
    }
    if (g_stream_selected_cache.gate_ptr) {
        if (g_stream_selected_cache.gate_host) {
            (void)cudaFreeHost(g_stream_selected_cache.gate_host);
        } else {
            (void)cudaFree(g_stream_selected_cache.gate_ptr);
        }
    }
    if (g_stream_selected_cache.up_ptr) {
        if (g_stream_selected_cache.up_host) {
            (void)cudaFreeHost(g_stream_selected_cache.up_host);
        } else {
            (void)cudaFree(g_stream_selected_cache.up_ptr);
        }
    }
    if (g_stream_selected_cache.down_ptr) {
        if (g_stream_selected_cache.down_host) {
            (void)cudaFreeHost(g_stream_selected_cache.down_host);
        } else {
            (void)cudaFree(g_stream_selected_cache.down_ptr);
        }
    }
    if (g_stream_selected_cache.slot_selected_ptr) {
        if (g_stream_selected_cache.slot_selected_host) {
            (void)cudaFreeHost(g_stream_selected_cache.slot_selected_host);
        } else {
            (void)cudaFree(g_stream_selected_cache.slot_selected_ptr);
        }
    }
    free(g_stream_selected_cache.host_expert_to_slot);
    free(g_stream_selected_cache.slot_gate_src);
    memset(&g_stream_selected_cache, 0, sizeof(g_stream_selected_cache));
    g_stream_selected_cache.logical_tier = -1;
}

/* Global expert key: expert ids restart per layer, so the resident map
 * must be keyed by (layer, expert) to avoid cross-layer collisions. */
static bool stream_selected_global_idx(uint32_t layer, uint32_t eu,
                                       uint32_t n_total_expert,
                                       uint64_t *out_idx) {
    if (n_total_expert == 0) return false;
    *out_idx = (uint64_t)layer * (uint64_t)n_total_expert + (uint64_t)eu;
    return true;
}

/* Grow the global expert->slot map to cover `layers` layers of `per_layer`
 * experts each. New entries start at -1 (not resident). When the per-layer
 * keying changes (model shape), the whole map is reallocated fresh. */
#define DS4_SLOT_MAP_MAX_ENTRIES 0x1000000u /* 16M entries cap */
static bool stream_selected_map_ensure(uint32_t layers, uint32_t per_layer) {
    if (layers == 0 || per_layer == 0) return false;
    const uint64_t need64 = (uint64_t)layers * (uint64_t)per_layer;
    if (need64 > DS4_SLOT_MAP_MAX_ENTRIES) {
        fprintf(stderr,
                "ds4: CUDA streaming expert map too large (%llu entries)\n",
                (unsigned long long)need64);
        return false;
    }
    const uint32_t need = (uint32_t)need64;
    if (g_stream_selected_cache.host_expert_to_slot &&
        g_stream_selected_cache.host_expert_map_entries >= need &&
        g_stream_selected_cache.host_expert_per_layer == per_layer) {
        return true;
    }
    if (g_stream_selected_cache.host_expert_per_layer != per_layer) {
        free(g_stream_selected_cache.host_expert_to_slot);
        g_stream_selected_cache.host_expert_to_slot = NULL;
        g_stream_selected_cache.host_expert_map_entries = 0;
        g_stream_selected_cache.host_expert_per_layer = per_layer;
    }
    int32_t *np = (int32_t *)realloc(
            g_stream_selected_cache.host_expert_to_slot,
            (size_t)need * sizeof(int32_t));
    if (!np) {
        g_stream_selected_cache.host_expert_to_slot = NULL;
        g_stream_selected_cache.host_expert_map_entries = 0;
        return false;
    }
    for (uint32_t i = g_stream_selected_cache.host_expert_map_entries;
         i < need; i++) {
        np[i] = -1;
    }
    g_stream_selected_cache.host_expert_to_slot = np;
    g_stream_selected_cache.host_expert_map_entries = need;
    g_stream_selected_cache.host_expert_per_layer = per_layer;
    return true;
}

static void stream_selected_map_reset(void) {
    for (uint32_t i = 0;
         i < g_stream_selected_cache.host_expert_map_entries; i++) {
        g_stream_selected_cache.host_expert_to_slot[i] = -1;
    }
}

/* Grow the reverse source map (DS4_CUDA_SLOT_VERIFY) to hold `slots` rows. */
static bool stream_selected_src_ensure(uint32_t slots) {
    if (g_stream_selected_cache.slot_gate_src &&
        g_stream_selected_cache.slot_gate_src_entries >= slots) {
        return true;
    }
    uint32_t cap = g_stream_selected_cache.slot_gate_src_entries;
    if (cap == 0) cap = DS4_SLOT_MAX_EXPERT;
    while (cap < slots) {
        if (cap > 0x80000000u / 2u) return false;
        cap *= 2u;
    }
    uint64_t *np = (uint64_t *)realloc(
            g_stream_selected_cache.slot_gate_src,
            (size_t)cap * sizeof(uint64_t));
    if (!np) return false;
    memset(np + g_stream_selected_cache.slot_gate_src_entries, 0,
           (size_t)(cap - g_stream_selected_cache.slot_gate_src_entries) *
                   sizeof(uint64_t));
    g_stream_selected_cache.slot_gate_src = np;
    g_stream_selected_cache.slot_gate_src_entries = cap;
    return true;
}

