/* Router-delta registry (DS4_ROUTER_DELTA, ReMoE Part 1): per-layer
 * replacement router weights uploaded to VRAM, resolved by abs_offset
 * before the normal model-range cache so the GPU prefill routes with the
 * fine-tuned weights. */
static struct {
    uint64_t offset;
    uint64_t bytes;
    char    *dev;
} g_router_delta[128];
static int g_router_delta_n = 0;

extern "C" int ds4_gpu_install_router_delta(const void *host_data,
                                            uint64_t offset,
                                            uint64_t bytes) {
    if (!host_data || bytes == 0 || g_router_delta_n >= 128 ||
        g_n_gpus <= 0) {
        return 0;
    }
    for (int i = 0; i < g_router_delta_n; i++) {
        if (g_router_delta[i].offset == offset) return 1;
    }
    void *dev = NULL;
    int prev = -1;
    (void)cudaGetDevice(&prev);
    if (cudaSetDevice(g_gpu[0].device_id) != cudaSuccess) return 0;
    cudaError_t err = cudaMalloc(&dev, (size_t)bytes);
    if (err == cudaSuccess) {
        err = cudaMemcpy(dev, host_data, (size_t)bytes,
                         cudaMemcpyHostToDevice);
    }
    if (err != cudaSuccess && dev) {
        (void)cudaFree(dev);
        dev = NULL;
    }
    if (prev >= 0) (void)cudaSetDevice(prev);
    if (!dev) return 0;
    g_router_delta[g_router_delta_n].offset = offset;
    g_router_delta[g_router_delta_n].bytes = bytes;
    g_router_delta[g_router_delta_n].dev = (char *)dev;
    g_router_delta_n++;
    return 1;
}

/* Per-pair pinned-host bounce buffers, indexed [src][dst]. Lazily grown
 * to the largest copy seen for that pair. Each pair is its own allocation
 * so concurrent fan-out copies from a single source GPU to multiple
 * destinations cannot race for staging memory. */
static void   *g_xdev_bounce[DS4_MAX_GPUS][DS4_MAX_GPUS];
static size_t  g_xdev_bounce_bytes[DS4_MAX_GPUS][DS4_MAX_GPUS];

/* Internal helper: resolve a tensor's device index. -1 (untagged) is
 * treated as device 0 for legacy callers. */
static inline int ds4_tensor_device_idx(const ds4_gpu_tensor *t) {
    if (!t) return 0;
    int d = t->device_id;
    if (d < 0) return 0;
    return d;
}

