/* WITH_DEVICE(d) { ... } scope macro.
 *
 * Save the calling thread's current CUDA device, switch to device `d`,
 * run the body exactly once, then restore the previous device. If the
 * required CUDA calls fail, the body still runs (we don't have a clean
 * way to early-exit a containing function from a macro), but the next
 * CUDA call inside the body will surface the error naturally.
 *
 * Implementation: a for-loop with two synthetic variables. Iter 0 runs
 * the body; on iter 1, the iteration step restores the previous device
 * via cudaSetDevice and sets _wd_first = 0 so the loop exits. The
 * single-statement-body restriction of for-loops is removed by the
 * required `{ ... }` block in the call site.
 */
#define WITH_DEVICE(d)                                                      \
    for (int _wd_prev = -1, _wd_first = 1;                                  \
         _wd_first;                                                          \
         _wd_first = 0,                                                      \
         (_wd_prev >= 0 ? (void)cudaSetDevice(_wd_prev) : (void)0))         \
        if (cudaGetDevice(&_wd_prev) != cudaSuccess) { /* leave */ } else   \
        if (cudaSetDevice(d)           != cudaSuccess) { /* leave */ } else

/* =========================================================================
 * Per-device selective model cache (selective model cache).
 *
 * The public API in ds4_gpu.h declares ds4_tensor_range and the
 * device_cache_tensors / lookup_cache entry points. ds4_cuda.cu does NOT
 * include ds4_gpu.h historically (a pre-existing project convention), so
 * we redeclare the struct here with the same layout the header uses.
 * The implementation links by C linkage; struct compatibility is by
 * field layout. */
typedef struct {
    uint64_t source_offset;
    uint64_t bytes;
    int      target_device;
} ds4_tensor_range;

struct cuda_device_cache {
    void   *base;     /* device-side slab base */
    size_t  bytes;
    int     present;
};
static cuda_device_cache g_dev_cache[DS4_MAX_GPUS];

struct cache_range_entry {
    uint64_t source_offset;
    uint64_t bytes;
    int      device_id;
    void    *device_ptr;
};
static std::vector<cache_range_entry> g_cache_ranges;

struct cuda_model_range {
    const void *host_base;
    uint64_t offset;
    uint64_t bytes;
    char *device_ptr;
    void *registered_base;
    char *registered_device_base;
    uint64_t registered_bytes;
    int host_registered;
    int arena_allocated;
    int borrowed;
    /* LRU (DS4_CUDA_WEIGHT_ARENA_LRU): monotonic tick of the last resolve
     * hit.  Zero until the first hit; the evictor picks the smallest. */
    uint64_t last_use;
};

struct cuda_model_arena {
    char *device_ptr;
    uint64_t bytes;
    uint64_t used;
    /* LRU: free holes inside this chunk, {offset,size}, sorted+coalesced.
     * Evicted ranges return their space here so later loads reuse it
     * without any new cudaMalloc (the WDDM shared-pool headroom check
     * only gates new chunks, so hole reuse stays legal at the cap). */
    std::vector<std::pair<uint64_t, uint64_t>> holes;
};

struct cuda_q8_f16_range {
    const void *host_base;
    uint64_t offset;
    uint64_t weight_bytes;
    uint64_t in_dim;
    uint64_t out_dim;
    __half *device_ptr;
    int device_id;          /* physical CUDA device id; 0 in single-tier */
};

struct cuda_q8_f32_range {
    const void *host_base;
    uint64_t offset;
    uint64_t weight_bytes;
    uint64_t in_dim;
    uint64_t out_dim;
    float *device_ptr;
    int device_id;          /* physical CUDA device id; 0 in single-tier */
};

enum cuda_derived_kind {
    CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE = 4,
    CUDA_DERIVED_Q8_0_ALIGNED_DENSE = 5,
    CUDA_DERIVED_Q2_K_ALIGNED_MOE = 6,
};

struct cuda_derived_range {
    const void *host_base;
    uint64_t source_offset;
    uint64_t source_bytes;
    uint32_t kind;
    uint64_t in_dim;
    uint64_t out_dim;
    uint32_t group_count;
    uint64_t bytes;
    char *device_ptr;
};

static std::vector<cuda_model_range> g_model_ranges;
static std::vector<cuda_model_arena> g_model_arenas;
static std::unordered_map<uint64_t, size_t> g_model_range_by_offset;
/* LRU tick: incremented on every arena-range resolve hit while
 * DS4_CUDA_WEIGHT_ARENA_LRU is enabled or a prefill LRU session is
 * active. */
static uint64_t g_model_lru_tick;
/* LRU tombstone count: evicted ranges stay in the vector as inert entries
 * until compaction; keeps by_offset indices stable. */
static uint64_t g_model_lru_dead;

/* Largest range the LRU evictor may reclaim.  0 = no size limit (the
 * model-tail guard still applies). */
static uint64_t cuda_model_arena_lru_max_bytes(void) {
    static uint64_t cached = 0;
    static int cached_done = 0;
    if (cached_done) return cached;
    cached_done = 1;
    uint64_t mb = 1;
    const char *env = getenv("DS4_CUDA_WEIGHT_ARENA_LRU_MAX_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env && v > 0) mb = (uint64_t)v;
    }
    cached = mb * 1048576ull;
    return cached;
}

/* Prefill-phase LRU scheduling (DS4_CUDA_WEIGHT_ARENA_PREFILL_LRU,
 * default on).  The streaming layer-major prefill holds direct device
 * pointers only to ranges resolved by the CURRENT layer/chunk: those
 * resolves bump the LRU tick past the reclaim floor, so they are never
 * reclaim candidates.  At each layer/chunk boundary the caller advances
 * the floor, making every range from completed layers reclaimable; the
 * evictor drains the device itself before freeing anything, so the
 * boundary costs nothing on the hot path.  The arena can then grow
 * across layers inside the WDDM shared-pool headroom budget (recycling
 * instead of freezing); without this, the static headroom cap starves
 * the streaming cache and costs ~2.7x on long-prompt prefill
 * (2.94 -> 8.07 t/s measured).  Evicted weights are identical bytes —
 * reclaim only costs a reload. */
static int g_arena_prefill_mode;
static uint64_t g_arena_prefill_floor;

static int cuda_arena_prefill_lru_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_WEIGHT_ARENA_PREFILL_LRU");
        cached = (env && env[0] && strcmp(env, "0") == 0) ? 0 : 1;
    }
    return cached == 1;
}

/* Largest range the prefill evictor may reclaim.  0 = no size limit (the
 * model-tail guard still applies).  The decode-era default cap (1 MiB)
 * is too small for prefill expert tables, so the prefill mode gets its
 * own, unlimited-by-default cap. */
static uint64_t cuda_arena_prefill_lru_max_bytes(void) {
    static uint64_t cached = 0;
    static int cached_done = 0;
    if (cached_done) return cached;
    cached_done = 1;
    uint64_t mb = 0;
    const char *env = getenv("DS4_CUDA_WEIGHT_ARENA_PREFILL_LRU_MAX_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env) mb = (uint64_t)v;
    }
    cached = mb * 1048576ull;
    return cached;
}

extern "C" void ds4_gpu_arena_prefill_begin(void) {
    if (!cuda_arena_prefill_lru_enabled()) return;
    cudaError_t serr = cudaDeviceSynchronize();
    if (getenv("DS4_CUDA_PREFILL_DIAG")) {
        size_t free_b = 0, total_b = 0;
        (void)cudaMemGetInfo(&free_b, &total_b);
        fprintf(stderr,
                "ds4: PREFILL-DIAG begin sync=%s free=%.2f MiB "
                "arena_chunks=%zu arena_used=%.2f MiB tick=%llu\n",
                cudaGetErrorString(serr), (double)free_b / 1048576.0,
                g_model_arenas.size(),
                g_model_arenas.empty() ? 0.0
                    : (double)g_model_arenas[0].used / 1048576.0,
                (unsigned long long)g_model_lru_tick);
    }
    if (serr != cudaSuccess) (void)cudaGetLastError();
    g_arena_prefill_mode = 1;
    g_arena_prefill_floor = g_model_lru_tick;
}

extern "C" void ds4_gpu_arena_prefill_chunk_boundary(void) {
    if (!cuda_arena_prefill_lru_enabled() || !g_arena_prefill_mode) return;
    /* Advance the reclaim floor WITHOUT syncing: expanding the candidate
     * set is harmless, and every actual eviction drains the device first
     * (cuda_model_arena_lru_make_room device-synchronizes before freeing
     * anything).  A sync here would serialize the streaming pipeline's
     * overlapped next-layer uploads on every layer, even when the arena is
     * under no pressure at all. */
    g_arena_prefill_floor = g_model_lru_tick;
    /* Fresh space may now exist: lift a sticky full flag set while the
     * previous layer/chunk had nothing evictable. */
    g_model_cache_full = 0;
}

extern "C" void ds4_gpu_arena_prefill_end(void) {
    g_arena_prefill_mode = 0;
    g_arena_prefill_floor = 0;
}

/* Weight-arena LRU eviction (DS4_CUDA_WEIGHT_ARENA_LRU, default off):
 * when the arena cannot grow (env limit / WDDM shared-pool headroom /
 * cudaMalloc failure), the least-recently-used arena ranges are evicted
 * and their space reused.  Weights are identical bytes wherever they live,
 * so eviction never changes numerics — it only costs a reload.
 *
 * Eviction is restricted to small transient ranges (<= LRU_MAX_MB,
 * default 1 MiB) OUTSIDE the model tail: the graph holds direct device
 * pointers to the large tensors and the output block (last ~512 MiB)
 * without re-resolving them, so evicting those would leave stale
 * pointers and illegal accesses.  The per-token compressor micro-ranges
 * (the streaming-path accumulation leak) are re-resolved per use and
 * are exactly what this mechanism reclaims. */
static int cuda_model_arena_lru_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_WEIGHT_ARENA_LRU");
        cached = (env && env[0] && strcmp(env, "0") != 0) ? 1 : 0;
        if (cached == 1) {
            const uint64_t max_mb = cuda_model_arena_lru_max_bytes() >> 20;
            fprintf(stderr,
                    "ds4: CUDA weight arena LRU eviction enabled "
                    "(DS4_CUDA_WEIGHT_ARENA_LRU, evictable <= %llu MiB, "
                    "model tail protected, decode-phase only)\n",
                    (unsigned long long)max_mb);
        }
    }
    return cached == 1;
}
static std::vector<cuda_q8_f16_range> g_q8_f16_ranges;
static std::unordered_map<uint64_t, size_t> g_q8_f16_by_offset;
static std::vector<cuda_q8_f32_range> g_q8_f32_ranges;
static std::unordered_map<uint64_t, size_t> g_q8_f32_by_offset;
static std::vector<cuda_derived_range> g_derived_ranges;
static const void *g_derived_replace_map;
static uint64_t g_derived_artifact_bytes;
static double g_derived_artifact_build_secs;
static int g_derived_replaces_complete;
static void *g_aligned_q81_scratch;
static uint64_t g_model_range_bytes;
static uint64_t g_q8_f16_bytes;
static uint64_t g_q8_f32_bytes;
static int g_q8_cache_suppressed;
static int g_q8_f16_disabled_after_oom;
static int g_q8_f16_budget_notice_printed;
static uint64_t g_model_load_progress_next;
static double g_model_load_progress_last;
static int g_model_load_progress_started;
static int g_model_load_progress_tty;
static void *g_cuda_tmp;
static uint64_t g_cuda_tmp_bytes;
/* Dedicated DS4_CUDA_KV_BITQ dequant gather buffer (grows on demand; must
 * not alias the shared tmp slab -- decode launches allocate slab temps after
 * the gather and would clobber the dequantized rows mid-flight). */
static void *g_bitq_gather;
static uint64_t g_bitq_gather_bytes;
/* Same for the DS4_CUDA_KV_BITQ_COMP cache (the comp temp must survive the
 * downstream launches too). */
static void *g_bitq_comp_gather;
static uint64_t g_bitq_comp_gather_bytes;
/* Same for the DS4_CUDA_KV_BITQ_IDX indexer cache. */
static void *g_bitq_idx_gather;
static uint64_t g_bitq_idx_gather_bytes;
static void *g_tt_scratch;
static uint64_t g_tt_scratch_bytes;
static int g_tt_scratch_device = -1;
#ifdef DS4_CUDA_HAVE_MXF4
static void *g_indexer_mxf4_scratch;
static uint64_t g_indexer_mxf4_scratch_bytes;
static int g_indexer_mxf4_scratch_device = -1;
#endif
static void *g_model_stage_raw[4];
static void *g_model_stage[4];
static cudaEvent_t g_model_stage_event[4];
static uint64_t g_model_stage_bytes;
static void *g_stream_selected_stage_raw[4];
static void *g_stream_selected_stage[4];
static cudaEvent_t g_stream_selected_stage_event[4];
static uint64_t g_stream_selected_stage_bytes;
static cudaStream_t g_stream_selected_upload_stream;
/* SlimInfer/streaming pipeline: recorded after each layer's expert uploads
 * complete; the compute stream waits it before the FFN kernels read the
 * slot table (replaces the former per-copy cudaStreamSynchronize). */
static cudaEvent_t g_stream_selected_upload_done_event;
/* Recorded after the gate/up copies of a layer complete (the down copies
 * follow on the same stream): the FFN gate/up kernels wait THIS event, so
 * the down-copy DMA overlaps the gate/up compute. */
static cudaEvent_t g_stream_selected_upload_gateup_event;
/* Recorded on the compute stream when a layer's expert load begins; the
 * upload stream waits it before overwriting the slot-table rows, so the
 * NEXT layer's uploads never race the previous layer's in-flight FFN
 * reads (the rebuild path overwrites every row). */
static cudaEvent_t g_stream_selected_compute_done_event;
/* Recorded on the legacy default stream after the routed/shared FFN
 * kernels of a prefill layer (ds4_gpu_record_stream0_ffn_done, called from
 * the layer-major ffn encode right before the hc-expand chain).  The
 * prefill hc-expand kernels run on the decode stream but read the FFN
 * outputs written on the default stream; they wait THIS marker so the
 * cross-stream read is ordered (the un-ordered read sampled mid-write
 * garbage whose pattern shifted with any timing change — the whole-vs-
 * split 281/295 B flip-flops). */
static cudaEvent_t g_stream0_ffn_done_event;

extern "C" void ds4_gpu_record_stream0_ffn_done(void) {
    /* Unconditional drain (FUSION_REPORT ㉑): the pagein epoch leaves an
     * asynchronously-delivered "invalid resource handle" in the sticky queue
     * (delivered by the time this runs); without the drain the next
     * cudaGetLastError consumer — the hc_expand_add_split launch check —
     * misjudges the launch as failed and the batch silently falls back.
     * The certified non-pagein path has a clean queue here, so the drain is
     * a one-call no-op. */
    (void)cudaGetLastError();
    if (getenv("DS4_CUDA_HC_EXPAND_DRAIN")) {
        const cudaError_t pre_err = cudaGetLastError();
        if (pre_err != cudaSuccess) {
            fprintf(stderr, "ds4: ffn_done drain pre-record: %s\n",
                    cudaGetErrorString(pre_err));
            fflush(stderr);
        }
    }
    if (!g_stream0_ffn_done_event) {
        if (cudaEventCreateWithFlags(&g_stream0_ffn_done_event,
                                     cudaEventDisableTiming) != cudaSuccess) {
            (void)cudaGetLastError();
            return;
        }
    }
    (void)cudaEventRecord(g_stream0_ffn_done_event, (cudaStream_t)0);
}
/* Staging rotation must span copy CALLS: each expert copy call used to end
 * with a full stream sync, which made the per-call local rotation safe.
 * With the pipeline event-ized, the rotation index is global so a fresh
 * call never overwrites a stage whose H2D is still in flight. */
static uint64_t g_stream_selected_stage_chunk_idx;

/* ---------------- Predictive expert prefetch (pinned-page registration) ----
 * The expert staging pipeline is HOST-MEMCPY bound (page cache -> pinned
 * stage -> H2D). Prediction: the previous chunk's routed expert set for a
 * layer approximates this chunk's set, so a worker thread pins (cudaHost-
 * Register) the predicted rows of the NEXT layer's mmap pages while the
 * current layer's copies run. A hit in the registered set then goes
 * DIRECTLY to the copy engine (full DMA bandwidth, no host memcpy), hiding
 * ~40-60% of the staging cost. Pinning is page-table work: it runs in
 * parallel with the main thread's memcpy without stealing its bandwidth.
 * DS4_CUDA_PREFETCH_PREDICT=1 enables; DS4_CUDA_PREFETCH_PREDICT_EXPERTS
 * sets the registered-row budget (default 40). */
#define DS4_PF_MAX_LAYERS 256
#define DS4_PF_MAX_IDS 96
#define DS4_PF_REG_EXPERTS 40

typedef struct {
    uint64_t gate_offset, up_offset, down_offset;
    uint64_t gate_expert_bytes, down_expert_bytes;
} ds4_pf_table_info;

static ds4_pf_table_info g_pf_table[DS4_PF_MAX_LAYERS];
static int32_t g_pf_prev_ids[DS4_PF_MAX_LAYERS][DS4_PF_MAX_IDS];
static uint32_t g_pf_prev_count[DS4_PF_MAX_LAYERS];
static uint32_t g_pf_reg_layer = UINT32_MAX;   /* layer the registered set targets */
static uint32_t g_pf_reg_count;
static int32_t  g_pf_reg_ids[DS4_PF_REG_EXPERTS * 3];
static uint64_t g_pf_reg_offs[DS4_PF_REG_EXPERTS * 3];
static uint64_t g_pf_reg_bytes[DS4_PF_REG_EXPERTS * 3];

static std::mutex g_pf_mu;
static std::condition_variable g_pf_cv;
static std::thread g_pf_thread;
static bool g_pf_quit = false;
static uint32_t g_pf_job_layer = UINT32_MAX;   /* pending prefetch target */
static std::atomic<uint32_t> g_pf_hit_count{0};    /* registered-range H2D hits */
static std::atomic<uint32_t> g_pf_miss_count{0};   /* staged-path copies */

static bool ds4_pf_enabled(void) {
    static int cached = -1;
    if (cached < 0) cached = getenv("DS4_CUDA_PREFETCH_PREDICT") != NULL ? 1 : 0;
    return cached == 1;
}

static uint32_t ds4_pf_expert_budget(void) {
    const char *env = getenv("DS4_CUDA_PREFETCH_PREDICT_EXPERTS");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long v = strtoul(env, &end, 10);
        if (end != env && v > 0 && v <= DS4_PF_REG_EXPERTS) return (uint32_t)v;
    }
    return DS4_PF_REG_EXPERTS;
}

static void ds4_pf_unregister_all(void) {
    std::lock_guard<std::mutex> lk(g_pf_mu);
    for (uint32_t i = 0; i < g_pf_reg_count; i++) {
        (void)cudaHostUnregister(
                (void *)((const char *)g_model_fd_host_base + g_pf_reg_offs[i]));
    }
    g_pf_reg_count = 0;
}

static void ds4_pf_thread_main(void) {
    int32_t loc_ids[DS4_PF_REG_EXPERTS * 3];
    uint64_t loc_offs[DS4_PF_REG_EXPERTS * 3];
    uint64_t loc_bytes[DS4_PF_REG_EXPERTS * 3];
    for (;;) {
        uint32_t layer;
        {
            std::unique_lock<std::mutex> lk(g_pf_mu);
            g_pf_cv.wait(lk, [] {
                return g_pf_job_layer != UINT32_MAX || g_pf_quit;
            });
            if (g_pf_quit) return;
            layer = g_pf_job_layer;
            g_pf_job_layer = UINT32_MAX;
        }
        if (layer >= DS4_PF_MAX_LAYERS || g_pf_prev_count[layer] == 0 ||
            g_model_fd_host_base == NULL) {
            continue;
        }
        /* Drain uploads before unregistering ranges a DMA may still read. */
        if (g_stream_selected_upload_stream != NULL) {
            (void)cudaStreamSynchronize(g_stream_selected_upload_stream);
            (void)cudaGetLastError();
        }
        ds4_pf_unregister_all();
        const ds4_pf_table_info *t = &g_pf_table[layer];
        if (t->gate_expert_bytes == 0 || t->down_expert_bytes == 0) continue;
        const uint32_t budget = ds4_pf_expert_budget();
        uint32_t n = 0;
        for (uint32_t i = 0;
             i < g_pf_prev_count[layer] && n < budget; i++) {
            const int32_t eu = g_pf_prev_ids[layer][i];
            if (eu < 0) continue;
            bool dup = false;
            for (uint32_t j = 0; j < n; j++) {
                if (loc_ids[j * 3u] == eu) { dup = true; break; }
            }
            if (dup) continue;
            const uint64_t gate_src =
                t->gate_offset + (uint64_t)eu * t->gate_expert_bytes;
            const uint64_t up_src =
                t->up_offset + (uint64_t)eu * t->gate_expert_bytes;
            const uint64_t down_src =
                t->down_offset + (uint64_t)eu * t->down_expert_bytes;
            const char *base = (const char *)g_model_fd_host_base;
            const cudaError_t e1 = cudaHostRegister(
                    (void *)(base + gate_src), (size_t)t->gate_expert_bytes,
                    cudaHostRegisterDefault);
            const cudaError_t e2 = cudaHostRegister(
                    (void *)(base + up_src), (size_t)t->gate_expert_bytes,
                    cudaHostRegisterDefault);
            const cudaError_t e3 = cudaHostRegister(
                    (void *)(base + down_src), (size_t)t->down_expert_bytes,
                    cudaHostRegisterDefault);
            if (e1 != cudaSuccess || e2 != cudaSuccess || e3 != cudaSuccess) {
                if (e1 == cudaSuccess) (void)cudaHostUnregister((void *)(base + gate_src));
                if (e2 == cudaSuccess) (void)cudaHostUnregister((void *)(base + up_src));
                if (e3 == cudaSuccess) (void)cudaHostUnregister((void *)(base + down_src));
                (void)cudaGetLastError();
                break; /* pool pressure: keep what we have */
            }
            const uint32_t b = n * 3u;
            loc_ids[b + 0] = eu;
            loc_offs[b + 0] = gate_src;
            loc_bytes[b + 0] = t->gate_expert_bytes;
            loc_ids[b + 1] = eu;
            loc_offs[b + 1] = up_src;
            loc_bytes[b + 1] = t->gate_expert_bytes;
            loc_ids[b + 2] = eu;
            loc_offs[b + 2] = down_src;
            loc_bytes[b + 2] = t->down_expert_bytes;
            n++;
        }
        {
            std::lock_guard<std::mutex> lk(g_pf_mu);
            memcpy(g_pf_reg_ids, loc_ids, (size_t)n * 3u * sizeof(int32_t));
            memcpy(g_pf_reg_offs, loc_offs, (size_t)n * 3u * sizeof(uint64_t));
            memcpy(g_pf_reg_bytes, loc_bytes, (size_t)n * 3u * sizeof(uint64_t));
            g_pf_reg_count = n * 3u;
            g_pf_reg_layer = layer;
        }
    }
}

/* Hit test: is [offset, offset+bytes) inside a registered pinned range?
 * Returns 1 when the caller may H2D straight from the mmap. */
static int ds4_pf_registered_hit(uint64_t offset, uint64_t bytes) {
    if (!ds4_pf_enabled() || g_pf_reg_count == 0) return 0;
    std::lock_guard<std::mutex> lk(g_pf_mu);
    for (uint32_t i = 0; i < g_pf_reg_count; i++) {
        if (offset >= g_pf_reg_offs[i] &&
            bytes <= g_pf_reg_bytes[i] &&
            offset - g_pf_reg_offs[i] <= g_pf_reg_bytes[i] - bytes) {
            return 1;
        }
    }
    return 0;
}

static void ds4_pf_submit_job(uint32_t layer) {
    if (!ds4_pf_enabled()) return;
    {
        std::lock_guard<std::mutex> lk(g_pf_mu);
        if (!g_pf_thread.joinable()) {
            g_pf_quit = false;
            g_pf_job_layer = UINT32_MAX;
            g_pf_thread = std::thread(ds4_pf_thread_main);
        }
        g_pf_job_layer = layer;
    }
    g_pf_cv.notify_one();
}

static void ds4_pf_shutdown(void) {
    if (!g_pf_thread.joinable()) return;
    {
        std::lock_guard<std::mutex> lk(g_pf_mu);
        g_pf_quit = true;
    }
    g_pf_cv.notify_one();
    g_pf_thread.join();
    if (getenv("DS4_CUDA_PREFETCH_PREDICT_LOG")) {
        const uint32_t h = g_pf_hit_count.load();
        const uint32_t m = g_pf_miss_count.load();
        fprintf(stderr,
                "ds4: expert prefetch stats: registered-hit copies=%u "
                "staged copies=%u hit-rate=%.1f%%\n",
                h, m,
                h + m ? 100.0 * (double)h / (double)(h + m) : 0.0);
    }
}

/* ================= DFC lossless sidecar compression =================
 * Block-wise canonical Huffman (byte symbols, 256 KiB blocks). Sidecar
 * layout: magic(8) | u64 orig_size | u32 block_size | u32 num_blocks |
 * u32 reserved | per-block entries (u32 packed_size, u8 cflag, payload) |
 * u64 index[num_blocks+1] of payload offsets. cflag=1: payload =
 * [256 lens bytes][bitstream]; cflag=0: raw bytes. Blocks that do not
 * shrink are stored raw, so quantized models pass through untouched.
 * Decompression is env-gated (DS4_CUDA_MODEL_DECOMPRESS=1, default OFF);
 * the GGUF file itself is never modified. */
#define DS4_DFC_MAGIC "DS4DFC1\n"
#define DS4_DFC_BLOCK (256u * 1024u)

/* Canonical Huffman from 256 code lengths: encoder code_by_sym[] and
 * decoder slots (slot_sym[] sorted by code, first[]/idx[] per length). */
static void ds4_dfc_derive(const uint8_t lens[256],
                           uint32_t code_by_sym[256],
                           uint32_t first[34], uint32_t idx[34],
                           uint8_t slot_sym[256], uint32_t *slot_count) {
    uint32_t bl[33];
    memset(bl, 0, sizeof(bl));
    uint32_t maxlen = 0;
    for (uint32_t s = 0; s < 256; s++) {
        if (lens[s]) { bl[lens[s]]++; if (lens[s] > maxlen) maxlen = lens[s]; }
    }
    uint32_t code = 0;
    for (uint32_t l = 1; l <= maxlen; l++) {
        code = (code + bl[l - 1u]) << 1u;
        first[l] = code;
    }
    uint32_t next_code[34];
    memcpy(next_code, first, sizeof(next_code));
    memset(idx, 0, sizeof(uint32_t) * 34);
    uint32_t slot = 0;
    for (uint32_t l = 1; l <= maxlen; l++) {
        idx[l] = slot;
        for (uint32_t s = 0; s < 256; s++) {
            if (lens[s] == l) {
                code_by_sym[s] = next_code[l]++;
                slot_sym[slot++] = (uint8_t)s;
            }
        }
    }
    /* counts for lengths above maxlen must read back as exactly 0 */
    for (uint32_t l = maxlen + 1u; l <= 33u; l++) idx[l] = slot;
    *slot_count = slot;
}

/* Huffman length assignment from counts: O(n^2) merge, n <= 256. */
static void ds4_dfc_build_lens(const uint32_t cnt[256], uint8_t lens[256]) {
    uint32_t freq[511], parent[511];
    uint8_t sym_of[256];
    memset(parent, 0, sizeof(parent));
    uint32_t n = 0;
    for (uint32_t s = 0; s < 256; s++) {
        if (cnt[s]) { freq[n] = cnt[s]; sym_of[n] = (uint8_t)s; n++; }
    }
    memset(lens, 0, 256);
    if (n == 0) return;
    if (n == 1) { lens[sym_of[0]] = 1; return; }
    const uint32_t nodes = 2u * n - 1u;
    for (uint32_t i = n; i < nodes; i++) {
        uint32_t m1 = UINT32_MAX, m2 = UINT32_MAX, i1 = 0, i2 = 0;
        for (uint32_t j = 0; j < i; j++) {
            if (parent[j]) continue;
            if (freq[j] < m1) { m2 = m1; i2 = i1; m1 = freq[j]; i1 = j; }
            else if (freq[j] < m2) { m2 = freq[j]; i2 = j; }
        }
        freq[i] = m1 + m2;
        parent[i1] = i + 1u;
        parent[i2] = i + 1u;
    }
    for (uint32_t i = 0; i < n; i++) {
        uint32_t len = 0, node = i;
        while (parent[node]) { len++; node = parent[node] - 1u; }
        lens[sym_of[i]] = (uint8_t)len;
    }
}

static const uint8_t *g_dfc_map = NULL;
static uint64_t g_dfc_map_size = 0;
static uint32_t g_dfc_num_blocks = 0;
static const uint64_t *g_dfc_index = NULL;
static const uint8_t *g_dfc_payload = NULL;

/* Decompress the blocks covering [offset, offset+bytes) into dst (dst must
 * hold `bytes`); returns 1 on success. */
static int ds4_dfc_read_range(uint8_t *dst, uint64_t offset, uint64_t bytes) {
    if (!g_dfc_map || bytes == 0) return 0;
    const uint64_t orig_size = *(const uint64_t *)(g_dfc_map + 8);
    if (offset > orig_size || bytes > orig_size - offset) return 0;
    const uint32_t bs = DS4_DFC_BLOCK;
    uint32_t b0 = (uint32_t)(offset / bs);
    uint32_t b1 = (uint32_t)((offset + bytes - 1u) / bs);
    if (b1 >= g_dfc_num_blocks) b1 = g_dfc_num_blocks - 1u;
    for (uint32_t b = b0; b <= b1; b++) {
        const uint64_t poff = g_dfc_index[b];
        const uint64_t nxt = g_dfc_index[b + 1u];
        if (poff > nxt || nxt > g_dfc_map_size) return 0;
        const uint8_t *ent = g_dfc_payload + poff;
        const uint32_t packed = *(const uint32_t *)ent;
        if (packed < 5u || packed > nxt - poff) return 0;
        const uint8_t cflag = ent[4];
        const uint8_t *data = ent + 5;
        const uint64_t bstart = (uint64_t)b * bs;
        uint64_t blen = orig_size - bstart;
        if (blen > bs) blen = bs;
        uint8_t *bout = dst + (bstart >= offset ? bstart - offset : 0);
        const uint64_t skip = offset > bstart ? offset - bstart : 0;
        /* window of this block that belongs to the requested range */
        const uint64_t rend = (b == b1) ? (offset + bytes - bstart) : blen;
        if (rend > blen) return 0;
        if (cflag) {
            /* decode [256 lens][bitstream] -> block */
            if (packed < 5u + 256u) return 0;
            uint32_t code_by_sym[256], first[34], idx[34], slot_count = 0;
            uint8_t slot_sym[256];
            uint32_t lens[256];
            memcpy(lens, data, 256);
            ds4_dfc_derive((const uint8_t *)lens, code_by_sym, first, idx,
                           slot_sym, &slot_count);
            if (slot_count == 0) return 0;
            const uint8_t *bits = data + 256;
            const uint32_t bitbytes = packed - 5u - 256u;
            uint64_t bitbuf = 0;
            uint32_t bitcnt = 0, bp = 0, out = 0;
            while (out < blen) {
                while (bitcnt < 32 && bp < bitbytes) {
                    bitbuf = (bitbuf << 8) | (uint64_t)bits[bp];
                    bitcnt += 8;
                    bp++;
                }
                if (bitcnt == 0) return 0;
                /* MSB-first packing: the next code is the top l bits */
                uint32_t symbol = 0;
                int found = 0;
                for (uint32_t l = 1; l <= 32 && !found; l++) {
                    const uint32_t cnt_l = idx[l + 1u] - idx[l];
                    if (cnt_l && bitcnt >= l) {
                        const uint32_t code_l = (uint32_t)(
                            (bitbuf >> (bitcnt - l)) & ((1ull << l) - 1ull));
                        if (code_l >= first[l] && code_l - first[l] < cnt_l) {
                            symbol = slot_sym[idx[l] + (code_l - first[l])];
                            bitcnt -= l;
                            found = 1;
                        }
                    }
                }
                if (!found) return 0;
                if (out >= skip && out < rend) {
                    bout[out - skip] = (uint8_t)symbol;
                }
                out++;
            }
        } else {
            if (packed < blen + 5u) return 0;
            memcpy(bout, data + skip, (size_t)(rend - skip));
        }
    }
    return 1;
}

static int ds4_dfc_map_sidecar(const char *model_path);

extern "C" int ds4_dfc_compress_file(const char *in_path, const char *out_path) {
    if (!in_path || !out_path) return 0;
    FILE *fin = fopen(in_path, "rb");
    if (!fin) return 0;
    if (fseeko(fin, 0, SEEK_END) != 0) { fclose(fin); return 0; }
    const uint64_t orig_size = (uint64_t)ftello(fin);
    rewind(fin);
    FILE *fout = fopen(out_path, "wb");
    if (!fout) { fclose(fin); return 0; }
    const uint32_t bs = DS4_DFC_BLOCK;
    const uint32_t num_blocks = (uint32_t)((orig_size + bs - 1u) / bs);
    uint64_t header[2] = { orig_size, 0 };
    uint32_t hdr[3] = { bs, num_blocks, 0 };
    fwrite(DS4_DFC_MAGIC, 1, 8, fout);
    fwrite(header, sizeof(header), 1, fout);
    fwrite(hdr, sizeof(hdr), 1, fout);
    std::vector<uint64_t> index(num_blocks + 1u, 0);
    uint8_t *raw = (uint8_t *)malloc(bs);
    uint8_t *packed = (uint8_t *)malloc(bs + bs / 2u + 1024u);
    if (!raw || !packed) { free(raw); free(packed); fclose(fin); fclose(fout); return 0; }
    uint64_t saved = 0, incompressible = 0;
    for (uint32_t b = 0; b < num_blocks; b++) {
        const uint64_t off = (uint64_t)b * bs;
        uint64_t len = orig_size - off;
        if (len > bs) len = bs;
        if (fread(raw, 1, (size_t)len, fin) != (size_t)len) {
            free(raw); free(packed); fclose(fin); fclose(fout); return 0;
        }
        uint32_t cnt[256];
        memset(cnt, 0, sizeof(cnt));
        for (uint64_t i = 0; i < len; i++) cnt[raw[i]]++;
        uint8_t lens[256];
        ds4_dfc_build_lens(cnt, lens);
        uint32_t maxl = 0;
        for (uint32_t s = 0; s < 256; s++) {
            if (lens[s] > maxl) maxl = lens[s];
        }
        /* pathological tree (needs >32-bit codes): store raw */
        if (maxl > 32) {
            *(uint32_t *)packed = (uint32_t)(len + 5u);
            packed[4] = 0;
            fwrite(packed, 1, 5, fout);
            fwrite(raw, 1, (size_t)len, fout);
            incompressible++;
            index[b + 1u] = (uint64_t)ftello(fout) - 36u;
            continue;
        }
        uint32_t code_by_sym[256], first[34], idx[34], slot_count = 0;
        uint8_t slot_sym[256];
        ds4_dfc_derive(lens, code_by_sym, first, idx, slot_sym, &slot_count);
        /* bound the encoded size before touching the buffer; encode only
         * when the block actually shrinks */
        uint64_t total_bits = 0;
        for (uint32_t s = 0; s < 256; s++) {
            total_bits += (uint64_t)cnt[s] * lens[s];
        }
        const uint32_t enc_size = 5u + 256u + (uint32_t)((total_bits + 7u) / 8u);
        if (enc_size >= len) {
            *(uint32_t *)packed = (uint32_t)(len + 5u);
            packed[4] = 0;
            fwrite(packed, 1, 5, fout);
            fwrite(raw, 1, (size_t)len, fout);
            incompressible++;
            index[b + 1u] = (uint64_t)ftello(fout) - 36u;
            continue;
        }
        /* encode (MSB-first canonical packing) */
        memcpy(packed + 5, lens, 256);
        uint64_t bitbuf = 0;
        uint32_t bitcnt = 0;
        uint32_t ob = 5 + 256;
        for (uint64_t i = 0; i < len; i++) {
            const uint32_t c = code_by_sym[raw[i]];
            const uint32_t l = lens[raw[i]];
            bitbuf = (bitbuf << l) | c;
            bitcnt += l;
            while (bitcnt >= 8) {
                packed[ob++] = (uint8_t)(bitbuf >> (bitcnt - 8));
                bitcnt -= 8;
            }
        }
        if (bitcnt) { packed[ob++] = (uint8_t)(bitbuf << (8 - bitcnt)); }
        const uint32_t packed_size = ob;
        if (packed_size < len) {
            *(uint32_t *)packed = packed_size;
            packed[4] = 1;
            fwrite(packed, 1, packed_size, fout);
            saved += len - packed_size;
        } else {
            *(uint32_t *)packed = (uint32_t)(len + 5u);
            packed[4] = 0;
            fwrite(packed, 1, 5, fout);
            fwrite(raw, 1, (size_t)len, fout);
            incompressible++;
        }
        /* payload-relative offset (36-byte header excluded) */
        index[b + 1u] = (uint64_t)ftello(fout) - 36u;
    }
    fwrite(index.data(), sizeof(uint64_t), num_blocks + 1u, fout);
    fclose(fout);
    /* Optional tool-side roundtrip check (DS4_DFC_VERIFY=1): decode every
     * block through the same path the engine will use and compare. */
    int verify_fail = 0;
    if (getenv("DS4_DFC_VERIFY") != NULL) {
        uint8_t *check = (uint8_t *)malloc(bs);
        if (!check || !ds4_dfc_map_sidecar(in_path)) {
            verify_fail = 1;
        } else {
            for (uint32_t b = 0; b < num_blocks; b++) {
                const uint64_t off = (uint64_t)b * bs;
                uint64_t len = orig_size - off;
                if (len > bs) len = bs;
                if (fseeko(fin, (off_t)off, SEEK_SET) != 0 ||
                    fread(raw, 1, (size_t)len, fin) != (size_t)len ||
                    !ds4_dfc_read_range(check, off, len)) {
                    verify_fail = 1;
                    fprintf(stderr, "ds4: DFC verify FAIL at block %u (read/decode)\n", b);
                    break;
                }
                const uint8_t *a = check, *e2 = raw;
                uint64_t d = 0;
                while (d < len && a[d] == e2[d]) d++;
                if (d != len) {
                    verify_fail = 1;
                    fprintf(stderr,
                            "ds4: DFC verify MISMATCH block %u off %llu: got 0x%02x want 0x%02x (block cflag=%u)\n",
                            b, (unsigned long long)d, a[d], e2[d],
                            g_dfc_payload[g_dfc_index[b] + 4]);
                    break;
                }
            }
        }
        free(check);
        if (!verify_fail) {
            /* engine-path fidelity: random misaligned, cross-block ranges */
            uint8_t *cbuf = (uint8_t *)malloc(2u * bs);
            uint8_t *rbuf = (uint8_t *)malloc(2u * bs);
            if (!cbuf || !rbuf) {
                verify_fail = 1;
            } else {
                for (uint32_t t = 0; t < 64 && !verify_fail; t++) {
                    const uint64_t roff = (uint64_t)rand() % orig_size;
                    const uint64_t rlen =
                        1u + (uint64_t)rand() % (2u * (uint64_t)bs);
                    const uint64_t rbytes =
                        roff + rlen > orig_size ? orig_size - roff : rlen;
                    if (fseeko(fin, (off_t)roff, SEEK_SET) != 0 ||
                        fread(rbuf, 1, (size_t)rbytes, fin) != (size_t)rbytes ||
                        !ds4_dfc_read_range(cbuf, roff, rbytes) ||
                        memcmp(cbuf, rbuf, (size_t)rbytes) != 0) {
                        verify_fail = 1;
                        fprintf(stderr,
                                "ds4: DFC range verify FAIL off %llu len %llu\n",
                                (unsigned long long)roff,
                                (unsigned long long)rbytes);
                    }
                }
            }
            free(cbuf);
            free(rbuf);
            fprintf(stderr, "ds4: DFC range verify %s\n",
                    verify_fail ? "FAILED" : "OK");
        }
        fprintf(stderr, "ds4: DFC verify %s\n", verify_fail ? "FAILED" : "OK");
    }
    free(raw); free(packed);
    fclose(fin);
    fprintf(stderr,
            "ds4: DFC sidecar written: %s (%.2f GiB -> %.2f GiB, %.1f%% kept, %u/%u blocks raw)\n",
            out_path, (double)orig_size / 1073741824.0,
            (double)index[num_blocks] / 1073741824.0,
            100.0 * (double)index[num_blocks] / (double)orig_size,
            incompressible, num_blocks);
    return verify_fail ? 0 : 1;
}

/* Map a sidecar and install the decode globals (no env gate; the public
 * wrapper applies the gate). */
static int ds4_dfc_map_sidecar(const char *model_path) {
    char side[4096];
    if (snprintf(side, sizeof(side), "%s.dfc", model_path) >= (int)sizeof(side)) return 0;
    FILE *f = fopen(side, "rb");
    if (!f) return 0;
    uint8_t magic[8];
    uint64_t h64[2];
    uint32_t h32[3];
    if (fread(magic, 1, 8, f) != 8 || memcmp(magic, DS4_DFC_MAGIC, 8) != 0 ||
        fread(h64, sizeof(h64), 1, f) != 1 ||
        fread(h32, sizeof(h32), 1, f) != 1) {
        fclose(f);
        return 0;
    }
    g_dfc_num_blocks = h32[1];
    if (h32[0] != DS4_DFC_BLOCK || g_dfc_num_blocks == 0) { fclose(f); return 0; }
    fseeko(f, 0, SEEK_END);
    const uint64_t fsize = (uint64_t)ftello(f);
    fclose(f);
    const uint64_t idx_bytes = (uint64_t)(g_dfc_num_blocks + 1u) * 8u;
    if (fsize < 36u + idx_bytes) return 0;
    /* Map the whole sidecar (demand paged, like the model). */
    int fd = open(side, O_RDONLY);
    if (fd < 0) return 0;
    void *m = mmap(NULL, (size_t)fsize, PROT_READ, MAP_SHARED, fd, 0);
    close(fd);
    if (m == MAP_FAILED) return 0;
    g_dfc_map = (const uint8_t *)m;
    g_dfc_map_size = fsize;
    g_dfc_index = (const uint64_t *)(g_dfc_map + fsize - idx_bytes);
    g_dfc_payload = g_dfc_map + 36;
    /* Validate the index (monotonic, ends at index start). */
    for (uint32_t i = 0; i <= g_dfc_num_blocks; i++) {
        if (g_dfc_index[i] > fsize - 36u - idx_bytes) {
            munmap(m, (size_t)fsize);
            g_dfc_map = NULL;
            return 0;
        }
        if (i != 0 && g_dfc_index[i] < g_dfc_index[i - 1u]) {
            munmap(m, (size_t)fsize);
            g_dfc_map = NULL;
            return 0;
        }
    }
    fprintf(stderr,
            "ds4: DFC decompression active (%s, %u blocks, %.2f GiB sidecar)\n",
            side, g_dfc_num_blocks, (double)fsize / 1073741824.0);
    return 1;
}

extern "C" int ds4_gpu_set_model_dfc(const char *model_path) {
    /* Default OFF: requires DS4_CUDA_MODEL_DECOMPRESS=1 AND the sidecar. */
    if (getenv("DS4_CUDA_MODEL_DECOMPRESS") == NULL || !model_path) return 0;
    return ds4_dfc_map_sidecar(model_path);
}

