__global__ static void head_rms_norm_kernel(float *x, uint32_t n_tok, uint32_t n_head, uint32_t head_dim, float eps) {
    uint32_t row = blockIdx.x;
    if (row >= n_tok * n_head) return;
    float *xr = x + (uint64_t)row * head_dim;
    float sum = 0.0f;
    for (uint32_t i = threadIdx.x; i < head_dim; i += blockDim.x) {
        float v = xr[i];
        sum += v * v;
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    float scale = rsqrtf(partial[0] / (float)head_dim + eps);
    for (uint32_t i = threadIdx.x; i < head_dim; i += blockDim.x) xr[i] *= scale;
}

__device__ static float rope_yarn_ramp_dev(float low, float high, int i0);

__global__ static void dsv4_qkv_rms_norm_rows_kv_rope_kernel(
        float *q_out,
        const float *q,
        const float *q_w,
        uint32_t q_n,
        float *kv_out,
        const float *kv,
        const float *kv_w,
        uint32_t kv_n,
        uint32_t rows,
        uint32_t kv_n_head,
        uint32_t kv_head_dim,
        uint32_t n_rot,
        uint32_t pos0,
        uint32_t n_ctx_orig,
        int inverse,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow,
        float eps) {
    const uint32_t row = blockIdx.x;
    const uint32_t which = blockIdx.y;
    if (row >= rows || which > 1u) return;
    const uint32_t n = which == 0u ? q_n : kv_n;
    const float *xr = (which == 0u ? q : kv) + (uint64_t)row * n;
    float *orow = (which == 0u ? q_out : kv_out) + (uint64_t)row * n;
    const float *w = which == 0u ? q_w : kv_w;
    float sum = 0.0f;
    for (uint32_t i = threadIdx.x; i < n; i += blockDim.x) {
        const float v = xr[i];
        sum += v * v;
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    const float scale = rsqrtf(partial[0] / (float)n + eps);
    if (which == 0u) {
        for (uint32_t i = threadIdx.x; i < n; i += blockDim.x) {
            orow[i] = xr[i] * scale * w[i];
        }
        return;
    }

    const uint32_t n_nope = kv_head_dim - n_rot;
    for (uint32_t h = 0; h < kv_n_head; h++) {
        const uint32_t head_base = h * kv_head_dim;
        for (uint32_t d = threadIdx.x; d < n_nope; d += blockDim.x) {
            const uint32_t i = head_base + d;
            orow[i] = xr[i] * scale * w[i];
        }
    }

    float corr0 = 0.0f, corr1 = 0.0f;
    if (ext_factor != 0.0f) {
        float denom = 2.0f * logf(freq_base);
        corr0 = floorf((float)n_rot * logf((float)n_ctx_orig / (beta_fast * 2.0f * (float)M_PI)) / denom);
        corr1 = ceilf((float)n_rot * logf((float)n_ctx_orig / (beta_slow * 2.0f * (float)M_PI)) / denom);
        corr0 = fmaxf(0.0f, corr0);
        corr1 = fminf((float)(n_rot - 1), corr1);
    }
    const uint32_t pairs_per_head = n_rot / 2u;
    const uint32_t total_pairs = kv_n_head * pairs_per_head;
    for (uint32_t p = threadIdx.x; p < total_pairs; p += blockDim.x) {
        const uint32_t h = p / pairs_per_head;
        const uint32_t pair = p - h * pairs_per_head;
        const uint32_t d = n_nope + pair * 2u;
        const uint32_t i0 = h * kv_head_dim + d;
        const uint32_t i = pair * 2u;
        float theta_extrap = (float)(pos0 + row) * powf(freq_base, -((float)i) / (float)n_rot);
        float theta_interp = freq_scale * theta_extrap;
        float theta = theta_interp;
        float mscale = attn_factor;
        if (ext_factor != 0.0f) {
            float ramp_mix = rope_yarn_ramp_dev(corr0, corr1, (int)i) * ext_factor;
            theta = theta_interp * (1.0f - ramp_mix) + theta_extrap * ramp_mix;
            mscale *= 1.0f + 0.1f * logf(1.0f / freq_scale);
        }
        float c = cosf(theta) * mscale;
        float s = sinf(theta) * mscale;
        if (inverse) s = -s;
        const float x0 = xr[i0] * scale * w[i0];
        const float x1 = xr[i0 + 1u] * scale * w[i0 + 1u];
        orow[i0] = x0 * c - x1 * s;
        orow[i0 + 1u] = x0 * s + x1 * c;
    }
}

__global__ static void head_rms_norm_rope_tail_kernel(
        float *x,
        uint32_t n_tok,
        uint32_t n_head,
        uint32_t head_dim,
        uint32_t n_rot,
        uint32_t pos0,
        uint32_t n_ctx_orig,
        int inverse,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow,
        float eps) {
    uint32_t row = blockIdx.x;
    if (row >= n_tok * n_head) return;
    uint32_t t = row / n_head;
    float *xr = x + (uint64_t)row * head_dim;
    float sum = 0.0f;
    for (uint32_t i = threadIdx.x; i < head_dim; i += blockDim.x) {
        float v = xr[i];
        sum += v * v;
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    const float scale = rsqrtf(partial[0] / (float)head_dim + eps);
    const uint32_t n_nope = head_dim - n_rot;
    for (uint32_t i = threadIdx.x; i < n_nope; i += blockDim.x) {
        xr[i] *= scale;
    }

    float corr0 = 0.0f, corr1 = 0.0f;
    if (ext_factor != 0.0f) {
        float denom = 2.0f * logf(freq_base);
        corr0 = floorf((float)n_rot * logf((float)n_ctx_orig / (beta_fast * 2.0f * (float)M_PI)) / denom);
        corr1 = ceilf((float)n_rot * logf((float)n_ctx_orig / (beta_slow * 2.0f * (float)M_PI)) / denom);
        corr0 = fmaxf(0.0f, corr0);
        corr1 = fminf((float)(n_rot - 1), corr1);
    }
    for (uint32_t pair = threadIdx.x; pair < n_rot / 2; pair += blockDim.x) {
        uint32_t i = pair * 2u;
        float theta_extrap = (float)(pos0 + t) * powf(freq_base, -((float)i) / (float)n_rot);
        float theta_interp = freq_scale * theta_extrap;
        float theta = theta_interp;
        float mscale = attn_factor;
        if (ext_factor != 0.0f) {
            float ramp_mix = rope_yarn_ramp_dev(corr0, corr1, (int)i) * ext_factor;
            theta = theta_interp * (1.0f - ramp_mix) + theta_extrap * ramp_mix;
            mscale *= 1.0f + 0.1f * logf(1.0f / freq_scale);
        }
        float c = cosf(theta) * mscale;
        float s = sinf(theta) * mscale;
        if (inverse) s = -s;
        float *tail = xr + n_nope;
        float x0 = tail[i] * scale;
        float x1 = tail[i + 1] * scale;
        tail[i] = x0 * c - x1 * s;
        tail[i + 1] = x0 * s + x1 * c;
    }
}

__device__ static float rope_yarn_ramp_dev(float low, float high, int i0) {
    float y = ((float)(i0 / 2) - low) / fmaxf(0.001f, high - low);
    return 1.0f - fminf(1.0f, fmaxf(0.0f, y));
}

__global__ static void rope_tail_kernel(
        float *x,
        uint32_t n_tok,
        uint32_t n_head,
        uint32_t head_dim,
        uint32_t n_rot,
        uint32_t pos0,
        uint32_t pos_stride,
        uint32_t n_ctx_orig,
        int inverse,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow) {
    uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
    uint32_t pairs = n_tok * n_head * (n_rot / 2);
    if (gid >= pairs) return;
    uint32_t pair = gid % (n_rot / 2);
    uint32_t tmp = gid / (n_rot / 2);
    uint32_t h = tmp % n_head;
    uint32_t t = tmp / n_head;
    uint32_t n_nope = head_dim - n_rot;
    uint32_t i = pair * 2;

    float corr0 = 0.0f, corr1 = 0.0f;
    if (ext_factor != 0.0f) {
        float denom = 2.0f * logf(freq_base);
        corr0 = floorf((float)n_rot * logf((float)n_ctx_orig / (beta_fast * 2.0f * (float)M_PI)) / denom);
        corr1 = ceilf((float)n_rot * logf((float)n_ctx_orig / (beta_slow * 2.0f * (float)M_PI)) / denom);
        corr0 = fmaxf(0.0f, corr0);
        corr1 = fminf((float)(n_rot - 1), corr1);
    }

    float theta_extrap = (float)(pos0 + t * pos_stride) * powf(freq_base, -((float)i) / (float)n_rot);
    float theta_interp = freq_scale * theta_extrap;
    float theta = theta_interp;
    float mscale = attn_factor;
    if (ext_factor != 0.0f) {
        float ramp_mix = rope_yarn_ramp_dev(corr0, corr1, (int)i) * ext_factor;
        theta = theta_interp * (1.0f - ramp_mix) + theta_extrap * ramp_mix;
        mscale *= 1.0f + 0.1f * logf(1.0f / freq_scale);
    }
    float c = cosf(theta) * mscale;
    float s = sinf(theta) * mscale;
    if (inverse) s = -s;

    float *tail = x + ((uint64_t)t * n_head + h) * head_dim + n_nope;
    float x0 = tail[i];
    float x1 = tail[i + 1];
    tail[i] = x0 * c - x1 * s;
    tail[i + 1] = x0 * s + x1 * c;
}

__global__ static void rope_tail_decode_rows_kernel(
        float *x,
        cuda_attention_decode_row_table rows,
        uint32_t n_rows,
        uint32_t n_head,
        uint32_t head_dim,
        uint32_t n_rot,
        uint32_t n_ctx_orig,
        int inverse,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow) {
    const uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
    const uint32_t pairs = n_rows * n_head * (n_rot / 2u);
    if (gid >= pairs) return;
    const uint32_t pair = gid % (n_rot / 2u);
    const uint32_t tmp = gid / (n_rot / 2u);
    const uint32_t h = tmp % n_head;
    const uint32_t row = tmp / n_head;
    const uint32_t n_nope = head_dim - n_rot;
    const uint32_t i = pair * 2u;

    float corr0 = 0.0f, corr1 = 0.0f;
    if (ext_factor != 0.0f) {
        const float denom = 2.0f * logf(freq_base);
        corr0 = floorf((float)n_rot *
                       logf((float)n_ctx_orig /
                            (beta_fast * 2.0f * (float)M_PI)) / denom);
        corr1 = ceilf((float)n_rot *
                      logf((float)n_ctx_orig /
                           (beta_slow * 2.0f * (float)M_PI)) / denom);
        corr0 = fmaxf(0.0f, corr0);
        corr1 = fminf((float)(n_rot - 1u), corr1);
    }

    const float theta_extrap = (float)rows.row[row].pos *
        powf(freq_base, -((float)i) / (float)n_rot);
    const float theta_interp = freq_scale * theta_extrap;
    float theta = theta_interp;
    float mscale = attn_factor;
    if (ext_factor != 0.0f) {
        const float ramp_mix =
            rope_yarn_ramp_dev(corr0, corr1, (int)i) * ext_factor;
        theta = theta_interp * (1.0f - ramp_mix) + theta_extrap * ramp_mix;
        mscale *= 1.0f + 0.1f * logf(1.0f / freq_scale);
    }
    const float c = cosf(theta) * mscale;
    float s = sinf(theta) * mscale;
    if (inverse) s = -s;

    float *tail = x + ((uint64_t)row * n_head + h) * head_dim + n_nope;
    const float x0 = tail[i];
    const float x1 = tail[i + 1u];
    tail[i] = x0 * c - x1 * s;
    tail[i + 1u] = x0 * s + x1 * c;
}

__device__ static float dsv4_e4m3fn_value_dev(int i) {
    int exp = (i >> 3) & 15;
    int mant = i & 7;
    if (exp == 0) return (float)mant * 0.001953125f;
    return (1.0f + (float)mant * 0.125f) * exp2f((float)exp - 7.0f);
}

__device__ static float dsv4_e4m3fn_dequant_dev(float x) {
    float sign = x < 0.0f ? -1.0f : 1.0f;
    float ax = fminf(fabsf(x), 448.0f);
    int lo = 0, hi = 126;
    while (lo < hi) {
        int mid = (lo + hi + 1) >> 1;
        if (dsv4_e4m3fn_value_dev(mid) <= ax) lo = mid;
        else hi = mid - 1;
    }
    int best = lo;
    if (best < 126) {
        float bd = fabsf(ax - dsv4_e4m3fn_value_dev(best));
        float nd = fabsf(ax - dsv4_e4m3fn_value_dev(best + 1));
        if (nd < bd || (nd == bd && (((best + 1) & 1) == 0) && ((best & 1) != 0))) best++;
    }
    return sign * dsv4_e4m3fn_value_dev(best);
}

__device__ static float dsv4_e2m1fn_value_dev(int i) {
    switch (i & 7) {
    case 0: return 0.0f;
    case 1: return 0.5f;
    case 2: return 1.0f;
    case 3: return 1.5f;
    case 4: return 2.0f;
    case 5: return 3.0f;
    case 6: return 4.0f;
    default: return 6.0f;
    }
}

__device__ static float dsv4_e2m1fn_dequant_dev(float x) {
    float sign = x < 0.0f ? -1.0f : 1.0f;
    float ax = fminf(fabsf(x), 6.0f);
    int best = 0;
    float best_diff = fabsf(ax - dsv4_e2m1fn_value_dev(0));
    for (int i = 1; i < 8; i++) {
        float diff = fabsf(ax - dsv4_e2m1fn_value_dev(i));
        if (diff < best_diff || (diff == best_diff && ((i & 1) == 0) && ((best & 1) != 0))) {
            best = i;
            best_diff = diff;
        }
    }
    return sign * dsv4_e2m1fn_value_dev(best);
}

__device__ static float model_scalar_dev(const void *base, uint64_t offset, uint32_t type, uint64_t idx) {
    const char *p = (const char *)base + offset;
    if (type == 1u) return __half2float(((const __half *)p)[idx]);
    return ((const float *)p)[idx];
}

__device__ static float rope_yarn_ramp_cpu_equiv_dev(float low, float high, int i0) {
    float y = ((float)(i0 / 2) - low) / fmaxf(0.001f, high - low);
    return 1.0f - fminf(1.0f, fmaxf(0.0f, y));
}

__device__ static DS4_CUDA_UNUSED void rope_tail_one_dev(float *x, uint32_t head_dim, uint32_t n_rot, uint32_t pos, uint32_t n_ctx_orig, float freq_base, float freq_scale, float ext_factor, float attn_factor, float beta_fast, float beta_slow) {
    uint32_t n_nope = head_dim - n_rot;
    float corr0 = 0.0f, corr1 = 0.0f;
    if (ext_factor != 0.0f) {
        float denom = 2.0f * logf(freq_base);
        corr0 = fmaxf(0.0f, floorf((float)n_rot * logf((float)n_ctx_orig / (beta_fast * 2.0f * (float)M_PI)) / denom));
        corr1 = fminf((float)(n_rot - 1), ceilf((float)n_rot * logf((float)n_ctx_orig / (beta_slow * 2.0f * (float)M_PI)) / denom));
    }
    for (uint32_t i = 0; i < n_rot; i += 2) {
        float theta_extrap = (float)pos * powf(freq_base, -((float)i) / (float)n_rot);
        float theta_interp = freq_scale * theta_extrap;
        float theta = theta_interp;
        float mscale = attn_factor;
        if (ext_factor != 0.0f) {
            float mix = rope_yarn_ramp_cpu_equiv_dev(corr0, corr1, (int)i) * ext_factor;
            theta = theta_interp * (1.0f - mix) + theta_extrap * mix;
            mscale *= 1.0f + 0.1f * logf(1.0f / freq_scale);
        }
        float c = cosf(theta) * mscale;
        float s = sinf(theta) * mscale;
        float x0 = x[n_nope + i];
        float x1 = x[n_nope + i + 1];
        x[n_nope + i] = x0 * c - x1 * s;
        x[n_nope + i + 1] = x0 * s + x1 * c;
    }
}

__device__ static void fp8_kv_quantize_row(
        float    *xr,
        uint32_t  head_dim,
        uint32_t  n_rot,
        float    *scratch) {
    uint32_t tid = threadIdx.x;
    uint32_t n_nope = head_dim - n_rot;
    for (uint32_t off = 0; off < n_nope; off += 64) {
        float v = 0.0f;
        if (off + tid < n_nope) v = xr[off + tid];
        scratch[tid] = off + tid < n_nope ? fabsf(v) : 0.0f;
        __syncthreads();
        for (uint32_t stride = 32; stride > 0; stride >>= 1) {
            if (tid < stride) scratch[tid] = fmaxf(scratch[tid], scratch[tid + stride]);
            __syncthreads();
        }
        float scale = exp2f(ceilf(log2f(fmaxf(scratch[0], 1.0e-4f) / 448.0f)));
        if (off + tid < n_nope) {
            float q = dsv4_e4m3fn_dequant_dev(fminf(448.0f, fmaxf(-448.0f, v / scale))) * scale;
            xr[off + tid] = q;
        }
        __syncthreads();
    }
}

__global__ static void fp8_kv_quantize_kernel(
        float    *x,
        uint32_t  n_tok,
        uint32_t  head_dim,
        uint32_t  n_rot) {
    uint32_t row = blockIdx.x;
    if (row >= n_tok) return;
    __shared__ float scratch[64];
    fp8_kv_quantize_row(
            x + (uint64_t)row * head_dim, head_dim, n_rot, scratch);
}

__global__ static void fp8_kv_quantize_store_rows_kernel(
        float                           *x,
        cuda_attention_decode_row_table  rows,
        uint32_t                         n_rows,
        uint32_t                         head_dim,
        uint32_t                         n_rot) {
    const uint32_t row = blockIdx.x;
    if (row >= n_rows) return;
    __shared__ float scratch[64];
    float *xr = x + (uint64_t)row * head_dim;
    fp8_kv_quantize_row(xr, head_dim, n_rot, scratch);

    const ds4_gpu_attention_decode_row dsc = rows.row[row];
    float *raw = (float *)(uintptr_t)dsc.raw_kv;
    for (uint32_t d = threadIdx.x; d < head_dim; d += blockDim.x) {
        raw[(uint64_t)dsc.raw_start * head_dim + d] =
            __half2float(__float2half(xr[d]));
    }
}

__global__ static void indexer_hadamard_fp4_kernel(float *x, uint32_t n_rows, uint32_t head_dim) {
    uint32_t row = blockIdx.x;
    uint32_t tid = threadIdx.x;
    if (row >= n_rows || head_dim != 128u || tid >= 128u) return;

    __shared__ float vals[128];
    __shared__ float absbuf[128];
    float *xr = x + (uint64_t)row * head_dim;
    vals[tid] = xr[tid];
    __syncthreads();

    for (uint32_t stride = 1u; stride < 128u; stride <<= 1u) {
        if ((tid & stride) == 0u) {
            uint32_t base = (tid & ~(2u * stride - 1u)) + (tid & (stride - 1u));
            float a = vals[base];
            float b = vals[base + stride];
            vals[base] = a + b;
            vals[base + stride] = a - b;
        }
        __syncthreads();
    }

    float v = vals[tid] * 0.08838834764831845f;
    uint32_t fp4_block = tid >> 5u;
    uint32_t lane = tid & 31u;
    uint32_t block_base = fp4_block * 32u;
    absbuf[tid] = fabsf(v);
    __syncthreads();

    for (uint32_t stride = 16u; stride > 0u; stride >>= 1u) {
        if (lane < stride) {
            absbuf[block_base + lane] = fmaxf(absbuf[block_base + lane],
                                              absbuf[block_base + lane + stride]);
        }
        __syncthreads();
    }

    float amax = fmaxf(absbuf[block_base], 7.052966104933725e-38f);
    float scale = exp2f(ceilf(log2f(amax / 6.0f)));
    xr[tid] = dsv4_e2m1fn_dequant_dev(fminf(6.0f, fmaxf(-6.0f, v / scale))) * scale;
}

/* DS4_CUDA_KV_BITQ (⑦ 阶段 1, FUSION_REPORT ㉑十续): per-16-channel-group KV
 * quantization for the raw attention ring.  Per-row independent (chunk-
 * invariant determinism); packed row = 32 f32 group scales + 512 x BITS
 * signed-symmetric codes (BITS=4:384B, 5:448B, 6:512B, 8:640B vs 2048B f32;
 * 5.3x at 4-bit).  DS4_CUDA_KV_BITQ_BITS selects the code width (default 4).
 * LOSSY: the dequantized KV differs from the FP32 ring, so the attention
 * family changes -- a new canonical requires whole==split + repeat
 * certification (the default path is untouched).
 *
 * DS4_CUDA_KV_BITQ_AUTO (startup bit-width scheduler, decided in ds4.c):
 * when active, these getters return the settled profile instead of reading
 * envs; manual bitq envs keep the legacy env semantics. */
extern "C" int ds4_kv_bitq_auto_active(void);
extern "C" int ds4_kv_bitq_auto_enabled(void);
extern "C" int ds4_kv_bitq_auto_raw_bits(void);
extern "C" int ds4_kv_bitq_auto_comp_bits(void);
extern "C" int ds4_kv_bitq_auto_idx_bits(void);

static int kv_bitq_bits(void) {
    if (ds4_kv_bitq_auto_active()) return ds4_kv_bitq_auto_raw_bits();
    static int bits = -1;
    if (bits < 0) {
        bits = 4;
        const char *env = getenv("DS4_CUDA_KV_BITQ_BITS");
        if (env && env[0]) {
            char *end = NULL;
            long v = strtol(env, &end, 10);
            if (end != env && *end == '\0' && v >= 2 && v <= 8) bits = (int)v;
        }
    }
    return bits;
}

/* 分缓存位数 (bitq quality campaign): per-cache env overrides fall back
 * to the global DS4_CUDA_KV_BITQ_BITS, mirroring the ds4.c readers. */
static int kv_bitq_cache_bits(const char *envname) {
    const char *env = getenv(envname);
    if (env && env[0]) {
        char *end = NULL;
        long v = strtol(env, &end, 10);
        if (end != env && *end == '\0' && v >= 2 && v <= 8) return (int)v;
    }
    return kv_bitq_bits();
}
static int kv_bitq_raw_bits(void) {
    if (ds4_kv_bitq_auto_active()) return ds4_kv_bitq_auto_raw_bits();
    return kv_bitq_cache_bits("DS4_CUDA_KV_BITQ_RAW_BITS");
}
static int kv_bitq_comp_bits(void) {
    if (ds4_kv_bitq_auto_active()) return ds4_kv_bitq_auto_comp_bits();
    return kv_bitq_cache_bits("DS4_CUDA_KV_BITQ_COMP_BITS");
}
static int kv_bitq_idx_bits(void) {
    if (ds4_kv_bitq_auto_active()) return ds4_kv_bitq_auto_idx_bits();
    return kv_bitq_cache_bits("DS4_CUDA_KV_BITQ_IDX_BITS");
}

static int kv_bitq_on(void) {
    if (ds4_kv_bitq_auto_active()) return ds4_kv_bitq_auto_enabled();
    static int on = -1;
    if (on < 0) on = getenv("DS4_CUDA_KV_BITQ") != NULL ? 1 : 0;
    return on;
}

/* ⑦ 阶段 4: the attention-compressed cache (512-dim f32 rows, append-only)
 * gets the same per-row pack under its own env so it composes with the raw
 * ring quantization or stands alone. */
static int kv_bitq_comp_on(void) {
    if (ds4_kv_bitq_auto_active()) return ds4_kv_bitq_auto_enabled();
    static int on = -1;
    if (on < 0) on = getenv("DS4_CUDA_KV_BITQ_COMP") != NULL ? 1 : 0;
    return on;
}

static __host__ __device__ inline uint32_t kv_bitq_row_bytes(uint32_t head_dim, int bits) {
    /* 32 x 4B scales + (512 x bits)/8 code bytes (per 512-dim row). */
    return (head_dim / 16u) * 4u + (head_dim / 8u) * (uint32_t)bits;
}

/* Ring byte-capacity check that follows the packed stride under the env
 * (stage 2: the ring is now ALLOCATED at row_bytes per row). */
static inline bool kv_ring_bytes_ok(const ds4_gpu_tensor *t,
        uint32_t raw_cap, uint32_t head_dim) {
    if (!t) return false;
    if (kv_bitq_on()) {
        return t->bytes >=
               (uint64_t)raw_cap * kv_bitq_row_bytes(head_dim, kv_bitq_raw_bits());
    }
    return t->bytes >= (uint64_t)raw_cap * head_dim * sizeof(float);
}

/* Comp-cache capacity check that follows the packed stride under
 * DS4_CUDA_KV_BITQ_COMP. */
static inline bool kv_comp_bytes_ok(const ds4_gpu_tensor *t,
        uint32_t cap, uint32_t head_dim) {
    if (!t) return false;
    if (kv_bitq_comp_on()) {
        return t->bytes >=
               (uint64_t)cap * kv_bitq_row_bytes(head_dim, kv_bitq_comp_bits());
    }
    return t->bytes >= (uint64_t)cap * head_dim * sizeof(float);
}

static __device__ __forceinline__ void kv_bitq_pack_row(
        unsigned char *dst, const float *src, uint32_t head_dim, int bits) {
    const int max_code = (1 << (bits - 1)) - 1;
    const uint32_t group_bytes = (16u * (uint32_t)bits) / 8u;
    for (uint32_t g = 0; g < head_dim / 16u; g++) {
        float mx = 0.0f;
        for (uint32_t c = 0; c < 16u; c++) {
            const float a = fabsf(src[g * 16u + c]);
            if (a > mx) mx = a;
        }
        const float scale = mx / (float)max_code;
        *(float *)(dst + g * 4u) = scale;
        unsigned char *pack = dst + (head_dim / 16u) * 4u + g * group_bytes;
        for (uint32_t i = 0; i < group_bytes; i++) pack[i] = 0;
        for (uint32_t c = 0; c < 16u; c++) {
            float v = src[g * 16u + c];
            int code = (int)roundf(v / (scale > 0.0f ? scale : 1.0f));
            if (code > max_code) code = max_code;
            if (code < -max_code) code = -max_code;
            const uint32_t u = (uint32_t)code & ((1u << bits) - 1u);
            const uint32_t bitpos = c * (uint32_t)bits;
            const uint32_t byte = bitpos >> 3u;
            const uint32_t shift = bitpos & 7u;
            pack[byte] |= (unsigned char)(u << shift);
            if (shift + (uint32_t)bits > 8u) {
                pack[byte + 1u] |= (unsigned char)(u >> (8u - shift));
            }
        }
    }
}

/* Decode-store variant: the certified decode ring rows are F16-rounded
 * (fp8_kv_quantize_store_rows_kernel writes half-rounded floats), so the
 * bitq pack must round to F16 first to keep the same canonical values. */
static __device__ __forceinline__ void kv_bitq_pack_row_f16(
        unsigned char *dst, const float *src, uint32_t head_dim, int bits) {
    const int max_code = (1 << (bits - 1)) - 1;
    const uint32_t group_bytes = (16u * (uint32_t)bits) / 8u;
    for (uint32_t g = 0; g < head_dim / 16u; g++) {
        float v16[16];
        float mx = 0.0f;
        for (uint32_t c = 0; c < 16u; c++) {
            v16[c] = __half2float(__float2half(src[g * 16u + c]));
            const float a = fabsf(v16[c]);
            if (a > mx) mx = a;
        }
        const float scale = mx / (float)max_code;
        *(float *)(dst + g * 4u) = scale;
        unsigned char *pack = dst + (head_dim / 16u) * 4u + g * group_bytes;
        for (uint32_t i = 0; i < group_bytes; i++) pack[i] = 0;
        for (uint32_t c = 0; c < 16u; c++) {
            int code = (int)roundf(v16[c] / (scale > 0.0f ? scale : 1.0f));
            if (code > max_code) code = max_code;
            if (code < -max_code) code = -max_code;
            const uint32_t u = (uint32_t)code & ((1u << bits) - 1u);
            const uint32_t bitpos = c * (uint32_t)bits;
            const uint32_t byte = bitpos >> 3u;
            const uint32_t shift = bitpos & 7u;
            pack[byte] |= (unsigned char)(u << shift);
            if (shift + (uint32_t)bits > 8u) {
                pack[byte + 1u] |= (unsigned char)(u >> (8u - shift));
            }
        }
    }
}

static __device__ __forceinline__ float kv_bitq_unpack_elem(
        const unsigned char *row, uint32_t head_dim, uint32_t c, int bits) {
    const uint32_t g = c / 16u;
    const float scale = *(const float *)(row + g * 4u);
    const unsigned char *pack = row + (head_dim / 16u) * 4u +
            g * ((16u * (uint32_t)bits) / 8u);
    const uint32_t bitpos = (c & 15u) * (uint32_t)bits;
    const uint32_t byte = bitpos >> 3u;
    const uint32_t shift = bitpos & 7u;
    uint32_t u = pack[byte] >> shift;
    if (shift + (uint32_t)bits > 8u) {
        u |= (uint32_t)pack[byte + 1u] << (8u - shift);
    }
    u &= (1u << bits) - 1u;
    int code = (int)u;
    const int max_code = (1 << (bits - 1)) - 1;
    if (code > max_code) code -= 1 << bits;
    return (float)code * scale;
}

__global__ static void store_raw_kv_bitq_batch_kernel(
        unsigned char *raw, const float *kv, uint32_t raw_cap,
        uint32_t pos0, uint32_t n_tokens, uint32_t head_dim, int bits) {
    const uint32_t t = blockIdx.x * blockDim.x + threadIdx.x;
    if (t >= n_tokens) return;
    const uint32_t row = (pos0 + t) % raw_cap;
    kv_bitq_pack_row(raw + (uint64_t)row * kv_bitq_row_bytes(head_dim, bits),
                     kv + (uint64_t)t * head_dim, head_dim, bits);
}

/* DS4_CUDA_KV_BITQ decode-store variant of fp8_kv_quantize_store_rows_kernel:
 * same FP8 non-RoPE round trip + F16 rounding as the certified decode ring
 * rows, then packed into the ring (row offset = raw_start * row_bytes). */
__global__ static void fp8_kv_bitq_store_rows_kernel(
        float                           *x,
        cuda_attention_decode_row_table  rows,
        uint32_t                         n_rows,
        uint32_t                         head_dim,
        uint32_t                         n_rot,
        int                              bits) {
    const uint32_t row = blockIdx.x;
    if (row >= n_rows) return;
    __shared__ float scratch[64];
    float *xr = x + (uint64_t)row * head_dim;
    fp8_kv_quantize_row(xr, head_dim, n_rot, scratch);

    const ds4_gpu_attention_decode_row dsc = rows.row[row];
    unsigned char *raw = (unsigned char *)(uintptr_t)dsc.raw_kv;
    if (threadIdx.x == 0u) {
        kv_bitq_pack_row_f16(raw + (uint64_t)dsc.raw_start *
                kv_bitq_row_bytes(head_dim, bits), xr, head_dim, bits);
    }
}

/* DS4_CUDA_KV_BITQ: dequant gather of a wrapped raw span
 * [raw_start, raw_start + n_raw) of the bitq ring into a contiguous FP32
 * buffer (ascending absolute order: dst[r] = ring[(raw_start + r) % raw_cap]).
 * Every ring consumer indexes rows as (raw_start + idx) % raw_cap, so running
 * the existing kernels with raw_start' = 0, raw_cap' = n_raw over the temp
 * reproduces the same rows in the same order. */
__global__ static void attention_raw_gather_window_bitq_kernel(
        float *dst, const unsigned char *ring,
        uint32_t raw_cap, uint32_t phys_start, uint32_t n_raw,
        uint32_t head_dim, int bits) {
    const uint32_t n = n_raw * head_dim;
    const uint32_t row_bytes = kv_bitq_row_bytes(head_dim, bits);
    for (uint32_t i = blockIdx.x * blockDim.x + threadIdx.x; i < n;
         i += blockDim.x * gridDim.x) {
        const uint32_t row = i / head_dim;
        const uint32_t col = i % head_dim;
        const uint32_t phys = (phys_start + row) % raw_cap;
        dst[i] = kv_bitq_unpack_elem(
                ring + (uint64_t)phys * row_bytes, head_dim, col, bits);
    }
}

/* Dedicated dequant gather buffer.  The gather temp must NOT live in the
 * shared tmp slab: decode launches (exact score split) allocate slab temps
 * AFTER the gather, which would clobber the dequantized rows mid-flight.
 * Grows on demand; freed in ds4_gpu_cleanup. */
static float *attention_bitq_gather_span(const ds4_gpu_tensor *ring,
        uint32_t raw_cap, uint32_t raw_start, uint32_t n_raw,
        uint32_t head_dim, int logical_tier, const char *tag) {
    (void)logical_tier;
    const uint64_t bytes = (uint64_t)n_raw * head_dim * sizeof(float);
    if (g_bitq_gather_bytes < bytes) {
        if (g_bitq_gather) {
            if (!cuda_ok(cudaDeviceSynchronize(),
                         "synchronize bitq gather growth")) return NULL;
            (void)cudaFree(g_bitq_gather);
            g_bitq_gather = NULL;
            g_bitq_gather_bytes = 0;
        }
        void *p = NULL;
        if (cudaMalloc(&p, (size_t)bytes) != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA bitq gather alloc failed for %s (%.2f MiB)\n",
                    tag ? tag : "?", (double)bytes / 1048576.0);
            (void)cudaGetLastError();
            return NULL;
        }
        g_bitq_gather = p;
        g_bitq_gather_bytes = bytes;
    }
    float *kv = (float *)g_bitq_gather;
    const uint32_t n = n_raw * head_dim;
    attention_raw_gather_window_bitq_kernel<<<(n + 255u) / 256u, 256u>>>(
            kv, (const unsigned char *)ring->ptr, raw_cap, raw_start, n_raw,
            head_dim, kv_bitq_raw_bits());
    if (!cuda_ok(cudaGetLastError(), "attention bitq span gather")) return NULL;
    return kv;
}

/* DS4_CUDA_KV_BITQ: checkpoint payload dump.  The session payload's stable
 * external format is FP32 raw rows in logical order; the bitq ring holds
 * packed rows at row_bytes stride, so dequant rows [first_row,
 * first_row + n_rows) (wrapped) into a host FP32 buffer. */
extern "C" int ds4_gpu_bitq_dequant_rows_dump(
        const ds4_gpu_tensor *ring, uint32_t raw_cap, uint32_t first_row,
        uint32_t n_rows, uint32_t head_dim, int bits, float *dst) {
    if (!ring || !dst || n_rows == 0u || raw_cap == 0u || head_dim == 0u ||
        bits < 2 || bits > 8) {
        return 0;
    }
    const int logical_tier = ds4_tensor_device_idx(ring);
    const uint64_t bytes = (uint64_t)n_rows * head_dim * sizeof(float);
    float *dev = (float *)cuda_tmp_alloc_on(logical_tier, bytes,
                                            "bitq dequant dump");
    if (!dev) return 0;
    const uint32_t n = n_rows * head_dim;
    attention_raw_gather_window_bitq_kernel<<<(n + 255u) / 256u, 256u>>>(
            dev, (const unsigned char *)ring->ptr, raw_cap, first_row, n_rows,
            head_dim, bits);
    if (!cuda_ok(cudaGetLastError(), "bitq dequant dump gather")) return 0;
    if (cudaMemcpy(dst, dev, bytes, cudaMemcpyDeviceToHost) != cudaSuccess) {
        return 0;
    }
    return 1;
}

/* DS4_CUDA_KV_BITQ: checkpoint payload load mirror.  Pack FP32 host rows
 * [first_row, first_row + n_rows) (logical order) into the packed ring
 * (wrapped, row_bytes stride) -- the inverse of the payload dump. */
extern "C" int ds4_gpu_bitq_pack_rows_upload(
        ds4_gpu_tensor *ring, uint32_t raw_cap, uint32_t first_row,
        uint32_t n_rows, uint32_t head_dim, int bits, const float *src) {
    if (!ring || !src || n_rows == 0u || raw_cap == 0u || head_dim == 0u ||
        bits < 2 || bits > 8) {
        return 0;
    }
    const int logical_tier = ds4_tensor_device_idx(ring);
    const uint64_t bytes = (uint64_t)n_rows * head_dim * sizeof(float);
    float *dev = (float *)cuda_tmp_alloc_on(logical_tier, bytes,
                                            "bitq pack upload");
    if (!dev) return 0;
    if (cudaMemcpy(dev, src, bytes, cudaMemcpyHostToDevice) != cudaSuccess) {
        return 0;
    }
    store_raw_kv_bitq_batch_kernel<<<(n_rows + 255u) / 256u, 256u>>>(
            (unsigned char *)ring->ptr, dev, raw_cap, first_row, n_rows,
            head_dim, bits);
    return cuda_ok(cudaGetLastError(), "bitq pack upload");
}

/* Dedicated comp-cache dequant gather buffer (same aliasing rationale as
 * g_bitq_gather: the comp temp must survive the downstream launches that
 * allocate slab temps).  When a paging table is installed
 * (ds4_gpu_indexer_paging_table_set, DS4_CUDA_INDEXER_PAGING), rows are
 * translated logical page -> resident physical page before the unpack. */
static const uint32_t *g_indexer_paging_table = NULL;

extern "C" void ds4_gpu_indexer_paging_table_set(const ds4_gpu_tensor *table) {
    if (getenv("DS4_CUDA_INDEXER_PAGING_NO_GATHER") != NULL) return;
    g_indexer_paging_table =
        table ? (const uint32_t *)table->ptr : NULL;
}

/* ④-(a): router near-miss ids (ranks 6..14 per token) feeding the expert
 * prefetcher's registration (DS4_CUDA_PREFETCH_PREDICT).  Set once at graph
 * init; the slot-cache recording appends them to the predicted set. */
static const ds4_gpu_tensor *g_router_prefetch_ids = NULL;

extern "C" void ds4_gpu_router_prefetch_ids_set(const ds4_gpu_tensor *t) {
    g_router_prefetch_ids = t;
}

__global__ static void attention_bitq_comp_gather_paged_kernel(
        float *dst, const unsigned char *ring,
        const uint32_t *table, uint32_t n_rows, uint32_t head_dim, int bits) {
    const uint32_t n = n_rows * head_dim;
    const uint32_t row_bytes = kv_bitq_row_bytes(head_dim, bits);
    for (uint32_t i = blockIdx.x * blockDim.x + threadIdx.x; i < n;
         i += blockDim.x * gridDim.x) {
        const uint32_t row = i / head_dim;
        const uint32_t col = i % head_dim;
        const uint32_t page = row >> 9u;
        const uint32_t phys = table[page];
        if (phys == UINT32_MAX) {
            /* evicted page: the read-prepare guarantees every SELECTED page
             * is resident, so these positions are never read by the indexed
             * attention kernels (they touch topk rows only). */
            dst[i] = 0.0f;
            continue;
        }
        const uint32_t src_row = (phys << 9u) + (row & 511u);
        dst[i] = kv_bitq_unpack_elem(
                ring + (uint64_t)src_row * row_bytes, head_dim, col, bits);
    }
}

static float *attention_bitq_comp_gather(const ds4_gpu_tensor *cache,
        uint32_t n_rows, uint32_t head_dim, int logical_tier, const char *tag) {
    (void)logical_tier;
    const uint64_t bytes = (uint64_t)n_rows * head_dim * sizeof(float);
    if (g_bitq_comp_gather_bytes < bytes) {
        if (g_bitq_comp_gather) {
            if (!cuda_ok(cudaDeviceSynchronize(),
                         "synchronize bitq comp gather growth")) return NULL;
            (void)cudaFree(g_bitq_comp_gather);
            g_bitq_comp_gather = NULL;
            g_bitq_comp_gather_bytes = 0;
        }
        void *p = NULL;
        if (cudaMalloc(&p, (size_t)bytes) != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA bitq comp gather alloc failed for %s (%.2f MiB)\n",
                    tag ? tag : "?", (double)bytes / 1048576.0);
            (void)cudaGetLastError();
            return NULL;
        }
        g_bitq_comp_gather = p;
        g_bitq_comp_gather_bytes = bytes;
    }
    float *kv = (float *)g_bitq_comp_gather;
    const uint32_t n = n_rows * head_dim;
    if (g_indexer_paging_table) {
        attention_bitq_comp_gather_paged_kernel<<<(n + 255u) / 256u, 256u>>>(
                kv, (const unsigned char *)cache->ptr, g_indexer_paging_table,
                n_rows, head_dim, kv_bitq_comp_bits());
        if (!cuda_ok(cudaGetLastError(), "attention bitq comp paged gather")) return NULL;
        /* Consumed: the kernel received its pointer copy; clear so gathers of
         * OTHER layers (ratio-1, non-paged) never reuse a stale table. */
        g_indexer_paging_table = NULL;
        return kv;
    }
    attention_raw_gather_window_bitq_kernel<<<(n + 255u) / 256u, 256u>>>(
            kv, (const unsigned char *)cache->ptr, n_rows, 0u, n_rows,
            head_dim, kv_bitq_comp_bits());
    if (!cuda_ok(cudaGetLastError(), "attention bitq comp gather")) return NULL;
    return kv;
}

/* ⑦ 阶段 4: pack staged f32 comp rows into the packed cache at
 * [first_row, first_row + rows).  The packed cache cannot receive f32 writes
 * in place, so the driver stages through attn_comp_stage (mirroring the F16
 * flow) and commits here. */
extern "C" int ds4_gpu_comp_cache_bitq_pack_stage_tensor(
        const ds4_gpu_tensor *stage, ds4_gpu_tensor *cache, uint32_t cap,
        uint32_t first_row, uint32_t rows, uint32_t head_dim) {
    if (!stage || !cache || cap == 0u || rows == 0u ||
        first_row + rows > cap) {
        return 0;
    }
    if (!kv_bitq_comp_on()) return 1;
    if (stage->bytes < (uint64_t)rows * head_dim * sizeof(float)) return 0;
    if (!kv_comp_bytes_ok(cache, cap, head_dim)) return 0;
    store_raw_kv_bitq_batch_kernel<<<(rows + 255u) / 256u, 256u>>>(
            (unsigned char *)cache->ptr, (const float *)stage->ptr, cap,
            first_row, rows, head_dim, kv_bitq_comp_bits());
    return cuda_ok(cudaGetLastError(), "comp bitq pack stage launch");
}

/* ④ 阶段2 paging: pack ONE page's row span [stage_row, stage_row+rows) of the
 * staged f32 batch into the resident ring at the page's physical slot.  The
 * stage rows are batch-relative; the ring rows are slot-relative (cap=512). */
extern "C" int ds4_gpu_comp_cache_bitq_pack_page_tensor(
        const ds4_gpu_tensor *stage, ds4_gpu_tensor *cache,
        uint32_t phys_slot, uint32_t page_row, uint32_t stage_row,
        uint32_t rows, uint32_t head_dim) {
    if (!stage || !cache || rows == 0u || head_dim == 0u ||
        rows > 512u || page_row + rows > 512u) {
        return 0;
    }
    if (!kv_bitq_comp_on()) return 1;
    if (stage->bytes <
        (uint64_t)(stage_row + rows) * head_dim * sizeof(float)) {
        return 0;
    }
    const int bits = kv_bitq_comp_bits();
    store_raw_kv_bitq_batch_kernel<<<(rows + 255u) / 256u, 256u>>>(
            (unsigned char *)cache->ptr +
                    (uint64_t)phys_slot * 512u * kv_bitq_row_bytes(head_dim, bits),
            (const float *)stage->ptr + (uint64_t)stage_row * head_dim,
            512u, page_row, rows, head_dim, bits);
    return cuda_ok(cudaGetLastError(), "comp bitq pack page launch");
}

/* ⑦ 阶段 4c: the indexer cache (128-dim f32 rows, ratio-4 layers, append-only)
 * gets the same per-row pack under its own env.  NOTE: prefill-side only --
 * the GPU standalone decode-side indexer writes f32 into the packed cache and
 * is unsupported under this env (the hybrid benches decode on the CPU). */
static int kv_bitq_idx_on(void) {
    if (ds4_kv_bitq_auto_active()) return ds4_kv_bitq_auto_enabled();
    static int on = -1;
    if (on < 0) on = getenv("DS4_CUDA_KV_BITQ_IDX") != NULL ? 1 : 0;
    return on;
}

static inline bool kv_idx_bytes_ok(const ds4_gpu_tensor *t,
        uint32_t cap, uint32_t head_dim) {
    if (!t) return false;
    if (kv_bitq_idx_on()) {
        return t->bytes >=
               (uint64_t)cap * kv_bitq_row_bytes(head_dim, kv_bitq_idx_bits());
    }
    return t->bytes >= (uint64_t)cap * head_dim * sizeof(float);
}

/* Dedicated indexer-cache dequant gather buffer (same aliasing rationale as
 * the other dedicated gather buffers). */
static float *attention_bitq_idx_gather(const ds4_gpu_tensor *cache,
        uint32_t n_rows, uint32_t head_dim, int logical_tier, const char *tag) {
    (void)logical_tier;
    const uint64_t bytes = (uint64_t)n_rows * head_dim * sizeof(float);
    if (g_bitq_idx_gather_bytes < bytes) {
        if (g_bitq_idx_gather) {
            if (!cuda_ok(cudaDeviceSynchronize(),
                         "synchronize bitq idx gather growth")) return NULL;
            (void)cudaFree(g_bitq_idx_gather);
            g_bitq_idx_gather = NULL;
            g_bitq_idx_gather_bytes = 0;
        }
        void *p = NULL;
        if (cudaMalloc(&p, (size_t)bytes) != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA bitq idx gather alloc failed for %s (%.2f MiB)\n",
                    tag ? tag : "?", (double)bytes / 1048576.0);
            (void)cudaGetLastError();
            return NULL;
        }
        g_bitq_idx_gather = p;
        g_bitq_idx_gather_bytes = bytes;
    }
    float *kv = (float *)g_bitq_idx_gather;
    const uint32_t n = n_rows * head_dim;
    attention_raw_gather_window_bitq_kernel<<<(n + 255u) / 256u, 256u>>>(
            kv, (const unsigned char *)cache->ptr, n_rows, 0u, n_rows,
            head_dim, kv_bitq_idx_bits());
    if (!cuda_ok(cudaGetLastError(), "attention bitq idx gather")) return NULL;
    return kv;
}

/* Pack staged f32 index rows into the packed indexer cache (mirrors the
 * comp-cache stage pack; the indexer writers stage through attn_comp_stage
 * under the env, then commit here). */
extern "C" int ds4_gpu_index_cache_bitq_pack_stage_tensor(
        const ds4_gpu_tensor *stage, ds4_gpu_tensor *cache, uint32_t cap,
        uint32_t first_row, uint32_t rows, uint32_t head_dim) {
    if (!stage || !cache || cap == 0u || rows == 0u ||
        first_row + rows > cap) {
        return 0;
    }
    if (!kv_bitq_idx_on()) return 1;
    if (stage->bytes < (uint64_t)rows * head_dim * sizeof(float)) return 0;
    if (!kv_idx_bytes_ok(cache, cap, head_dim)) return 0;
    store_raw_kv_bitq_batch_kernel<<<(rows + 255u) / 256u, 256u>>>(
            (unsigned char *)cache->ptr, (const float *)stage->ptr, cap,
            first_row, rows, head_dim, kv_bitq_idx_bits());
    return cuda_ok(cudaGetLastError(), "idx bitq pack stage launch");
}

/* Layer-2 two-stage retrieval (DS4_CUDA_INDEXER_2STAGE, default OFF):
 * capture the exact squared norm of each packed row's DEQUANTIZED values
 * (dequant = code * scale, so ||k||^2 = sum_g scale_g^2 * sum_c code_c^2)
 * into a side table.  ONE norm per row: the indexer key row (128 dims) is
 * shared across all 64 scoring heads, so the Cauchy-Schwarz bound needs a
 * single per-row norm.  One block per row, 8 groups. */
__global__ static void indexer_norm_capture_kernel(
        float *norm2, const unsigned char *cache, uint32_t cap,
        uint32_t first_row, uint32_t rows, uint32_t head_dim, int bits) {
    const uint32_t row = blockIdx.x;
    if (row >= rows) return;
    const uint32_t groups = head_dim / 16u;
    const uint32_t group_bytes = (16u * (uint32_t)bits) / 8u;
    const uint64_t row_bytes = (uint64_t)groups * 4u + (uint64_t)groups * group_bytes;
    const unsigned char *src =
        cache + (uint64_t)(first_row + row) * row_bytes;
    float acc = 0.0f;
    if (threadIdx.x < groups) {
        const uint32_t g = threadIdx.x;
        float scale = 0.0f;
        memcpy(&scale, src + g * 4u, 4);
        const unsigned char *pack = src + groups * 4u + g * group_bytes;
        int code_sum2 = 0;
        for (uint32_t c = 0; c < 16u; c++) {
            const uint32_t bitpos = c * (uint32_t)bits;
            const uint32_t byte = bitpos >> 3u;
            const uint32_t shift = bitpos & 7u;
            uint32_t u = pack[byte] >> shift;
            if (shift + (uint32_t)bits > 8u) {
                u |= (uint32_t)pack[byte + 1u] << (8u - shift);
            }
            u &= (1u << bits) - 1u;
            int code = (int)u;
            if (bits < 32 && (u & (1u << (bits - 1u)))) {
                code -= 1 << bits;   /* sign-extend two's complement */
            }
            code_sum2 += code * code;
        }
        acc = scale * scale * (float)code_sum2;
    }
    __shared__ float sh[256];
    sh[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) sh[threadIdx.x] += sh[threadIdx.x + s];
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        norm2[first_row + row] = sh[0];
    }
}

extern "C" int ds4_gpu_index_norm_capture(
        const ds4_gpu_tensor *cache, ds4_gpu_tensor *norm_cache,
        uint32_t cap, uint32_t first_row, uint32_t rows, uint32_t head_dim) {
    if (!cache || !norm_cache || cap == 0u || rows == 0u ||
        first_row + rows > cap) {
        return 0;
    }
    if (!kv_bitq_idx_on()) return 1;
    if (norm_cache->bytes < (uint64_t)cap * sizeof(float)) return 0;
    const int bits = kv_bitq_idx_bits();
    indexer_norm_capture_kernel<<<rows, 256>>>(
            (float *)norm_cache->ptr, (const unsigned char *)cache->ptr,
            cap, first_row, rows, head_dim, bits);
    return cuda_ok(cudaGetLastError(), "indexer norm capture launch");
}

__global__ static void store_raw_kv_batch_kernel(float *raw, const float *kv, uint32_t raw_cap, uint32_t pos0, uint32_t n_tokens, uint32_t head_dim) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * head_dim;
    if (gid >= n) return;
    uint32_t d = gid % head_dim;
    uint32_t t = gid / head_dim;
    uint32_t row = (pos0 + t) % raw_cap;
    /* ds4 determinism: the zero-prefix raw attention reads the FP32 batch
     * KV, so the ring must hold the same FP32 values — the old FP16 rounding
     * made the window-fused nonzero-prefix path drift ULP-level vs the
     * whole batch (the ③ boundary fork). */
    raw[(uint64_t)row * head_dim + d] = kv[(uint64_t)t * head_dim + d];
}

__global__ static void attention_prefill_raw_kernel(
        float *heads,
        const float *sinks,
        const float *q,
        const float *raw_kv,
        uint32_t n_tokens,
        uint32_t window,
        uint32_t n_head,
        uint32_t head_dim) {
    uint32_t t = blockIdx.x;
    uint32_t h = blockIdx.y;
    if (t >= n_tokens || h >= n_head) return;
    uint32_t raw_count = t + 1 < window ? t + 1 : window;
    uint32_t raw_start = t + 1 - raw_count;
    const float *qh = q + ((uint64_t)t * n_head + h) * head_dim;
    __shared__ float scores[256];
    __shared__ float partial[128];
    __shared__ float max_s;
    __shared__ float denom;
    float scale = rsqrtf((float)head_dim);
    float local_max = sinks[h];
    __syncthreads();
    for (uint32_t r = threadIdx.x; r < raw_count; r += blockDim.x) {
        const float *kv = raw_kv + (uint64_t)(raw_start + r) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; d++) dot += qh[d] * kv[d];
        scores[r] = dot * scale;
        local_max = fmaxf(local_max, scores[r]);
    }
    partial[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] = fmaxf(partial[threadIdx.x], partial[threadIdx.x + stride]);
        __syncthreads();
    }
    if (threadIdx.x == 0) max_s = partial[0];
    __syncthreads();
    if (threadIdx.x == 0) {
        float den = expf(sinks[h] - max_s);
        for (uint32_t r = 0; r < raw_count; r++) {
            scores[r] = expf(scores[r] - max_s);
            den += scores[r];
        }
        denom = den;
    }
    __syncthreads();
    float *oh = heads + ((uint64_t)t * n_head + h) * head_dim;
    for (uint32_t d = threadIdx.x; d < head_dim; d += blockDim.x) {
        float acc = 0.0f;
        for (uint32_t r = 0; r < raw_count; r++) {
            acc += raw_kv[(uint64_t)(raw_start + r) * head_dim + d] * scores[r];
        }
        oh[d] = acc / denom;
    }
}

__global__ static void attention_prefill_mixed_kernel(
        float *heads,
        const float *sinks,
        const float *q,
        const float *raw_kv,
        const float *comp_kv,
        const float *comp_mask,
        uint32_t use_comp_mask,
        uint32_t n_tokens,
        uint32_t n_comp,
        uint32_t window,
        uint32_t ratio,
        uint32_t n_head,
        uint32_t head_dim) {
    uint32_t t = blockIdx.x;
    uint32_t h = blockIdx.y;
    if (t >= n_tokens || h >= n_head) return;
    const float *qh = q + ((uint64_t)t * n_head + h) * head_dim;
    uint32_t raw_start = (window != 0 && t + 1u > window) ? t + 1u - window : 0u;
    uint32_t raw_count = t + 1u - raw_start;
    uint32_t visible_comp = (t + 1u) / ratio;
    if (visible_comp > n_comp) visible_comp = n_comp;
    __shared__ float scores[512];
    __shared__ float partial[256];
    __shared__ float max_s;
    __shared__ float denom;
    float scale = rsqrtf((float)head_dim);
    float local_max = sinks[h];
    uint32_t n_score = raw_count + visible_comp;

    for (uint32_t r = threadIdx.x; r < raw_count; r += blockDim.x) {
        const float *kvrow = raw_kv + (uint64_t)(raw_start + r) * head_dim;
        float dot = 0.0f;
        for (uint32_t d = 0; d < head_dim; d++) dot += qh[d] * kvrow[d];
        scores[r] = dot * scale;
        local_max = fmaxf(local_max, scores[r]);
    }
    for (uint32_t c = threadIdx.x; c < visible_comp; c += blockDim.x) {
        float add = use_comp_mask ? comp_mask[(uint64_t)t * n_comp + c] : 0.0f;
        float s = -INFINITY;
        if (add > -1.0e20f) {
            const float *kvrow = comp_kv + (uint64_t)c * head_dim;
            float dot = 0.0f;
            for (uint32_t d = 0; d < head_dim; d++) dot += qh[d] * kvrow[d];
            s = dot * scale + add;
        }
        scores[raw_count + c] = s;
        local_max = fmaxf(local_max, s);
    }
    partial[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] = fmaxf(partial[threadIdx.x], partial[threadIdx.x + stride]);
        __syncthreads();
    }
    if (threadIdx.x == 0) max_s = partial[0];
    __syncthreads();
    float den_local = 0.0f;
    for (uint32_t i = threadIdx.x; i < n_score; i += blockDim.x) {
        scores[i] = expf(scores[i] - max_s);
        den_local += scores[i];
    }
    partial[threadIdx.x] = den_local;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) denom = partial[0] + expf(sinks[h] - max_s);
    __syncthreads();
    float *oh = heads + ((uint64_t)t * n_head + h) * head_dim;
    for (uint32_t d = threadIdx.x; d < head_dim; d += blockDim.x) {
        float acc = 0.0f;
        for (uint32_t r = 0; r < raw_count; r++) acc += raw_kv[(uint64_t)(raw_start + r) * head_dim + d] * scores[r];
        for (uint32_t c = 0; c < visible_comp; c++) acc += comp_kv[(uint64_t)c * head_dim + d] * scores[raw_count + c];
        oh[d] = acc / denom;
    }
}

__global__ static void attention_prefill_raw_softmax_kernel(
        float *scores,
        const float *sinks,
        uint32_t n_tokens,
        uint32_t window,
        uint32_t n_keys) {
    uint32_t t = blockIdx.x;
    uint32_t h = blockIdx.y;
    if (t >= n_tokens) return;
    float *row = scores + ((uint64_t)h * n_tokens + t) * n_keys;
    __shared__ float partial[256];
    __shared__ float max_s;
    __shared__ float denom;
    float local_max = sinks[h];
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) {
        bool valid = k <= t && (window == 0 || t - k < window);
        float s = valid ? row[k] : -INFINITY;
        row[k] = s;
        local_max = fmaxf(local_max, s);
    }
    partial[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] = fmaxf(partial[threadIdx.x], partial[threadIdx.x + stride]);
        __syncthreads();
    }
    if (threadIdx.x == 0) max_s = partial[0];
    __syncthreads();
    float den_local = 0.0f;
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) {
        float p = isfinite(row[k]) ? expf(row[k] - max_s) : 0.0f;
        row[k] = p;
        den_local += p;
    }
    partial[threadIdx.x] = den_local;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) denom = partial[0] + expf(sinks[h] - max_s);
    __syncthreads();
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) row[k] /= denom;
}

__global__ static void attention_prefill_mixed_softmax_kernel(
        float *scores,
        const float *sinks,
        const float *comp_mask,
        uint32_t use_comp_mask,
        uint32_t n_tokens,
        uint32_t n_comp,
        uint32_t window,
        uint32_t ratio,
        uint32_t n_keys) {
    uint32_t t = blockIdx.x;
    uint32_t h = blockIdx.y;
    if (t >= n_tokens || ratio == 0) return;
    float *row = scores + ((uint64_t)h * n_tokens + t) * n_keys;
    __shared__ float partial[256];
    __shared__ float max_s;
    __shared__ float denom;
    float local_max = sinks[h];
    const uint32_t visible_comp = (t + 1u) / ratio;
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) {
        float s = -INFINITY;
        if (k < n_tokens) {
            if (k <= t && (window == 0 || t - k < window)) s = row[k];
        } else {
            uint32_t c = k - n_tokens;
            if (c < n_comp && c < visible_comp) {
                float add = use_comp_mask ? comp_mask[(uint64_t)t * n_comp + c] : 0.0f;
                if (add > -1.0e20f) s = row[k] + add;
            }
        }
        row[k] = s;
        local_max = fmaxf(local_max, s);
    }
    partial[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] = fmaxf(partial[threadIdx.x], partial[threadIdx.x + stride]);
        __syncthreads();
    }
    if (threadIdx.x == 0) max_s = partial[0];
    __syncthreads();
    float den_local = 0.0f;
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) {
        float p = isfinite(row[k]) ? expf(row[k] - max_s) : 0.0f;
        row[k] = p;
        den_local += p;
    }
    partial[threadIdx.x] = den_local;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) denom = partial[0] + expf(sinks[h] - max_s);
    __syncthreads();
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) row[k] /= denom;
}

__global__ static void attention_prefill_pack_mixed_kv_kernel(
        float *dst,
        const float *raw_kv,
        const float *comp_kv,
        uint32_t n_tokens,
        uint32_t n_comp,
        uint32_t head_dim) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)(n_tokens + n_comp) * head_dim;
    if (gid >= n) return;
    uint32_t d = gid % head_dim;
    uint32_t r = gid / head_dim;
    dst[gid] = r < n_tokens ? raw_kv[(uint64_t)r * head_dim + d]
                             : comp_kv[(uint64_t)(r - n_tokens) * head_dim + d];
}

__global__ static void attention_visual_pack_mixed_kv_kernel(
        float       *dst,
        const float *raw_kv,
        const float *comp_kv,
        uint32_t     n_raw,
        uint32_t     raw_cap,
        uint32_t     raw_start,
        uint32_t     n_comp,
        uint32_t     head_dim) {
    const uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t count = (uint64_t)(n_raw + n_comp) * head_dim;
    if (gid >= count) return;
    const uint32_t d = gid % head_dim;
    const uint32_t row = gid / head_dim;
    if (row < n_raw) {
        const uint32_t physical = (raw_start + row) % raw_cap;
        dst[gid] = raw_kv[(uint64_t)physical * head_dim + d];
    } else {
        dst[gid] = comp_kv[(uint64_t)(row - n_raw) * head_dim + d];
    }
}

__global__ static void attention_visual_mixed_softmax_kernel(
        float       *scores,
        const float *sinks,
        const float *comp_mask,
        const uint32_t *raw_bounds,
        uint32_t     use_comp_mask,
        uint32_t     n_tokens,
        uint32_t     pos0,
        uint32_t     first_raw_pos,
        uint32_t     n_raw,
        uint32_t     n_comp,
        uint32_t     ratio,
        uint32_t     n_keys) {
    const uint32_t t = blockIdx.x;
    const uint32_t h = blockIdx.y;
    if (t >= n_tokens) return;
    float *row = scores + ((uint64_t)h * n_tokens + t) * n_keys;
    __shared__ float partial[256];
    __shared__ float max_s;
    __shared__ float denom;
    const uint32_t raw_lo = raw_bounds[2u * t];
    const uint32_t raw_hi = raw_bounds[2u * t + 1u];
    const uint32_t qpos = pos0 + t;
    uint32_t visible_comp = ratio ? (qpos + 1u) / ratio : 0u;
    if (visible_comp > n_comp) visible_comp = n_comp;
    float local_max = sinks[h];
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) {
        float score = -INFINITY;
        if (k < n_raw) {
            const uint32_t kpos = first_raw_pos + k;
            if (kpos >= raw_lo && kpos <= raw_hi) score = row[k];
        } else {
            const uint32_t c = k - n_raw;
            if (c < visible_comp) {
                const float add = use_comp_mask
                    ? comp_mask[(uint64_t)t * n_comp + c] : 0.0f;
                if (add > -1.0e20f) score = row[k] + add;
            }
        }
        row[k] = score;
        local_max = fmaxf(local_max, score);
    }
    partial[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = blockDim.x / 2u; stride != 0u; stride >>= 1u) {
        if (threadIdx.x < stride)
            partial[threadIdx.x] = fmaxf(partial[threadIdx.x],
                                          partial[threadIdx.x + stride]);
        __syncthreads();
    }
    if (threadIdx.x == 0u) max_s = partial[0];
    __syncthreads();
    float sum = 0.0f;
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x) {
        const float probability = isfinite(row[k])
            ? expf(row[k] - max_s) : 0.0f;
        row[k] = probability;
        sum += probability;
    }
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x / 2u; stride != 0u; stride >>= 1u) {
        if (threadIdx.x < stride)
            partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0u)
        denom = partial[0] + expf(sinks[h] - max_s);
    __syncthreads();
    for (uint32_t k = threadIdx.x; k < n_keys; k += blockDim.x)
        row[k] /= denom;
}

__global__ static void attention_prefill_unpack_heads_kernel(
        float *heads,
        const float *tmp,
        uint32_t n_tokens,
        uint32_t n_head,
        uint32_t head_dim) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_head * head_dim;
    if (gid >= n) return;
    uint32_t d = gid % head_dim;
    uint64_t q = gid / head_dim;
    uint32_t h = q % n_head;
    uint32_t t = q / n_head;
    heads[gid] = tmp[((uint64_t)h * n_tokens + t) * head_dim + d];
}

/* SlimInfer APIA v2 (attention Q-row pruning): gather the kept query rows
 * (listed in active_idx, ascending chunk-local positions) into a compact
 * buffer so the cuBLAS attention GEMMs run with n_active rows. */
__global__ static void attention_pruned_q_gather_kernel(
        float * __restrict__ dst,
        const float * __restrict__ src,
        const int32_t * __restrict__ active_idx,
        uint32_t n_active,
        uint32_t row_floats) {
    const uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t n = (uint64_t)n_active * row_floats;
    if (gid >= n) return;
    const uint32_t row = (uint32_t)(gid / row_floats);
    const uint32_t col = (uint32_t)(gid % row_floats);
    dst[gid] = src[(uint64_t)active_idx[row] * row_floats + col];
}

/* SlimInfer APIA v2: scatter the compact attention output (out_tmp layout
 * [n_head][n_active][head_dim]) back to the kept rows of the full heads
 * tensor. Pruned rows are NOT touched here; the caller zeroes them with
 * ds4_gpu_attention_pruned_heads_zero_tensor before the O projection. */
__global__ static void attention_pruned_unpack_scatter_kernel(
        float * __restrict__ heads,
        const float * __restrict__ tmp,
        const int32_t * __restrict__ active_idx,
        uint32_t n_active,
        uint32_t n_head,
        uint32_t head_dim) {
    const uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t n = (uint64_t)n_active * n_head * head_dim;
    if (gid >= n) return;
    const uint32_t qdim = n_head * head_dim;
    const uint32_t a = (uint32_t)(gid / qdim);
    const uint32_t col = (uint32_t)(gid % qdim);
    const uint32_t head = col / head_dim;
    const uint32_t d = col % head_dim;
    const uint32_t row = (uint32_t)active_idx[a];
    heads[(uint64_t)row * qdim + col] =
        tmp[((uint64_t)head * n_active + a) * head_dim + d];
}

/* SlimInfer APIA v2: zero the heads rows of pruned tokens (prune_mask is a
 * uint8 tensor; 1 = pruned) so the O projection emits zero for them. */
__global__ static void attention_pruned_zero_rows_kernel(
        float * __restrict__ heads,
        const uint8_t * __restrict__ prune_mask,
        uint32_t n_tokens,
        uint32_t row_floats) {
    const uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t n = (uint64_t)n_tokens * row_floats;
    if (gid >= n) return;
    const uint32_t row = (uint32_t)(gid / row_floats);
    if (prune_mask[row]) heads[gid] = 0.0f;
}

__global__ static void attention_pack_group_heads_f16_kernel(
        __half *dst,
        const float *heads,
        uint32_t n_tokens,
        uint32_t n_groups,
        uint32_t group_dim) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_groups * n_tokens * group_dim;
    if (gid >= n) return;
    uint32_t d = gid % group_dim;
    uint64_t q = gid / group_dim;
    uint32_t t = q % n_tokens;
    uint32_t g = q / n_tokens;
    dst[gid] = __float2half(heads[((uint64_t)t * n_groups + g) * group_dim + d]);
}

__global__ static void attention_unpack_group_low_kernel(
        float *low,
        const float *tmp,
        uint32_t n_tokens,
        uint32_t n_groups,
        uint32_t rank) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_groups * n_tokens * rank;
    if (gid >= n) return;
    uint32_t r = gid % rank;
    uint64_t q = gid / rank;
    uint32_t t = q % n_tokens;
    uint32_t g = q / n_tokens;
    uint32_t low_dim = n_groups * rank;
    low[(uint64_t)t * low_dim + (uint64_t)g * rank + r] = tmp[gid];
}

__global__ static void attention_decode_mixed_kernel(
        float *heads,
        const float *sinks,
        const float *q,
        const float *raw_kv,
        const float *comp_kv,
        const float *comp_mask,
        uint32_t use_comp_mask,
        uint32_t n_tokens,
        uint32_t pos0,
        uint32_t n_raw,
        uint32_t raw_cap,
        uint32_t raw_start,
        uint32_t n_comp,
        uint32_t window,
        uint32_t ratio,
        uint32_t n_head,
        uint32_t head_dim,
        uint32_t score_lanes_single) {
    uint32_t t = blockIdx.x;
    uint32_t h = blockIdx.y;
    if (t >= n_tokens || h >= n_head) return;
    const bool single_all = (n_tokens == 1u && ratio == 0u);
    uint32_t qpos = pos0 + t;
    uint32_t first_raw_pos = pos0 + n_tokens - n_raw;
    uint32_t visible_comp = single_all ? n_comp : (n_comp ? (qpos + 1u) / ratio : 0u);
    if (visible_comp > n_comp) visible_comp = n_comp;
    const float *qh = q + ((uint64_t)t * n_head + h) * head_dim;
    __shared__ float scores[DS4_CUDA_ATTENTION_SCORE_CAP];
    __shared__ uint32_t raw_rows[256];
    __shared__ float partial[256];
    __shared__ float max_s;
    __shared__ float denom;
    __shared__ uint32_t raw_count;
    __shared__ uint32_t raw_first_idx;
    const uint32_t score_threads = blockDim.x > 256u ? 256u : blockDim.x;
    const bool score_thread = threadIdx.x < score_threads;
    float scale = rsqrtf((float)head_dim);
    if (threadIdx.x == 0) {
        raw_count = 0;
        raw_first_idx = 0;
        if (n_raw != 0) {
            const uint32_t raw_last_pos = first_raw_pos + n_raw - 1u;
            if (single_all) {
                raw_count = n_raw > 256u ? 256u : n_raw;
            } else if (qpos >= first_raw_pos) {
                uint32_t lo = first_raw_pos;
                if (window != 0 && qpos + 1u > window) {
                    const uint32_t wlo = qpos + 1u - window;
                    if (wlo > lo) lo = wlo;
                }
                const uint32_t hi = qpos < raw_last_pos ? qpos : raw_last_pos;
                if (hi >= lo) {
                    raw_first_idx = lo - first_raw_pos;
                    raw_count = hi - lo + 1u;
                    if (raw_count > 256u) raw_count = 256u;
                }
            }
        }
    }
    __syncthreads();
    if (score_thread) {
        for (uint32_t r = threadIdx.x; r < raw_count; r += score_threads) {
            raw_rows[r] = (raw_start + raw_first_idx + r) % raw_cap;
        }
    }
    __syncthreads();
    uint32_t n_score = raw_count + visible_comp;
    float local_max = sinks[h];
    if (score_thread) {
        if (visible_comp == 0 || (n_tokens == 1u && score_lanes_single == 0u)) {
            for (uint32_t r = threadIdx.x; r < raw_count; r += score_threads) {
                const float *kvrow = raw_kv + (uint64_t)raw_rows[r] * head_dim;
                float dot = 0.0f;
                for (uint32_t d = 0; d < head_dim; d++) dot += qh[d] * kvrow[d];
                scores[r] = dot * scale;
                local_max = fmaxf(local_max, scores[r]);
            }
            for (uint32_t c = threadIdx.x; c < visible_comp; c += score_threads) {
                float add = use_comp_mask ? comp_mask[(uint64_t)t * n_comp + c] : 0.0f;
                float s = -INFINITY;
                if (add > -1.0e20f) {
                    const float *kvrow = comp_kv + (uint64_t)c * head_dim;
                    float dot = 0.0f;
                    for (uint32_t d = 0; d < head_dim; d++) dot += qh[d] * kvrow[d];
                    s = dot * scale + add;
                }
                scores[raw_count + c] = s;
                local_max = fmaxf(local_max, s);
            }
        } else if (n_tokens == 1u && score_lanes_single == 4u) {
            uint32_t qlane = threadIdx.x & 3u;
            uint32_t qgroup = threadIdx.x >> 2u;
            for (uint32_t row0 = 0; row0 < n_score; row0 += 64u) {
                uint32_t row = row0 + qgroup;
                if (row < n_score) {
                    float add = 0.0f;
                    const float *kvrow = NULL;
                    if (row < raw_count) {
                        kvrow = raw_kv + (uint64_t)raw_rows[row] * head_dim;
                    } else {
                        uint32_t c = row - raw_count;
                        add = use_comp_mask ? comp_mask[(uint64_t)t * n_comp + c] : 0.0f;
                        if (add > -1.0e20f) kvrow = comp_kv + (uint64_t)c * head_dim;
                    }
                    float s = -INFINITY;
                    if (kvrow) {
                        float dot = 0.0f;
                        for (uint32_t d = qlane; d < head_dim; d += 4u) dot += qh[d] * kvrow[d];
                        const uint32_t mask = 0xfu << (threadIdx.x & 28u);
                        dot += __shfl_down_sync(mask, dot, 2, 4);
                        dot += __shfl_down_sync(mask, dot, 1, 4);
                        s = dot * scale + add;
                    }
                    if (qlane == 0) scores[row] = s;
                }
            }
            __syncthreads();
            for (uint32_t i = threadIdx.x; i < n_score; i += score_threads) {
                local_max = fmaxf(local_max, scores[i]);
            }
        } else {
            uint32_t qlane = threadIdx.x & 7u;
            uint32_t qgroup = threadIdx.x >> 3u;
            for (uint32_t row0 = 0; row0 < n_score; row0 += 32u) {
                uint32_t row = row0 + qgroup;
                if (row < n_score) {
                    float add = 0.0f;
                    const float *kvrow = NULL;
                    if (row < raw_count) {
                        kvrow = raw_kv + (uint64_t)raw_rows[row] * head_dim;
                    } else {
                        uint32_t c = row - raw_count;
                        add = use_comp_mask ? comp_mask[(uint64_t)t * n_comp + c] : 0.0f;
                        if (add > -1.0e20f) kvrow = comp_kv + (uint64_t)c * head_dim;
                    }
                    float s = -INFINITY;
                    if (kvrow) {
                        float dot = 0.0f;
                        for (uint32_t d = qlane; d < head_dim; d += 8u) dot += qh[d] * kvrow[d];
                        const uint32_t mask = 0xffu << (threadIdx.x & 24u);
                        for (uint32_t off = 4u; off > 0u; off >>= 1u) {
                            dot += __shfl_down_sync(mask, dot, off, 8);
                        }
                        s = dot * scale + add;
                    }
                    if (qlane == 0) scores[row] = s;
                }
            }
            __syncthreads();
            for (uint32_t i = threadIdx.x; i < n_score; i += score_threads) {
                local_max = fmaxf(local_max, scores[i]);
            }
        }
    }
    if (score_thread) partial[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = score_threads >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] = fmaxf(partial[threadIdx.x], partial[threadIdx.x + stride]);
        __syncthreads();
    }
    if (threadIdx.x == 0) max_s = partial[0];
    __syncthreads();
    float den_local = 0.0f;
    if (score_thread) {
        for (uint32_t i = threadIdx.x; i < n_score; i += score_threads) {
            scores[i] = expf(scores[i] - max_s);
            den_local += scores[i];
        }
    }
    if (score_thread) partial[threadIdx.x] = den_local;
    __syncthreads();
    for (uint32_t stride = score_threads >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) denom = partial[0] + expf(sinks[h] - max_s);
    __syncthreads();
    float *oh = heads + ((uint64_t)t * n_head + h) * head_dim;
    if (head_dim == 512u && blockDim.x >= 512u) {
        uint32_t d = threadIdx.x;
        float acc = 0.0f;
        for (uint32_t r = 0; r < raw_count; r++) {
            float s = scores[r];
            const float *kv = raw_kv + (uint64_t)raw_rows[r] * head_dim;
            acc += kv[d] * s;
        }
        for (uint32_t c = 0; c < visible_comp; c++) {
            float s = scores[raw_count + c];
            const float *kv = comp_kv + (uint64_t)c * head_dim;
            acc += kv[d] * s;
        }
        oh[d] = acc / denom;
    } else if (head_dim == 512u && blockDim.x == 256u) {
        uint32_t d0 = threadIdx.x;
        uint32_t d1 = d0 + 256u;
        float acc0 = 0.0f;
        float acc1 = 0.0f;
        for (uint32_t r = 0; r < raw_count; r++) {
            float s = scores[r];
            const float *kv = raw_kv + (uint64_t)raw_rows[r] * head_dim;
            acc0 += kv[d0] * s;
            acc1 += kv[d1] * s;
        }
        for (uint32_t c = 0; c < visible_comp; c++) {
            float s = scores[raw_count + c];
            const float *kv = comp_kv + (uint64_t)c * head_dim;
            acc0 += kv[d0] * s;
            acc1 += kv[d1] * s;
        }
        oh[d0] = acc0 / denom;
        oh[d1] = acc1 / denom;
    } else {
        for (uint32_t d = threadIdx.x; d < head_dim; d += blockDim.x) {
            float acc = 0.0f;
            for (uint32_t r = 0; r < raw_count; r++) acc += raw_kv[(uint64_t)raw_rows[r] * head_dim + d] * scores[r];
            for (uint32_t c = 0; c < visible_comp; c++) acc += comp_kv[(uint64_t)c * head_dim + d] * scores[raw_count + c];
            oh[d] = acc / denom;
        }
    }
}

__global__ static void attention_decode_score_split_scores_kernel(
        float *score_out,
        const float *q,
        const float *raw_kv,
        const float *comp_kv,
        const float *comp_mask,
        uint32_t use_comp_mask,
        uint32_t pos0,
        uint32_t n_raw,
        uint32_t raw_cap,
        uint32_t raw_start,
        uint32_t n_comp,
        uint32_t window,
        uint32_t ratio,
        uint32_t n_head,
        uint32_t head_dim,
        uint32_t S) {
    const uint32_t h = blockIdx.y;
    const uint32_t j = blockIdx.z;
    if (h >= n_head || j >= S) return;
    const bool single_all = (ratio == 0u);
    const uint32_t qpos = pos0;
    const uint32_t first_raw_pos = pos0 + 1u - n_raw;
    uint32_t visible_comp = single_all ? n_comp : (n_comp ? (qpos + 1u) / ratio : 0u);
    if (visible_comp > n_comp) visible_comp = n_comp;

    uint32_t raw_count = 0;
    uint32_t raw_first_idx = 0;
    if (n_raw != 0) {
        const uint32_t raw_last_pos = first_raw_pos + n_raw - 1u;
        if (single_all) {
            raw_count = n_raw > 256u ? 256u : n_raw;
        } else if (qpos >= first_raw_pos) {
            uint32_t lo = first_raw_pos;
            if (window != 0 && qpos + 1u > window) {
                const uint32_t wlo = qpos + 1u - window;
                if (wlo > lo) lo = wlo;
            }
            const uint32_t hi = qpos < raw_last_pos ? qpos : raw_last_pos;
            if (hi >= lo) {
                raw_first_idx = lo - first_raw_pos;
                raw_count = hi - lo + 1u;
                if (raw_count > 256u) raw_count = 256u;
            }
        }
    }
    const uint32_t n_score = raw_count + visible_comp;
    if (n_score == 0u) return;

    const uint32_t qbase = n_score / S;
    const uint32_t rem = n_score % S;
    const uint32_t g0 = j * qbase + (j < rem ? j : rem);
    const uint32_t cnt = qbase + (j < rem ? 1u : 0u);
    const uint32_t g1 = g0 + cnt;
    const float *qh = q + (uint64_t)h * head_dim;
    float *row_scores = score_out + (uint64_t)h * n_score;
    const float scale = rsqrtf((float)head_dim);

    for (uint32_t g = g0 + threadIdx.x; g < g1; g += blockDim.x) {
        float s = -INFINITY;
        if (g < raw_count) {
            const uint32_t raw_row =
                (raw_start + raw_first_idx + g) % raw_cap;
            const float *kvrow = raw_kv + (uint64_t)raw_row * head_dim;
            float dot = 0.0f;
            for (uint32_t d = 0; d < head_dim; d++) dot += qh[d] * kvrow[d];
            s = dot * scale;
        } else {
            const uint32_t cidx = g - raw_count;
            const float add = use_comp_mask ? comp_mask[(uint64_t)cidx] : 0.0f;
            if (add > -1.0e20f) {
                const float *kvrow = comp_kv + (uint64_t)cidx * head_dim;
                float dot = 0.0f;
                for (uint32_t d = 0; d < head_dim; d++) dot += qh[d] * kvrow[d];
                s = dot * scale + add;
            }
        }
        row_scores[g] = s;
    }
}

__device__ __forceinline__ float ds4_dot_scalar_ldg(
        const float *a,
        const float *b,
        uint32_t n) {
    float dot = 0.0f;
    for (uint32_t d = 0; d < n; d++) dot += __ldg(a + d) * __ldg(b + d);
    return dot;
}

__global__ static void attention_decode_score_split_scores_ldg_kernel(
        float *score_out,
        const float *q,
        const float *raw_kv,
        const float *comp_kv,
        const float *comp_mask,
        uint32_t use_comp_mask,
        uint32_t pos0,
        uint32_t n_raw,
        uint32_t raw_cap,
        uint32_t raw_start,
        uint32_t n_comp,
        uint32_t window,
        uint32_t ratio,
        uint32_t n_head,
        uint32_t head_dim,
        uint32_t S) {
    const uint32_t h = blockIdx.y;
    const uint32_t j = blockIdx.z;
    if (h >= n_head || j >= S) return;
    const bool single_all = (ratio == 0u);
    const uint32_t qpos = pos0;
    const uint32_t first_raw_pos = pos0 + 1u - n_raw;
    uint32_t visible_comp = single_all ? n_comp : (n_comp ? (qpos + 1u) / ratio : 0u);
    if (visible_comp > n_comp) visible_comp = n_comp;

    uint32_t raw_count = 0;
    uint32_t raw_first_idx = 0;
    if (n_raw != 0) {
        const uint32_t raw_last_pos = first_raw_pos + n_raw - 1u;
        if (single_all) {
            raw_count = n_raw > 256u ? 256u : n_raw;
        } else if (qpos >= first_raw_pos) {
            uint32_t lo = first_raw_pos;
            if (window != 0 && qpos + 1u > window) {
                const uint32_t wlo = qpos + 1u - window;
                if (wlo > lo) lo = wlo;
            }
            const uint32_t hi = qpos < raw_last_pos ? qpos : raw_last_pos;
            if (hi >= lo) {
                raw_first_idx = lo - first_raw_pos;
                raw_count = hi - lo + 1u;
                if (raw_count > 256u) raw_count = 256u;
            }
        }
    }
    const uint32_t n_score = raw_count + visible_comp;
    if (n_score == 0u) return;

    const uint32_t qbase = n_score / S;
    const uint32_t rem = n_score % S;
    const uint32_t g0 = j * qbase + (j < rem ? j : rem);
    const uint32_t cnt = qbase + (j < rem ? 1u : 0u);
    const uint32_t g1 = g0 + cnt;
    const float *qh = q + (uint64_t)h * head_dim;
    float *row_scores = score_out + (uint64_t)h * n_score;
    const float scale = rsqrtf((float)head_dim);

    for (uint32_t g = g0 + threadIdx.x; g < g1; g += blockDim.x) {
        float s = -INFINITY;
        if (g < raw_count) {
            const uint32_t raw_row =
                (raw_start + raw_first_idx + g) % raw_cap;
            const float *kvrow = raw_kv + (uint64_t)raw_row * head_dim;
            const float dot = ds4_dot_scalar_ldg(qh, kvrow, head_dim);
            s = dot * scale;
        } else {
            const uint32_t cidx = g - raw_count;
            const float add = use_comp_mask ? comp_mask[(uint64_t)cidx] : 0.0f;
            if (add > -1.0e20f) {
                const float *kvrow = comp_kv + (uint64_t)cidx * head_dim;
                const float dot = ds4_dot_scalar_ldg(qh, kvrow, head_dim);
                s = dot * scale + add;
            }
        }
        row_scores[g] = s;
    }
}

/* Head-tiled exact score kernel for head_dim==512.
 *
 * The reference score kernel assigns one (head, row-chunk) per block and lets
 * every thread walk one KV row with a scalar sequential dot. Because MQA
 * shares the same KV rows across all 64 heads, that reference layout re-reads
 * every KV row once per head, and the per-thread row walk is fully
 * uncoalesced (threads stride 2KB apart), which multiplies L2 traffic again.
 *
 * This kernel keeps the per-score arithmetic bit-identical (same ascending-d
 * scalar accumulation `dot += q[d] * kv[d]`, same `dot * scale [+ add]`
 * epilogue, same masked-row/raw-window classification) but stages a 16-row KV
 * tile and a 16-head Q tile in shared memory with coalesced global loads, so
 * each KV row is read from L2 once per 16 heads instead of once per head.
 * Scores are independent outputs, so retiling the (head, row) space cannot
 * change any output bit as long as each individual dot keeps its order. */
#define DS4_SCORE_TILE_HEADS 16u
#define DS4_SCORE_TILE_ROWS 16u
#define DS4_SCORE_TILE_STRIDE 516u /* 512 + 4 floats: 16B-aligned rows, banks shifted by 4 */

__global__ static void attention_decode_score_split_scores_tile512_kernel(
        float *score_out,
        const float *q,
        const float *raw_kv,
        const float *comp_kv,
        const float *comp_mask,
        uint32_t use_comp_mask,
        uint32_t pos0,
        uint32_t n_raw,
        uint32_t raw_cap,
        uint32_t raw_start,
        uint32_t n_comp,
        uint32_t window,
        uint32_t ratio,
        uint32_t n_head,
        uint32_t head_dim) {
    const bool single_all = (ratio == 0u);
    const uint32_t qpos = pos0;
    const uint32_t first_raw_pos = pos0 + 1u - n_raw;
    uint32_t visible_comp = single_all ? n_comp : (n_comp ? (qpos + 1u) / ratio : 0u);
    if (visible_comp > n_comp) visible_comp = n_comp;

    uint32_t raw_count = 0;
    uint32_t raw_first_idx = 0;
    if (n_raw != 0) {
        const uint32_t raw_last_pos = first_raw_pos + n_raw - 1u;
        if (single_all) {
            raw_count = n_raw > 256u ? 256u : n_raw;
        } else if (qpos >= first_raw_pos) {
            uint32_t lo = first_raw_pos;
            if (window != 0 && qpos + 1u > window) {
                const uint32_t wlo = qpos + 1u - window;
                if (wlo > lo) lo = wlo;
            }
            const uint32_t hi = qpos < raw_last_pos ? qpos : raw_last_pos;
            if (hi >= lo) {
                raw_first_idx = lo - first_raw_pos;
                raw_count = hi - lo + 1u;
                if (raw_count > 256u) raw_count = 256u;
            }
        }
    }
    const uint32_t n_score = raw_count + visible_comp;
    if (n_score == 0u) return;

    extern __shared__ float score_tile_shared[];
    float *sh_q = score_tile_shared; /* 16 x 516 */
    float *sh_kv = sh_q + DS4_SCORE_TILE_HEADS * DS4_SCORE_TILE_STRIDE; /* 16 x 516 */
    __shared__ float sh_add[DS4_SCORE_TILE_ROWS];

    const uint32_t g_base = blockIdx.x * DS4_SCORE_TILE_ROWS;
    const uint32_t h_base = blockIdx.y * DS4_SCORE_TILE_HEADS;
    if (g_base >= n_score || h_base >= n_head) return;

    /* Cooperative Q tile load: 16 heads x 512 floats, float4 coalesced. */
    {
        const float4 *q4 = (const float4 *)(q + (uint64_t)h_base * 512u);
        const uint32_t tile_heads =
            n_head - h_base < DS4_SCORE_TILE_HEADS ? n_head - h_base : DS4_SCORE_TILE_HEADS;
        for (uint32_t idx = threadIdx.x; idx < tile_heads * 128u; idx += blockDim.x) {
            const uint32_t hh = idx >> 7u;      /* head within tile */
            const uint32_t dd = idx & 127u;     /* float4 within row */
            const float4 v = q4[hh * 128u + dd];
            float *dst = sh_q + hh * DS4_SCORE_TILE_STRIDE + dd * 4u;
            dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
        }
    }
    /* Row classification + mask staging (thread per row). */
    if (threadIdx.x < DS4_SCORE_TILE_ROWS) {
        const uint32_t g = g_base + threadIdx.x;
        float add = -INFINITY;
        if (g < n_score) {
            if (g < raw_count) {
                add = 0.0f; /* raw rows are always visible */
            } else {
                const uint32_t cidx = g - raw_count;
                add = use_comp_mask ? comp_mask[(uint64_t)cidx] : 0.0f;
            }
        }
        sh_add[threadIdx.x] = add;
    }
    __syncthreads();
    /* Cooperative KV tile load: two rows at a time, float4 coalesced.
     * Masked rows (add <= -1e20) are skipped; their scores never read KV. */
    {
        const uint32_t rows_per_pass = blockDim.x >> 7u; /* 128 threads per row */
        const uint32_t rr0 = threadIdx.x >> 7u;
        const uint32_t dd = threadIdx.x & 127u;
        for (uint32_t r = rr0; r < DS4_SCORE_TILE_ROWS; r += rows_per_pass) {
            const uint32_t g = g_base + r;
            if (g >= n_score) continue;
            const bool visible = g < raw_count || sh_add[r] > -1.0e20f;
            if (!visible) continue;
            const float4 *src;
            if (g < raw_count) {
                const uint32_t raw_row = (raw_start + raw_first_idx + g) % raw_cap;
                src = (const float4 *)(raw_kv + (uint64_t)raw_row * 512u);
            } else {
                const uint32_t cidx = g - raw_count;
                src = (const float4 *)(comp_kv + (uint64_t)cidx * 512u);
            }
            const float4 v = src[dd];
            float *dst = sh_kv + r * DS4_SCORE_TILE_STRIDE + dd * 4u;
            dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
        }
    }
    __syncthreads();

    /* One score per thread: r = tid&15 (consecutive threads, coalesced score
     * writes), h = tid>>4. The dot keeps the reference kernel's exact scalar
     * ascending-d accumulation. */
    const uint32_t r = threadIdx.x & (DS4_SCORE_TILE_ROWS - 1u);
    const uint32_t h = h_base + (threadIdx.x >> 4u);
    const uint32_t g = g_base + r;
    if (h >= n_head || g >= n_score) return;
    const float scale = rsqrtf((float)head_dim);
    float *row_scores = score_out + (uint64_t)h * n_score;
    const float *qh = sh_q + (uint64_t)(threadIdx.x >> 4u) * DS4_SCORE_TILE_STRIDE;
    const float *kvrow = sh_kv + (uint64_t)r * DS4_SCORE_TILE_STRIDE;
    float s = -INFINITY;
    const bool need_dot = g < raw_count || sh_add[r] > -1.0e20f;
    if (need_dot) {
        /* The reference kernel's runtime-trip loop compiles to one sequential
         * FFMA chain. Keep exactly that accumulation order here: batched loads
         * for latency hiding, but a single explicit ascending fma chain. */
        float dot = 0.0f;
#pragma unroll 1
        for (uint32_t d = 0; d < 512u; d += 8u) {
            const float a0 = qh[d + 0u], a1 = qh[d + 1u];
            const float a2 = qh[d + 2u], a3 = qh[d + 3u];
            const float a4 = qh[d + 4u], a5 = qh[d + 5u];
            const float a6 = qh[d + 6u], a7 = qh[d + 7u];
            const float b0 = kvrow[d + 0u], b1 = kvrow[d + 1u];
            const float b2 = kvrow[d + 2u], b3 = kvrow[d + 3u];
            const float b4 = kvrow[d + 4u], b5 = kvrow[d + 5u];
            const float b6 = kvrow[d + 6u], b7 = kvrow[d + 7u];
            dot = __fmaf_rn(a0, b0, dot);
            dot = __fmaf_rn(a1, b1, dot);
            dot = __fmaf_rn(a2, b2, dot);
            dot = __fmaf_rn(a3, b3, dot);
            dot = __fmaf_rn(a4, b4, dot);
            dot = __fmaf_rn(a5, b5, dot);
            dot = __fmaf_rn(a6, b6, dot);
            dot = __fmaf_rn(a7, b7, dot);
        }
        if (g < raw_count) {
            s = dot * scale;
        } else {
            /* The reference expression `dot * scale + add` contracts to one
             * FFMA; keep that exact contraction explicit. */
            s = __fmaf_rn(dot, scale, sh_add[r]);
        }
    }
    row_scores[g] = s;
}

/* Multi-session form of the exact tiled score kernel. Each z-slice selects a
 * private KV table entry, while every individual score keeps the same scalar
 * ascending-d FMA chain as the one-session kernel. */
__global__ static void attention_decode_score_split_scores_tile512_rows_kernel(
        float *score_out,
        const float *q,
        cuda_attention_decode_row_table rows,
        uint32_t n_rows,
        uint32_t score_stride,
        uint32_t n_head,
        uint32_t head_dim) {
    const uint32_t row = blockIdx.z;
    if (row >= n_rows) return;
    const ds4_gpu_attention_decode_row dsc = rows.row[row];
    if (dsc.indexed) return;

    const float *raw_kv = (const float *)(uintptr_t)dsc.raw_kv;
    const float *comp_kv = (const float *)(uintptr_t)dsc.comp_kv;
    const bool single_all = dsc.ratio == 0u;
    const uint32_t qpos = dsc.pos;
    const uint32_t first_raw_pos = dsc.pos + 1u - dsc.n_raw;
    uint32_t visible_comp = single_all
        ? dsc.n_comp
        : (dsc.n_comp ? (qpos + 1u) / dsc.ratio : 0u);
    if (visible_comp > dsc.n_comp) visible_comp = dsc.n_comp;

    uint32_t raw_count = 0u;
    uint32_t raw_first_idx = 0u;
    if (dsc.n_raw != 0u) {
        const uint32_t raw_last_pos = first_raw_pos + dsc.n_raw - 1u;
        if (single_all) {
            raw_count = dsc.n_raw > 256u ? 256u : dsc.n_raw;
        } else if (qpos >= first_raw_pos) {
            uint32_t lo = first_raw_pos;
            if (dsc.window != 0u && qpos + 1u > dsc.window) {
                const uint32_t wlo = qpos + 1u - dsc.window;
                if (wlo > lo) lo = wlo;
            }
            const uint32_t hi = qpos < raw_last_pos ? qpos : raw_last_pos;
            if (hi >= lo) {
                raw_first_idx = lo - first_raw_pos;
                raw_count = hi - lo + 1u;
                if (raw_count > 256u) raw_count = 256u;
            }
        }
    }
    const uint32_t n_score = raw_count + visible_comp;

    extern __shared__ float score_tile_shared[];
    float *sh_q = score_tile_shared;
    float *sh_kv = sh_q + DS4_SCORE_TILE_HEADS * DS4_SCORE_TILE_STRIDE;

    const uint32_t g_base = blockIdx.x * DS4_SCORE_TILE_ROWS;
    const uint32_t h_base = blockIdx.y * DS4_SCORE_TILE_HEADS;
    if (g_base >= n_score || h_base >= n_head) return;

    {
        const float4 *q4 = (const float4 *)(
            q + ((uint64_t)row * n_head + h_base) * head_dim);
        const uint32_t tile_heads =
            n_head - h_base < DS4_SCORE_TILE_HEADS
                ? n_head - h_base : DS4_SCORE_TILE_HEADS;
        for (uint32_t idx = threadIdx.x;
             idx < tile_heads * 128u;
             idx += blockDim.x) {
            const uint32_t hh = idx >> 7u;
            const uint32_t dd = idx & 127u;
            const float4 v = q4[hh * 128u + dd];
            float *dst = sh_q + hh * DS4_SCORE_TILE_STRIDE + dd * 4u;
            dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
        }
    }
    __syncthreads();
    {
        const uint32_t rows_per_pass = blockDim.x >> 7u;
        const uint32_t rr0 = threadIdx.x >> 7u;
        const uint32_t dd = threadIdx.x & 127u;
        for (uint32_t r = rr0; r < DS4_SCORE_TILE_ROWS; r += rows_per_pass) {
            const uint32_t g = g_base + r;
            if (g >= n_score) continue;
            const float4 *src;
            if (g < raw_count) {
                const uint32_t raw_row =
                    (dsc.raw_start + raw_first_idx + g) % dsc.raw_cap;
                src = (const float4 *)(raw_kv + (uint64_t)raw_row * head_dim);
            } else {
                src = (const float4 *)(comp_kv +
                    (uint64_t)(g - raw_count) * head_dim);
            }
            const float4 v = src[dd];
            float *dst = sh_kv + r * DS4_SCORE_TILE_STRIDE + dd * 4u;
            dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
        }
    }
    __syncthreads();

    const uint32_t r = threadIdx.x & (DS4_SCORE_TILE_ROWS - 1u);
    const uint32_t h = h_base + (threadIdx.x >> 4u);
    const uint32_t g = g_base + r;
    if (h >= n_head || g >= n_score) return;
    const float scale = rsqrtf((float)head_dim);
    float *row_scores = score_out +
        ((uint64_t)row * n_head + h) * score_stride;
    const float *qh = sh_q +
        (uint64_t)(threadIdx.x >> 4u) * DS4_SCORE_TILE_STRIDE;
    const float *kvrow = sh_kv + (uint64_t)r * DS4_SCORE_TILE_STRIDE;
    float dot = 0.0f;
#pragma unroll 1
    for (uint32_t dd = 0; dd < 512u; dd += 8u) {
        const float a0 = qh[dd + 0u], a1 = qh[dd + 1u];
        const float a2 = qh[dd + 2u], a3 = qh[dd + 3u];
        const float a4 = qh[dd + 4u], a5 = qh[dd + 5u];
        const float a6 = qh[dd + 6u], a7 = qh[dd + 7u];
        const float b0 = kvrow[dd + 0u], b1 = kvrow[dd + 1u];
        const float b2 = kvrow[dd + 2u], b3 = kvrow[dd + 3u];
        const float b4 = kvrow[dd + 4u], b5 = kvrow[dd + 5u];
        const float b6 = kvrow[dd + 6u], b7 = kvrow[dd + 7u];
        dot = __fmaf_rn(a0, b0, dot);
        dot = __fmaf_rn(a1, b1, dot);
        dot = __fmaf_rn(a2, b2, dot);
        dot = __fmaf_rn(a3, b3, dot);
        dot = __fmaf_rn(a4, b4, dot);
        dot = __fmaf_rn(a5, b5, dot);
        dot = __fmaf_rn(a6, b6, dot);
        dot = __fmaf_rn(a7, b7, dot);
    }
    row_scores[g] = g < raw_count
        ? dot * scale
        : __fmaf_rn(dot, scale, 0.0f);
}

__device__ __forceinline__ float ds4_dot512_float4_ordered(
        const float *a,
        const float *b) {
    const float4 *a4 = (const float4 *)a;
    const float4 *b4 = (const float4 *)b;
    float dot = 0.0f;
#pragma unroll 1
    for (uint32_t i = 0; i < 128u; i++) {
        const float4 av = a4[i];
        const float4 bv = b4[i];
        dot = __fadd_rn(dot, __fmul_rn(av.x, bv.x));
        dot = __fadd_rn(dot, __fmul_rn(av.y, bv.y));
        dot = __fadd_rn(dot, __fmul_rn(av.z, bv.z));
        dot = __fadd_rn(dot, __fmul_rn(av.w, bv.w));
    }
    return dot;
}

__device__ __forceinline__ float ds4_dot512_float4_plain(
        const float *a,
        const float *b) {
    const float4 *a4 = (const float4 *)a;
    const float4 *b4 = (const float4 *)b;
    float dot = 0.0f;
#pragma unroll 1
    for (uint32_t i = 0; i < 128u; i++) {
        const float4 av = a4[i];
        const float4 bv = b4[i];
        dot += av.x * bv.x;
        dot += av.y * bv.y;
        dot += av.z * bv.z;
        dot += av.w * bv.w;
    }
    return dot;
}

__global__ static void attention_decode_score_split_scores_vec4_kernel(
        float *score_out,
        const float *q,
        const float *raw_kv,
        const float *comp_kv,
        const float *comp_mask,
        uint32_t use_comp_mask,
        uint32_t pos0,
        uint32_t n_raw,
        uint32_t raw_cap,
        uint32_t raw_start,
        uint32_t n_comp,
        uint32_t window,
        uint32_t ratio,
        uint32_t n_head,
        uint32_t S) {
    const uint32_t h = blockIdx.y;
    const uint32_t j = blockIdx.z;
    if (h >= n_head || j >= S) return;
    const uint32_t head_dim = 512u;
    const bool single_all = (ratio == 0u);
    const uint32_t qpos = pos0;
    const uint32_t first_raw_pos = pos0 + 1u - n_raw;
    uint32_t visible_comp = single_all ? n_comp : (n_comp ? (qpos + 1u) / ratio : 0u);
    if (visible_comp > n_comp) visible_comp = n_comp;

    uint32_t raw_count = 0;
    uint32_t raw_first_idx = 0;
    if (n_raw != 0) {
        const uint32_t raw_last_pos = first_raw_pos + n_raw - 1u;
        if (single_all) {
            raw_count = n_raw > 256u ? 256u : n_raw;
        } else if (qpos >= first_raw_pos) {
            uint32_t lo = first_raw_pos;
            if (window != 0 && qpos + 1u > window) {
                const uint32_t wlo = qpos + 1u - window;
                if (wlo > lo) lo = wlo;
            }
            const uint32_t hi = qpos < raw_last_pos ? qpos : raw_last_pos;
            if (hi >= lo) {
                raw_first_idx = lo - first_raw_pos;
                raw_count = hi - lo + 1u;
                if (raw_count > 256u) raw_count = 256u;
            }
        }
    }
    const uint32_t n_score = raw_count + visible_comp;
    if (n_score == 0u) return;

    const uint32_t qbase = n_score / S;
    const uint32_t rem = n_score % S;
    const uint32_t g0 = j * qbase + (j < rem ? j : rem);
    const uint32_t cnt = qbase + (j < rem ? 1u : 0u);
    const uint32_t g1 = g0 + cnt;
    const float *qh = q + (uint64_t)h * head_dim;
    float *row_scores = score_out + (uint64_t)h * n_score;
    const float scale = rsqrtf((float)head_dim);

    for (uint32_t g = g0 + threadIdx.x; g < g1; g += blockDim.x) {
        float s = -INFINITY;
        if (g < raw_count) {
            const uint32_t raw_row =
                (raw_start + raw_first_idx + g) % raw_cap;
            const float *kvrow = raw_kv + (uint64_t)raw_row * head_dim;
            const float dot = ds4_dot512_float4_ordered(qh, kvrow);
            s = dot * scale;
        } else {
            const uint32_t cidx = g - raw_count;
            const float add = use_comp_mask ? comp_mask[(uint64_t)cidx] : 0.0f;
            if (add > -1.0e20f) {
                const float *kvrow = comp_kv + (uint64_t)cidx * head_dim;
                const float dot = ds4_dot512_float4_ordered(qh, kvrow);
                s = dot * scale + add;
            }
        }
        row_scores[g] = s;
    }
}

