    uint32_t np = 0;
    for (; np < 16u; np++) {
        uint32_t local_pair = local_start + np;
        if (local_pair >= counts[expert]) break;
        pair[np] = sorted_pairs[offsets[expert] + local_pair];
        xqb[np] = midq + (uint64_t)pair[np] * midq_blocks;
    }
    if (midq_blocks <= 8u) {
        for (uint32_t i = threadIdx.x; i < np * midq_blocks; i += blockDim.x) {
            uint32_t p = i / midq_blocks;
            uint32_t b = i - p * midq_blocks;
            sxq[p][b] = xqb[p][b];
        }
        __syncthreads();
        for (uint32_t p = 0; p < np; p++) xqb[p] = sxq[p];
    }
    for (uint32_t rr = 0; rr < ROW_SPAN / 32u; rr++) {
        uint32_t row = blockIdx.x * ROW_SPAN + row_lane + rr * 32u;
        if (row >= out_dim) continue;
        const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)expert * down_expert_bytes + (uint64_t)row * down_row_bytes);
        float acc[16] = {0.0f};
        for (uint32_t b = lane; b < midq_blocks; b += 8u) {
            dev_dot_q2_K_q8_K_block8(wr + b, xqb[0] ? xqb[0] + b : NULL, xqb[1] ? xqb[1] + b : NULL,
                                     xqb[2] ? xqb[2] + b : NULL, xqb[3] ? xqb[3] + b : NULL,
                                     xqb[4] ? xqb[4] + b : NULL, xqb[5] ? xqb[5] + b : NULL,
                                     xqb[6] ? xqb[6] + b : NULL, xqb[7] ? xqb[7] + b : NULL, np < 8u ? np : 8u, acc);
            if (np > 8u) {
                dev_dot_q2_K_q8_K_block8(wr + b, xqb[8] ? xqb[8] + b : NULL, xqb[9] ? xqb[9] + b : NULL,
                                         xqb[10] ? xqb[10] + b : NULL, xqb[11] ? xqb[11] + b : NULL,
                                         xqb[12] ? xqb[12] + b : NULL, xqb[13] ? xqb[13] + b : NULL,
                                         xqb[14] ? xqb[14] + b : NULL, xqb[15] ? xqb[15] + b : NULL, np - 8u, acc + 8);
            }
        }
        for (uint32_t p = 0; p < np; p++) {
            acc[p] = quarter_warp_sum_f32(acc[p], lane);
            if (lane == 0) {
                if (atomic_out) {
                    uint32_t tok = pair[p] / n_expert;
                    atomicAdd(down_out + (uint64_t)tok * out_dim + row, acc[p]);
                } else {
                    down_out[(uint64_t)pair[p] * out_dim + row] = acc[p];
                }
            }
        }
    }
}

__global__ static void moe_down_sorted_p2_qwarp32_kernel(
        float *down_out,
        const char *down_base,
        const cuda_block_q8_K *midq,
        const uint32_t *sorted_pairs,
        const int32_t *selected,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t midq_blocks,
        uint32_t out_dim,
        uint32_t n_expert,
        uint32_t pair_count) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t pair_lane = (threadIdx.x >> 3u) & 1u;
    uint32_t row = blockIdx.x * 16u + (threadIdx.x >> 4u);
    uint32_t sorted_idx = blockIdx.y * 2u + pair_lane;
    if (row >= out_dim || sorted_idx >= pair_count) return;
    uint32_t pair = sorted_pairs[sorted_idx];
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const cuda_block_q8_K *xq = midq + (uint64_t)pair * midq_blocks;
    float acc = 0.0f;
    for (uint32_t b = lane; b < midq_blocks; b += 8u) acc += dev_dot_q2_K_q8_K_block(wr + b, xq + b);
    acc = quarter_warp_sum_f32(acc, lane);
    if (lane == 0) down_out[(uint64_t)pair * out_dim + row] = acc;
}

__global__ static void moe_sum_kernel(float *out, const float *down, uint32_t out_dim, uint32_t n_expert, uint32_t n_tokens) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * out_dim;
    if (gid >= n) return;
    uint32_t tok = gid / out_dim;
    uint32_t row = gid - (uint64_t)tok * out_dim;
    float acc = 0.0f;
    for (uint32_t e = 0; e < n_expert; e++) acc += down[((uint64_t)tok * n_expert + e) * out_dim + row];
    out[gid] = acc;
}

__global__ static void moe_sum_owned_kernel(
        float *out,
        const float *down,
        const int32_t *selected,
        uint32_t out_dim,
        uint32_t n_expert,
        uint32_t n_tokens) {
    const uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t n = (uint64_t)n_tokens * out_dim;
    if (gid >= n) return;
    const uint32_t tok = (uint32_t)(gid / out_dim);
    const uint32_t row = (uint32_t)(gid - (uint64_t)tok * out_dim);
    float acc = 0.0f;
    #pragma unroll
    for (uint32_t slot = 0; slot < 6u; slot++) {
        if (slot >= n_expert) break;
        const uint64_t pair = (uint64_t)tok * n_expert + slot;
        const float value = selected[pair] >= 0
            ? down[pair * out_dim + row] : 0.0f;
        acc = __fadd_rn(acc, value);
    }
    out[gid] = acc;
}

__device__ static float dev_iq2_xxs_dot_f32(const cuda_block_iq2_xxs *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_iq2_xxs *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const uint16_t *q2 = xb->qs;
        const float *xf = x + (uint64_t)b * CUDA_QK_K;
        for (uint32_t ib32 = 0; ib32 < CUDA_QK_K / 32; ib32++) {
            const uint32_t aux_g = (uint32_t)q2[0] | ((uint32_t)q2[1] << 16);
            const uint32_t aux_s = (uint32_t)q2[2] | ((uint32_t)q2[3] << 16);
            q2 += 4;
            const float dl = d * (0.5f + (float)(aux_s >> 28)) * 0.25f;
            const uint8_t grids[4] = {
                (uint8_t)(aux_g & 0xffu),
                (uint8_t)((aux_g >> 8) & 0xffu),
                (uint8_t)((aux_g >> 16) & 0xffu),
                (uint8_t)((aux_g >> 24) & 0xffu),
            };
            for (uint32_t half = 0; half < 2; half++) {
                for (uint32_t g = 0; g < 2; g++) {
                    const uint32_t gi = half * 2 + g;
                    const uint64_t grid = cuda_iq2xxs_grid[grids[gi]];
                    const uint8_t signs = cuda_ksigns_iq2xs[(aux_s >> (14u * half + 7u * g)) & 127u];
                    for (uint32_t i = 0; i < 8; i++) {
                        float w = (float)((grid >> (8u * i)) & 0xffu);
                        if (signs & (1u << i)) w = -w;
                        acc += dl * w * xf[ib32 * 32u + half * 16u + g * 8u + i];
                    }
                }
            }
        }
    }
    return acc;
}

__device__ static float dev_q2_K_dot_f32(const cuda_block_q2_K *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_q2_K *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const float dmin = dev_f16_to_f32(xb->dmin);
        for (uint32_t il = 0; il < 16; il++) {
            const uint32_t chunk = il / 8u;
            const uint32_t pair = il & 1u;
            const uint32_t shift = ((il / 2u) & 3u) * 2u;
            const uint8_t sc = xb->scales[il];
            const float dl = d * (float)(sc & 0x0fu);
            const float ml = dmin * (float)(sc >> 4);
            const uint8_t *q = xb->qs + 32u * chunk + 16u * pair;
            const float *xf = x + (uint64_t)b * CUDA_QK_K + chunk * 128u + ((il % 8u) / 2u) * 32u + pair * 16u;
            for (uint32_t i = 0; i < 16; i++) {
                const float w = dl * (float)((q[i] >> shift) & 3u) - ml;
                acc += w * xf[i];
            }
        }
    }
    return acc;
}

__global__ static void moe_gate_up_mid_f32_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const char *gate_base,
        const char *up_base,
        const float *x,
        const int32_t *selected,
        const float *weights,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        float clamp) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= expert_mid_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    uint32_t expert = (uint32_t)expert_i;
    const uint32_t nb = expert_in_dim / CUDA_QK_K;
    const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const float *xr = x + (uint64_t)tok * expert_in_dim;
    float gate = 0.0f;
    float up = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) {
        gate += dev_iq2_xxs_dot_f32(gr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
        up += dev_iq2_xxs_dot_f32(ur + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    }
    __shared__ float partial_gate[256];
    __shared__ float partial_up[256];
    partial_gate[threadIdx.x] = gate;
    partial_up[threadIdx.x] = up;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            partial_gate[threadIdx.x] += partial_gate[threadIdx.x + stride];
            partial_up[threadIdx.x] += partial_up[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        gate = partial_gate[0];
        up = partial_up[0];
        if (clamp > 1.0e-6f) {
            if (gate > clamp) gate = clamp;
            if (up > clamp) up = clamp;
            if (up < -clamp) up = -clamp;
        }
        const uint64_t off = (uint64_t)pair * expert_mid_dim + row;
        gate_out[off] = gate;
        up_out[off] = up;
        mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[(uint64_t)tok * n_expert + slot];
    }
}

__global__ static void moe_down_f32_kernel(
        float *down_out,
        const char *down_base,
        const float *mid,
        const int32_t *selected,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        uint32_t n_expert) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= out_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    const uint32_t nb = expert_mid_dim / CUDA_QK_K;
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const float *xr = mid + (uint64_t)pair * expert_mid_dim;
    float acc = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) acc += dev_q2_K_dot_f32(wr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) down_out[(uint64_t)pair * out_dim + row] = partial[0];
}

/* Prefill graph capture over the MMQ tier (DS4_CUDA_PREFILL_GRAPH): the
 * streaming slot cache's compact expert table is a persistent fixed buffer
 * whose contents are refreshed per layer, so the MMQ launch sequence has
 * stable arguments across layers — capture once, replay per layer. */
static cudaGraphExec_t g_pg_exec = NULL;
static uint32_t g_pg_n_tokens = 0;
static uint64_t g_pg_request_assign = 0;   /* request-level selection count */
static int g_pg_tried = 0;
static int g_pg_disabled = 0;
static cudaStream_t g_pg_stream = NULL;
static cudaEvent_t g_pg_ev_pre = NULL, g_pg_ev_post = NULL;
/* Capture-time records: the graph bakes the compact-table pointers and the
 * n_experts bound (now captured at n_total_expert scale, see the mmq tier),
 * and replays are only valid while those still hold. */
static const char *g_pg_cap_gate = NULL;
static const char *g_pg_cap_up = NULL;
static const char *g_pg_cap_down = NULL;
static const char *g_pg_cap_sel = NULL;
static int g_pg_cap_experts = 0;
/* Measured VRAM charge of the pg graph instantiation (fee accounting). */
static uint64_t g_pg_fee_bytes = 0;

static int pg_mmq_tier(
        const char *gate_w, const char *up_w, const char *down_w,
        const int32_t *sel_ids,
        const float *x_ptr, const float *weights_ptr,
        float *gate_ptr, float *up_ptr, float *mid_ptr, float *down_ptr,
        float *out_ptr,
        uint32_t expert_mid_dim, uint32_t expert_in_dim,
        uint32_t out_dim, uint32_t n_tokens, uint32_t n_expert,
        int weight_experts, int cap_experts, float clamp,
        uint64_t n_assignments, int streaming_slot_valid) {
    /* The decode-graph machinery captures on the legacy stream; the pg
     * capture must live on its own stream to avoid colliding with it. */
    if (!g_pg_stream) {
        if (cudaStreamCreateWithFlags(&g_pg_stream, cudaStreamNonBlocking) !=
                cudaSuccess ||
            cudaEventCreateWithFlags(&g_pg_ev_pre, cudaEventDisableTiming) !=
                cudaSuccess ||
            cudaEventCreateWithFlags(&g_pg_ev_post, cudaEventDisableTiming) !=
                cudaSuccess) {
            fprintf(stderr, "ds4: pg stream create failed\n");
            g_pg_disabled = 1;
            return -1;
        }
    }
    /* The graph bakes the request's n_tokens into the kernel grids: a
     * different prompt length needs a fresh capture. */
    if (g_pg_exec && g_pg_n_tokens != n_tokens) {
        (void)cudaGraphExecDestroy(g_pg_exec);
        g_pg_exec = NULL;
        g_pg_tried = 0;
    }
    if (!g_pg_exec) {
        if (g_pg_tried) return -1;
        g_pg_tried = 1;
        g_pg_n_tokens = n_tokens;
        cudaError_t cerr = cudaStreamBeginCapture(
                g_pg_stream, cudaStreamCaptureModeThreadLocal);
        if (cerr != cudaSuccess) {
            fprintf(stderr, "ds4: pg begin capture failed: %s\n",
                    cudaGetErrorString(cerr));
            g_pg_disabled = 1;
            return -1;
        }
        int rc2 = ds4_mmq_iq2_xxs_moe_pair(
                gate_w, up_w, x_ptr, sel_ids,
                gate_ptr, up_ptr,
                (int)expert_mid_dim, (int)expert_in_dim,
                (int)n_tokens, cap_experts, (int)n_expert,
                g_pg_stream);
        if (rc2 == 0) {
            const uint64_t mid_floats = n_assignments * expert_mid_dim;
            moe_mmq_swiglu_weighted_clamp_kernel<<<
                    (uint32_t)((mid_floats + 255) / 256), 256, 0,
                    g_pg_stream>>>(
                    mid_ptr, gate_ptr, up_ptr, weights_ptr,
                    expert_mid_dim, n_tokens, n_expert, clamp);
            rc2 = cuda_ok(cudaGetLastError(),
                          "pg mmq swiglu capture") ? 0 : -1;
        }
        if (rc2 == 0) {
            rc2 = ds4_mmq_q2_K_moe(
                    down_w, mid_ptr, sel_ids, down_ptr,
                    (int)out_dim, (int)expert_mid_dim,
                    (int)n_assignments, cap_experts,
                    /*n_expert_used=*/1, g_pg_stream);
        }
        if (rc2 == 0) {
            const uint64_t n = (uint64_t)n_tokens * out_dim;
            moe_mmq_sum_kernel<<<(uint32_t)((n + 255) / 256), 256, 0,
                    g_pg_stream>>>(
                    out_ptr, down_ptr, NULL, out_dim, n_expert, n_tokens,
                    /*guard_nonfinite=*/1);
            rc2 = cuda_ok(cudaGetLastError(),
                          "pg mmq sum capture") ? 0 : -1;
        }
        cudaGraph_t gph = NULL;
        const cudaError_t cerr2 = cudaStreamEndCapture(g_pg_stream, &gph);
        if (rc2 != 0 || cerr2 != cudaSuccess || !gph) {
            fprintf(stderr, "ds4: pg capture failed rc=%d err=%s; "
                    "falling back to the launch path\n",
                    rc2, cudaGetErrorString(cerr2));
            if (gph) (void)cudaGraphDestroy(gph);
            g_pg_disabled = 1;
            return -1;
        }
        cudaGraphExec_t ex = NULL;
        {
            size_t free_before = 0, total_b = 0;
            (void)cudaMemGetInfo(&free_before, &total_b);
            if (cudaGraphInstantiate(&ex, gph, NULL, NULL, 0) != cudaSuccess) {
                fprintf(stderr, "ds4: pg graph instantiate failed\n");
                (void)cudaGraphDestroy(gph);
                g_pg_disabled = 1;
                return -1;
            }
            size_t free_after = 0;
            if (cudaMemGetInfo(&free_after, &total_b) == cudaSuccess &&
                free_after < free_before) {
                g_pg_fee_bytes = (uint64_t)(free_before - free_after);
                if (getenv("DS4_LM_DEBUG")) {
                    fprintf(stderr,
                            "ds4: pg graph instantiate charged %.1f MiB\n",
                            (double)g_pg_fee_bytes / 1048576.0);
                }
            }
        }
        (void)cudaGraphDestroy(gph);
        g_pg_exec = ex;
        g_pg_cap_gate = gate_w;
        g_pg_cap_up = up_w;
        g_pg_cap_down = down_w;
        g_pg_cap_sel = (const char *)sel_ids;
        g_pg_cap_experts = cap_experts;
        fprintf(stderr, "ds4: pg graph captured (mmq tier)\n");
    }
    /* Replay validity tripwire: the captured graph bakes the compact-table
     * base pointers and the n_experts bound.  A mid-request realloc or a
     * layer whose compact set exceeds the captured bound would make the
     * replay read freed memory or write out of bounds (the layer-2/3
     * illegal-access failures).  Refuse the replay and let the caller fall
     * back to the plain launch path for the rest of the request. */
    if (g_pg_exec &&
        (gate_w != g_pg_cap_gate || up_w != g_pg_cap_up ||
         down_w != g_pg_cap_down || (const char *)sel_ids != g_pg_cap_sel ||
         weight_experts > g_pg_cap_experts)) {
        fprintf(stderr,
                "ds4: pg replay guard tripped (ptr drift or experts %d > cap %d); "
                "disabling graph for this request\n",
                weight_experts, g_pg_cap_experts);
        g_pg_disabled = 1;
        return -1;
    }
    /* Ordering bridges: the replay must follow the upstream work on the
     * legacy stream, and downstream consumers must follow the replay. */
    (void)cudaEventRecord(g_pg_ev_pre, (cudaStream_t)0);
    (void)cudaStreamWaitEvent(g_pg_stream, g_pg_ev_pre, 0);
    if (streaming_slot_valid && g_stream_selected_upload_done_event) {
        (void)cudaStreamWaitEvent(g_pg_stream,
                                  g_stream_selected_upload_done_event, 0);
    }
    if (cudaGraphLaunch(g_pg_exec, g_pg_stream) != cudaSuccess) {
        fprintf(stderr, "ds4: pg graph replay failed; disabling\n");
        (void)cudaGraphExecDestroy(g_pg_exec);
        g_pg_exec = NULL;
        g_pg_disabled = 1;
        return -1;
    }
    (void)cudaEventRecord(g_pg_ev_post, g_pg_stream);
    (void)cudaStreamWaitEvent((cudaStream_t)0, g_pg_ev_post, 0);
    return 0;
}

/* Per-request reset: the graph, stream and events never survive across
 * requests (a captured graph from one request poisoned the next request's
 * layer-major encode on oversized prompts; see FUSION_REPORT).  Re-capture
 * per request costs milliseconds against a multi-second prefill. */
/* Free device memory for the budget-driven sub-batch sizing. */
extern "C" uint64_t ds4_gpu_free_bytes(void) {
    size_t free_b = 0, total_b = 0;
    if (cudaMemGetInfo(&free_b, &total_b) != cudaSuccess) return 0;
    return (uint64_t)free_b;
}

/* Measured compact-table capacity (the slot consumer's actual quota). */
extern "C" uint64_t ds4_gpu_slot_table_capacity_bytes(void) {
    return (uint64_t)g_stream_selected_cache.gate_capacity +
           (uint64_t)g_stream_selected_cache.up_capacity +
           (uint64_t)g_stream_selected_cache.down_capacity;
}

/* Peak per-layer union footprint since the last reset (scheduler telemetry). */
extern "C" uint64_t ds4_gpu_slot_peak_union_bytes(void) {
    return g_stream_selected_cache.peak_union_bytes;
}

extern "C" void ds4_gpu_slot_peak_reset(void) {
    g_stream_selected_cache.peak_union_bytes = 0;
}

/* Measured VRAM charge of the pg graph instantiation (fee accounting). */
extern "C" uint64_t ds4_gpu_pg_fee_bytes(void) {
    return g_pg_fee_bytes;
}

extern "C" void ds4_gpu_pg_reset(uint64_t request_assignments) {
    if (g_pg_exec) {
        (void)cudaGraphExecDestroy(g_pg_exec);
        g_pg_exec = NULL;
    }
    if (g_pg_ev_pre) {
        (void)cudaEventDestroy(g_pg_ev_pre);
        g_pg_ev_pre = NULL;
    }
    if (g_pg_ev_post) {
        (void)cudaEventDestroy(g_pg_ev_post);
        g_pg_ev_post = NULL;
    }
    if (g_pg_stream) {
        (void)cudaStreamDestroy(g_pg_stream);
        g_pg_stream = NULL;
    }
    g_pg_request_assign = request_assignments;
    g_pg_tried = 0;
    g_pg_disabled = 0;
    g_pg_n_tokens = 0;
    g_pg_fee_bytes = 0;
    g_pg_cap_gate = NULL;
    g_pg_cap_up = NULL;
    g_pg_cap_down = NULL;
    g_pg_cap_sel = NULL;
    g_pg_cap_experts = 0;
}

static int routed_moe_launch(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *model_map,
        uint64_t model_size,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_total_expert,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        uint32_t layer_index,
        uint32_t n_tokens,
        int allow_streaming,
        int owned_filtered) {
    if (!out || !gate || !up || !mid || !down || !model_map || !selected || !weights || !x ||
        n_tokens == 0 || n_total_expert == 0 || n_expert == 0 ||
        expert_in_dim % CUDA_QK_K != 0 || expert_mid_dim % CUDA_QK_K != 0 ||
        gate_offset > model_size || up_offset > model_size || down_offset > model_size ||
        x->bytes < (uint64_t)n_tokens * expert_in_dim * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        gate->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        up->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        mid->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        down->bytes < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float) ||
        out->bytes < (uint64_t)n_tokens * out_dim * sizeof(float)) {
        return 0;
    }
    const int q4k_path = (gate_type == 12u && down_type == 12u);
    const int iq2_path = (gate_type == 16u && down_type == 10u);
    const int mxfp4_path = (gate_type == 39u && down_type == 39u);
    if (getenv("DS4_CUDA_MOE_ENTRY_LOG")) {
        fprintf(stderr,
                "ds4: CUDA MoE entry tokens=%u owned=%d q4k=%d iq2=%d mxfp4=%d streaming=%d gate_type=%u down_type=%u layer=%u\n",
                n_tokens, owned_filtered, q4k_path, iq2_path, mxfp4_path,
                g_ssd_streaming_mode ? 1 : 0, gate_type, down_type, layer_index);
        fflush(stderr);
    }
    if (!q4k_path && !iq2_path && !mxfp4_path) return 0;

    /* The aligned artifacts replace the raw expert tensors on integrated
     * CUDA systems.  Route both prefill and decode before resolving a raw
     * pointer, otherwise the fallback cache would duplicate tens of GiB. */
    if (iq2_path && !owned_filtered && !g_ssd_streaming_mode &&
        cuda_aligned_iq2_enabled() && cuda_aligned_q2k_enabled()) {
        const uint64_t gate_total = (uint64_t)n_total_expert * gate_expert_bytes;
        const uint64_t down_total = (uint64_t)n_total_expert * down_expert_bytes;
        const uint64_t gate_aligned_bytes = ds4_mmq_iq2_xxs_aligned_bytes(
            (int)expert_mid_dim, (int)expert_in_dim, (int)n_total_expert);
        const uint64_t down_aligned_bytes = ds4_mmq_q2_k_aligned_bytes(
            (int)out_dim, (int)expert_mid_dim, (int)n_total_expert);
        const char *gate_aligned = cuda_derived_weight_ptr(
            model_map, gate_offset, gate_total,
            CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE,
            expert_in_dim, expert_mid_dim, n_total_expert,
            gate_aligned_bytes);
        const char *up_aligned = cuda_derived_weight_ptr(
            model_map, up_offset, gate_total,
            CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE,
            expert_in_dim, expert_mid_dim, n_total_expert,
            gate_aligned_bytes);
        const char *down_aligned = cuda_derived_weight_ptr(
            model_map, down_offset, down_total,
            CUDA_DERIVED_Q2_K_ALIGNED_MOE,
            expert_mid_dim, out_dim, n_total_expert,
            down_aligned_bytes);
        if (gate_aligned && up_aligned && down_aligned) {
            const cudaStream_t aligned_stream =
                n_tokens == 1u ? cuda_decode_stream() : (cudaStream_t)0;
            int rc;
            if (n_tokens == 1u) {
                rc = ds4_mmq_iq2_xxs_aligned_moe_gate_up_mid_vec(
                    gate_aligned, up_aligned,
                    (const float *)x->ptr,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    (float *)mid->ptr,
                    (int)expert_mid_dim, (int)expert_in_dim,
                    (int)n_tokens, (int)n_total_expert, (int)n_expert,
                    clamp, aligned_stream);
                if (rc == 0) {
                    const uint32_t assignments = n_tokens * n_expert;
                    rc = ds4_mmq_q2_K_aligned_moe_vec(
                        down_aligned, (const float *)mid->ptr,
                        (const int32_t *)selected->ptr,
                        (float *)down->ptr,
                        (int)out_dim, (int)expert_mid_dim,
                        (int)assignments, (int)n_total_expert,
                        /*n_expert_used=*/1,
                        aligned_stream);
                }
            } else {
                rc = 1;
                const uint64_t assignments =
                    (uint64_t)n_tokens * n_expert;
                if (assignments >= 1024u) {
                    size_t input_q8_bytes = 0;
                    size_t down_q8_bytes = 0;
                    size_t work_bytes = 0;
                    if (ds4_mmq_iq2_xxs_q2_K_moe_fused_direct_scratch_sizes(
                            (int)expert_mid_dim, (int)expert_in_dim,
                            (int)n_tokens, (int)n_total_expert,
                            (int)n_expert, &input_q8_bytes,
                            &down_q8_bytes, &work_bytes) == 0 &&
                        gate->bytes >= input_q8_bytes &&
                        up->bytes >= down_q8_bytes &&
                        mid->bytes >= work_bytes) {
                        rc = ds4_mmq_iq2_xxs_q2_K_moe_fused_direct_soa(
                            gate_aligned, up_aligned, down_aligned,
                            (const float *)x->ptr,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate->ptr, input_q8_bytes,
                            up->ptr, down_q8_bytes,
                            mid->ptr, work_bytes,
                            NULL, 0,
                            (float *)down->ptr,
                            (int)expert_mid_dim, (int)expert_in_dim,
                            (int)out_dim, (int)n_tokens,
                            (int)n_total_expert, (int)n_expert,
                            clamp, aligned_stream);
                        if (rc == 0) {
                            static int direct_logged = 0;
                            if (!direct_logged) {
                                direct_logged = 1;
                                fprintf(stderr,
                                        "ds4: routed MoE using fused-direct CUDA prefill\n");
                            }
                        }
                    }
                }
                if (rc != 0) {
                    rc = ds4_mmq_iq2_xxs_q2_K_moe_fused_soa(
                        gate_aligned, up_aligned, down_aligned,
                        (const float *)x->ptr,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        (float *)gate->ptr, (float *)up->ptr,
                        (float *)mid->ptr, (float *)down->ptr,
                        (int)expert_mid_dim, (int)expert_in_dim,
                        (int)out_dim, (int)n_tokens,
                        (int)n_total_expert, (int)n_expert,
                        clamp, aligned_stream);
                }
            }
            if (rc == 0) {
                const uint64_t n = (uint64_t)n_tokens * out_dim;
                moe_mmq_sum_kernel<<<
                    (uint32_t)((n + 255u) / 256u), 256, 0, aligned_stream>>>(
                    (float *)out->ptr, (const float *)down->ptr,
                    NULL, out_dim, n_expert, n_tokens,
                    /*guard_nonfinite=*/1);
                if (cuda_ok(cudaGetLastError(), "aligned moe sum launch")) {
                    static int logged = 0;
                    if (!logged) {
                        logged = 1;
                        fprintf(stderr,
                                "ds4: routed MoE using aligned CUDA artifacts\n");
                    }
                    return 1;
                }
                rc = -1;
            }
            fprintf(stderr,
                    "ds4: aligned routed-MoE returned %d "
                    "(layer=%u n_tokens=%u)\n",
                    rc, layer_index, n_tokens);
            if (cuda_model_map_replaces_complete(model_map)) return 0;
        }
    }

    /* Native MXFP4 routed experts use the vendored MMVQ decode kernels and
     * MMQ matrix kernels. On Blackwell the latter dispatch to FP4 MMA; older
     * CUDA devices use the mathematically equivalent DP4A implementation.
     * SSD streaming presents a compact table containing only the selected
     * experts, together with IDs remapped into that table. */
    if (mxfp4_path) {
        if (!cuda_use_mxfp4_mmq()) {
            fprintf(stderr, "ds4: CUDA MXFP4 requires the MMQ backend\n");
            return 0;
        }
        const uint64_t gate_total =
            (uint64_t)n_total_expert * gate_expert_bytes;
        const uint64_t down_total =
            (uint64_t)n_total_expert * down_expert_bytes;
        if (gate_total > model_size - gate_offset ||
            gate_total > model_size - up_offset ||
            down_total > model_size - down_offset) {
            return 0;
        }

        const uint64_t slot_count = (uint64_t)n_tokens * n_expert;
        const int logical_tier = ds4_tensor_device_idx(out);
        /* Incremental residency (Windows/8GB fusion port): the compact table
         * is a persistent superset across layers; layer/offset equality no
         * longer applies, the table just has to be live and large enough. */
        const int use_stream_selected_cache =
            allow_streaming &&
            g_ssd_streaming_mode &&
            g_stream_selected_cache.valid &&
            g_stream_selected_cache.logical_tier == logical_tier &&
            g_stream_selected_cache.model_map == model_map &&
            g_stream_selected_cache.n_total_expert == n_total_expert &&
            g_stream_selected_cache.slot_count >= slot_count &&
            g_stream_selected_cache.gate_expert_bytes == gate_expert_bytes &&
            g_stream_selected_cache.down_expert_bytes == down_expert_bytes &&
            g_stream_selected_cache.gate_ptr &&
            g_stream_selected_cache.up_ptr &&
            g_stream_selected_cache.down_ptr &&
            g_stream_selected_cache.slot_selected_tensor.ptr &&
            g_stream_selected_cache.slot_selected_tensor.bytes >=
                slot_count * sizeof(int32_t);
        if (g_ssd_streaming_mode && allow_streaming &&
            !use_stream_selected_cache) {
            fprintf(stderr,
                    "ds4: CUDA streaming MXFP4 experts are unavailable for layer %u\n",
                    layer_index);
            return 0;
        }

        const ds4_gpu_tensor *mx_selected = use_stream_selected_cache ?
            &g_stream_selected_cache.slot_selected_tensor : selected;
        const uint32_t weight_experts = use_stream_selected_cache ?
            g_stream_selected_cache.compact_count : n_total_expert;
        const char *gate_w = use_stream_selected_cache ?
            g_stream_selected_cache.gate_ptr :
            cuda_resolve_weight_ptr(model_map, gate_offset, gate_total,
                                    logical_tier, "mxfp4 moe gate");
        const char *up_w = use_stream_selected_cache ?
            g_stream_selected_cache.up_ptr :
            cuda_resolve_weight_ptr(model_map, up_offset, gate_total,
                                    logical_tier, "mxfp4 moe up");
        const char *down_w = use_stream_selected_cache ?
            g_stream_selected_cache.down_ptr :
            cuda_resolve_weight_ptr(model_map, down_offset, down_total,
                                    logical_tier, "mxfp4 moe down");
        if (!gate_w || !up_w || !down_w || weight_experts == 0u) return 0;

        const cudaStream_t stream =
            n_tokens == 1u ? cuda_decode_stream() : (cudaStream_t)0;
        int rc = -1;
        if (n_tokens == 1u && n_expert == 6u) {
            rc = ds4_mmq_mxfp4_moe_gate_up_mid_vec(
                gate_w, up_w, (const float *)x->ptr,
                (const int32_t *)mx_selected->ptr,
                (const float *)weights->ptr, (float *)mid->ptr,
                (int)expert_mid_dim, (int)expert_in_dim,
                (int)n_tokens, (int)weight_experts, (int)n_expert,
                clamp, stream);
            if (rc == 0) {
                if (use_stream_selected_cache &&
                    g_stream_selected_upload_done_event) {
                    (void)cudaStreamWaitEvent(
                            (cudaStream_t)0,
                            g_stream_selected_upload_done_event, 0);
                }
                rc = ds4_mmq_mxfp4_moe_down_sum6_vec(
                    down_w, (const float *)mid->ptr,
                    (const int32_t *)mx_selected->ptr, (float *)out->ptr,
                    (int)out_dim, (int)expert_mid_dim,
                    (int)n_tokens, (int)weight_experts, (int)n_expert,
                    stream);
            }
        } else {
            rc = ds4_mmq_mxfp4_moe_pair(
                gate_w, up_w, (const float *)x->ptr,
                (const int32_t *)mx_selected->ptr,
                (float *)gate->ptr, (float *)up->ptr,
                (int)expert_mid_dim, (int)expert_in_dim,
                (int)n_tokens, (int)weight_experts, (int)n_expert,
                stream);
            if (rc == 0) {
                const uint64_t mid_floats =
                    slot_count * expert_mid_dim;
                moe_mmq_swiglu_weighted_clamp_kernel<<<
                    (uint32_t)((mid_floats + 255u) / 256u), 256, 0, stream>>>(
                    (float *)mid->ptr,
                    (const float *)gate->ptr, (const float *)up->ptr,
                    (const float *)weights->ptr,
                    expert_mid_dim, n_tokens, n_expert, clamp);
                rc = cuda_ok(cudaGetLastError(),
                             "mxfp4 moe swiglu launch") ? 0 : -1;
            }
            if (rc == 0) {
                if (use_stream_selected_cache &&
                    g_stream_selected_upload_done_event) {
                    (void)cudaStreamWaitEvent(
                            (cudaStream_t)0,
                            g_stream_selected_upload_done_event, 0);
                }
                rc = ds4_mmq_mxfp4_moe(
                    down_w, (const float *)mid->ptr,
                    (const int32_t *)mx_selected->ptr,
                    (float *)down->ptr,
                    (int)out_dim, (int)expert_mid_dim,
                    (int)slot_count, (int)weight_experts,
                    /*n_expert_used=*/1, stream);
            }
            if (rc == 0) {
                const uint64_t n = (uint64_t)n_tokens * out_dim;
                moe_mmq_sum_kernel<<<
                    (uint32_t)((n + 255u) / 256u), 256, 0, stream>>>(
                    (float *)out->ptr, (const float *)down->ptr,
                    owned_filtered
                        ? (const int32_t *)mx_selected->ptr
                        : NULL,
                    out_dim, n_expert, n_tokens, /*guard_nonfinite=*/1);
                rc = cuda_ok(cudaGetLastError(),
                             "mxfp4 moe sum launch") ? 0 : -1;
            }
            if (rc == 0 && use_stream_selected_cache &&
                g_stream_selected_compute_done_event) {
                /* Same decode determinism fix as the direct-down-sum path:
                 * publish compute-done so the next layer's slot uploads wait
                 * for these kernels before overwriting the table. */
                (void)cudaEventRecord(g_stream_selected_compute_done_event,
                                      (cudaStream_t)0);
            }
        }
        if (rc == 0) return 1;
        fprintf(stderr,
                "ds4: CUDA MXFP4 routed-MoE returned %d "
                "(layer=%u n_tokens=%u)\n",
                rc, layer_index, n_tokens);
        return 0;
    }
    /* mmq routed-MoE prefill tier (ported from the Entrpi/ds4 fork).
     * IQ2_XXS gate/up pair (one shared activation quantize + routing
     * pass) -> SwiGLU + clamp + router weight -> Q2_K down, treating
     * each (token, slot) assignment as its own single-expert row ->
     * guarded slot sum.  Buffers gate/up/mid/down are already sized to
     * [n_tokens, n_expert, *] by the validation above.  Any entry
     * failure falls through to the legacy sorted-pairs path (the
     * buffers are scratch there too).
     *
     * Windows/8GB fusion port: this tier resolves the FULL expert table
     * (~1.7 GiB) outside the streaming slot cache; on ssd-streaming
     * configs the arena OOM then falls back to a HOST pointer, which the
     * mmq kernels dereference on device -> illegal memory access (and
     * the cascade poisons the batch selected ids with -1 sentinels).
     * Skip the tier under streaming so the batch prefill uses the
     * compact slot-cache path below instead. */
    const bool streaming_slot_valid =
        g_ssd_streaming_mode && g_stream_selected_cache.valid &&
        g_stream_selected_cache.logical_tier == ds4_tensor_device_idx(out) &&
        g_stream_selected_cache.model_map == model_map &&
        g_stream_selected_cache.n_total_expert == n_total_expert &&
        g_stream_selected_cache.slot_count >= (uint64_t)n_tokens * n_expert &&
        g_stream_selected_cache.gate_expert_bytes == gate_expert_bytes &&
        g_stream_selected_cache.down_expert_bytes == down_expert_bytes &&
        g_stream_selected_cache.gate_ptr &&
        g_stream_selected_cache.up_ptr &&
        g_stream_selected_cache.down_ptr &&
        g_stream_selected_cache.slot_selected_tensor.ptr &&
        g_stream_selected_cache.slot_selected_tensor.bytes >=
            (uint64_t)n_tokens * n_expert * sizeof(int32_t);
    if (iq2_path && n_tokens > 1u && !owned_filtered && cuda_use_mmq()) {
        /* Windows/8GB fusion port (compact mmq): under SSD streaming, run the
         * mmq tier over the streaming slot cache's compact expert table and
         * the remapped slot ids instead of resolving the full per-layer
         * expert table (~1.7 GiB), which cannot fit the streaming arena. */
        const char *gate_w = NULL, *up_w = NULL, *down_w = NULL;
        const int32_t *sel_ids = NULL;
        int weight_experts = 0;
        if (streaming_slot_valid) {
            gate_w = g_stream_selected_cache.gate_ptr;
            up_w = g_stream_selected_cache.up_ptr;
            down_w = g_stream_selected_cache.down_ptr;
            sel_ids = (const int32_t *)g_stream_selected_cache.slot_selected_tensor.ptr;
            weight_experts = (int)g_stream_selected_cache.compact_count;
            if (getenv("DS4_LM_DEBUG")) {
                fprintf(stderr,
                        "ds4: compact mmq layer=%u tokens=%u experts=%d\n",
                        layer_index, n_tokens, weight_experts);
            }
        } else {
            const uint64_t gate_total = (uint64_t)n_total_expert * gate_expert_bytes;
            const uint64_t down_total = (uint64_t)n_total_expert * down_expert_bytes;
            const int mmq_tier = ds4_tensor_device_idx(out);
            gate_w = cuda_resolve_weight_ptr(model_map, gate_offset, gate_total, mmq_tier, "moe gate mmq");
            up_w = gate_w ? cuda_resolve_weight_ptr(model_map, up_offset, gate_total, mmq_tier, "moe up mmq") : NULL;
            down_w = up_w ? cuda_resolve_weight_ptr(model_map, down_offset, down_total, mmq_tier, "moe down mmq") : NULL;
            sel_ids = (const int32_t *)selected->ptr;
            weight_experts = (int)n_total_expert;
        }
        if (down_w) {
            {
                /* Drain and report sticky errors at the tier entry to bisect
                 * where the invalid-resource-handle originates. */
                const cudaError_t t_err = cudaGetLastError();
                if (t_err != cudaSuccess) {
                    fprintf(stderr,
                            "ds4: mmq tier entry sticky drained: %s (layer=%u)\n",
                            cudaGetErrorString(t_err), layer_index);
                    fflush(stderr);
                }
            }
            const uint32_t profile_mmq = getenv("DS4_CUDA_MOE_PROFILE_MMQ") != NULL;
            const uint32_t probe_create =
                getenv("DS4_CUDA_MOE_PROFILE_MMQ_CREATE") != NULL &&
                !profile_mmq;
            const uint32_t probe_record =
                getenv("DS4_CUDA_MOE_PROFILE_MMQ_RECORD") != NULL &&
                !profile_mmq;
            cudaEvent_t mmq_ev[5] = {NULL, NULL, NULL, NULL, NULL};
            uint64_t mmq_wall0 = 0;
            if (profile_mmq) {
                for (uint32_t i = 0; i < 5u; i++) (void)cudaEventCreate(&mmq_ev[i]);
                mmq_wall0 = GetTickCount64();
                if (mmq_ev[0]) (void)cudaEventRecord(mmq_ev[0], (cudaStream_t)0);
            } else if (probe_create) {
                /* A/B probe: create+destroy event objects only, no records
                 * and no sync — isolates the driver resource churn. */
                for (uint32_t i = 0; i < 5u; i++) {
                    cudaEvent_t ev = NULL;
                    (void)cudaEventCreate(&ev);
                    (void)cudaEventDestroy(ev);
                }
            } else if (probe_record) {
                /* A/B probe: record only at the profile points (four
                 * SEPARATE pre-created events), no host sync — isolates the
                 * multi-point stream-marker effect.  The env value is a
                 * bitmask: 1=entry 2=after-pair 4=after-swiglu 8=after-down
                 * (0/default = all four). */
                static cudaEvent_t probe_ev[4] = {NULL, NULL, NULL, NULL};
                static int probe_init = 0;
                static uint32_t probe_mask = 0;
                if (!probe_init) {
                    probe_init = 1;
                    probe_mask = (uint32_t)atoi(getenv("DS4_CUDA_MOE_PROFILE_MMQ_RECORD"));
                    if (probe_mask == 0) probe_mask = 0xFu;
                    const int notime = getenv("DS4_CUDA_MOE_PROFILE_MMQ_RECORD_NOTIME") != NULL;
                    for (int pi = 0; pi < 4; pi++) {
                        if (notime) {
                            (void)cudaEventCreateWithFlags(&probe_ev[pi],
                                                           cudaEventDisableTiming);
                        } else {
                            (void)cudaEventCreate(&probe_ev[pi]);
                        }
                    }
                }
                if (probe_mask & 1u) mmq_ev[0] = probe_ev[0];
                if (probe_mask & 2u) mmq_ev[1] = probe_ev[1];
                if (probe_mask & 4u) mmq_ev[2] = probe_ev[2];
                if (probe_mask & 8u) mmq_ev[3] = probe_ev[3];
                if (mmq_ev[0]) (void)cudaEventRecord(mmq_ev[0], (cudaStream_t)0);
            }
            const uint64_t n_assignments = (uint64_t)n_tokens * n_expert;
            /* Prefill graph capture over the MMQ tier: the compact expert
             * table pointers are stable across layers, so capture once and
             * replay per layer (staging refreshes the table contents).
             * Request gate: the default bound (4096 assignments) exists
             * only because the pre-OOB-fix builds poisoned large requests;
             * with the replay guard + full-table prealloc the gate is a
             * proven-safe default, and DS4_CUDA_PREFILL_GRAPH_LARGE=1 lifts
             * it to measure whole-batch pg on long prompts (③ experiment). */
            const bool pg_gate_open =
                g_pg_request_assign <= 4096u ||
                getenv("DS4_CUDA_PREFILL_GRAPH_LARGE") != NULL;
            if (getenv("DS4_CUDA_PREFILL_GRAPH") != NULL && !g_pg_disabled &&
                streaming_slot_valid && pg_gate_open &&
                (g_pg_exec || !g_pg_tried)) {
                /* Capture at the full-table expert count: the graph bakes
                 * n_experts into the ids-helper bounds arrays, and the
                 * compact set grows/shrinks per layer (227..258 measured).
                 * Baking the per-layer count made the replay write
                 * expert_bounds OOB whenever a later layer's union exceeded
                 * the capture-time one (the layer-2/3 illegal accesses).
                 * Unused expert slots are zero-row tiles by construction. */
                const uint64_t pg_wall0 = profile_mmq ? GetTickCount64() : 0;
                if (pg_mmq_tier(gate_w, up_w, down_w, sel_ids,
                                (const float *)x->ptr,
                                (const float *)weights->ptr,
                                (float *)gate->ptr, (float *)up->ptr,
                                (float *)mid->ptr, (float *)down->ptr,
                                (float *)out->ptr,
                                expert_mid_dim, expert_in_dim,
                                out_dim, n_tokens, n_expert,
                                weight_experts, (int)n_total_expert,
                                clamp, n_assignments,
                                streaming_slot_valid ? 1 : 0) == 0) {
                    if (profile_mmq) {
                        fprintf(stderr,
                                "ds4: CUDA MoE mmq pg tokens=%u wall=%.3f ms layer=%u\n",
                                n_tokens,
                                (double)(GetTickCount64() - pg_wall0), layer_index);
                        fflush(stderr);
                    }
                    if (g_stream_selected_compute_done_event) {
                        (void)cudaEventRecord(g_stream_selected_compute_done_event,
                                              g_pg_stream ? g_pg_stream
                                                          : (cudaStream_t)0);
                    }
                    return 1;
                }
            }
            int rc = ds4_mmq_iq2_xxs_moe_pair(
                    gate_w, up_w, (const float *)x->ptr,
                    sel_ids,
                    (float *)gate->ptr, (float *)up->ptr,
                    (int)expert_mid_dim, (int)expert_in_dim,
                    (int)n_tokens, weight_experts, (int)n_expert,
                    (cudaStream_t)0);
            if ((profile_mmq || probe_record) && mmq_ev[1]) (void)cudaEventRecord(mmq_ev[1], (cudaStream_t)0);
            if (getenv("DS4_CUDA_MOE_STICKY_TRACE")) {
                const cudaError_t s1 = cudaGetLastError();
                if (s1 != cudaSuccess) {
                    fprintf(stderr, "ds4: sticky after pair layer=%u: %s\n",
                            layer_index, cudaGetErrorString(s1));
                    fflush(stderr);
                }
            }
            if (getenv("DS4_CUDA_MOE_HASH_STAGES")) {
                /* Stage probe: hash the first slot's gate/up row right after
                 * the pair (host read = legacy barrier). */
                uint64_t hg = 1469598103934665603ull;
                float hbuf[512];
                if (cudaMemcpy(hbuf, gate->ptr, sizeof(hbuf),
                               cudaMemcpyDeviceToHost) == cudaSuccess) {
                    for (int hi = 0; hi < 512; hi++) {
                        uint32_t w;
                        memcpy(&w, &hbuf[hi], 4);
                        hg ^= (uint64_t)w;
                        hg *= 1099511628211ull;
                    }
                }
                fprintf(stderr,
                        "ds4: MoE hash_pair layer=%u hash=%016llx\n",
                        layer_index, (unsigned long long)hg);
                fflush(stderr);
            }
            if (rc == 0) {
                const uint64_t mid_floats = n_assignments * expert_mid_dim;
                moe_mmq_swiglu_weighted_clamp_kernel<<<(uint32_t)((mid_floats + 255) / 256), 256>>>(
                        (float *)mid->ptr,
                        (const float *)gate->ptr, (const float *)up->ptr,
                        (const float *)weights->ptr,
                        expert_mid_dim, n_tokens, n_expert, clamp);
                rc = cuda_ok(cudaGetLastError(), "mmq moe swiglu launch") ? 0 : -1;
            }
            if ((profile_mmq || probe_record) && mmq_ev[2]) (void)cudaEventRecord(mmq_ev[2], (cudaStream_t)0);
            if (getenv("DS4_CUDA_MOE_STICKY_TRACE")) {
                const cudaError_t s2 = cudaGetLastError();
                if (s2 != cudaSuccess) {
                    fprintf(stderr, "ds4: sticky after swiglu layer=%u: %s\n",
                            layer_index, cudaGetErrorString(s2));
                    fflush(stderr);
                }
            }
            if (rc == 0) {
                /* Split-phase pipeline: the down rows' DMA may still be in
                 * flight; wait for the upload stream before reading them. */
                if (streaming_slot_valid &&
                    g_stream_selected_upload_done_event) {
                    (void)cudaStreamWaitEvent(
                            (cudaStream_t)0,
                            g_stream_selected_upload_done_event, 0);
                }
                rc = ds4_mmq_q2_K_moe(
                        down_w, (const float *)mid->ptr,
                        sel_ids,
                        (float *)down->ptr,
                        (int)out_dim, (int)expert_mid_dim,
                        (int)n_assignments, weight_experts,
                        /*n_expert_used=*/1,
                        (cudaStream_t)0);
            }
            if ((profile_mmq || probe_record) && mmq_ev[3]) (void)cudaEventRecord(mmq_ev[3], (cudaStream_t)0);
            if (getenv("DS4_CUDA_MOE_STICKY_TRACE")) {
                const cudaError_t s3 = cudaGetLastError();
                if (s3 != cudaSuccess) {
                    fprintf(stderr, "ds4: sticky after down layer=%u: %s\n",
                            layer_index, cudaGetErrorString(s3));
                    fflush(stderr);
                }
            }
            if (getenv("DS4_CUDA_MOE_HASH_STAGES")) {
                /* Stage probe: hash the first slot's down row after the down
                 * kernel (host read = legacy barrier). */
                uint64_t hd = 1469598103934665603ull;
                float dbuf[512];
                if (cudaMemcpy(dbuf, down->ptr, sizeof(dbuf),
                               cudaMemcpyDeviceToHost) == cudaSuccess) {
                    for (int di = 0; di < 512; di++) {
                        uint32_t w;
                        memcpy(&w, &dbuf[di], 4);
                        hd ^= (uint64_t)w;
                        hd *= 1099511628211ull;
                    }
                }
                fprintf(stderr,
                        "ds4: MoE hash_down layer=%u hash=%016llx\n",
                        layer_index, (unsigned long long)hd);
                fflush(stderr);
            }
            if (rc == 0) {
                const uint64_t n = (uint64_t)n_tokens * out_dim;
                moe_mmq_sum_kernel<<<(uint32_t)((n + 255) / 256), 256>>>(
                        (float *)out->ptr, (const float *)down->ptr,
                        NULL, out_dim, n_expert, n_tokens,
                        /*guard_nonfinite=*/1);
                if (cuda_ok(cudaGetLastError(), "mmq moe sum launch")) {
                    if (getenv("DS4_CUDA_MOE_STICKY_TRACE")) {
                        const cudaError_t s4 = cudaGetLastError();
                        if (s4 != cudaSuccess) {
                            fprintf(stderr, "ds4: sticky after sum layer=%u: %s\n",
                                    layer_index, cudaGetErrorString(s4));
                            fflush(stderr);
                        }
                    }
                    if (g_stream_selected_compute_done_event) {
                        (void)cudaEventRecord(g_stream_selected_compute_done_event,
                                              (cudaStream_t)0);
                        if (getenv("DS4_CUDA_MOE_STICKY_TRACE")) {
                            const cudaError_t re = cudaGetLastError();
                            if (re != cudaSuccess) {
                                fprintf(stderr,
                                        "ds4: sticky after compute_done record layer=%u: %s\n",
                                        layer_index, cudaGetErrorString(re));
                                fflush(stderr);
                            }
                        }
                    }
                    if (getenv("DS4_CUDA_MOE_HASH_OUT")) {
                        /* Divergence probe: hash the routed output rows after
                         * the sum (host read = full legacy-stream barrier). */
                        const uint64_t hn = (uint64_t)n_tokens * out_dim;
                        float *hb = (float *)malloc((size_t)hn * sizeof(float));
                        if (hb) {
                            uint64_t h = 1469598103934665603ull;
                            if (cudaMemcpy(hb, out->ptr, (size_t)hn * sizeof(float),
                                           cudaMemcpyDeviceToHost) == cudaSuccess) {
                                for (uint64_t i = 0; i < hn; i++) {
                                    uint32_t w;
                                    memcpy(&w, &hb[i], 4);
                                    h ^= (uint64_t)w;
                                    h *= 1099511628211ull;
                                }
                            }
                            fprintf(stderr,
                                    "ds4: MoE hash_out layer=%u tokens=%u hash=%016llx\n",
                                    layer_index, n_tokens,
                                    (unsigned long long)h);
                            fflush(stderr);
                            free(hb);
                        }
                    }
                    if (getenv("DS4_CUDA_MOE_HOST_SYNC")) {
                        /* A/B probe: isolate whether the host-side timing
                         * (serializing the host behind each MoE call) alone
                         * flips the byte output. */
                        (void)cudaDeviceSynchronize();
                    }
                    if (profile_mmq && mmq_ev[4]) {
                        (void)cudaEventRecord(mmq_ev[4], (cudaStream_t)0);
                        (void)cudaEventSynchronize(mmq_ev[4]);
                        float m_pair = 0.0f, m_swi = 0.0f, m_down = 0.0f, m_sum = 0.0f, m_gpu = 0.0f;
                        (void)cudaEventElapsedTime(&m_pair, mmq_ev[0], mmq_ev[1]);
                        (void)cudaEventElapsedTime(&m_swi, mmq_ev[1], mmq_ev[2]);
                        (void)cudaEventElapsedTime(&m_down, mmq_ev[2], mmq_ev[3]);
                        (void)cudaEventElapsedTime(&m_sum, mmq_ev[3], mmq_ev[4]);
                        (void)cudaEventElapsedTime(&m_gpu, mmq_ev[0], mmq_ev[4]);
                        const double m_wall = (double)(GetTickCount64() - mmq_wall0);
                        fprintf(stderr,
                                "ds4: CUDA MoE mmq eager tokens=%u pair=%.3f swiglu=%.3f down=%.3f sum=%.3f gpu=%.3f wall=%.3f host=%.3f ms layer=%u\n",
                                n_tokens, m_pair, m_swi, m_down, m_sum, m_gpu,
                                m_wall, m_wall - (double)m_gpu, layer_index);
                        fflush(stderr);
                    }
                    for (uint32_t i = 0; i < 5u; i++) {
                        if (!probe_record) (void)cudaEventDestroy(mmq_ev[i]);
                    }
                    return 1;
                }
                rc = -1;
            }
            fprintf(stderr, "ds4: mmq routed-MoE tier rc=%d (layer=%u n_tokens=%u); falling back\n",
                    rc, layer_index, n_tokens);
        }
    }
    /* Q4_K routed-MoE dispatch:
     *   n_tokens == 1 and n_expert == 6:
     *                  use_direct_down_sum + moe_gate_up_mid_decode_q4K_qwarp32
     *                  + moe_down_q4K_sum6_qwarp32.
     *   n_tokens == 1 and n_expert == 3:
     *                  use the same direct path with moe_down_q4K_sum3_qwarp32.
     *                  Decode TP relies on this for splitting the six selected
     *                  experts into two groups.
     *   n_tokens == 1 and other n_expert:
     *                  use the same per-pair gate/up kernel plus the generic
     *                  q4K down + sum path.
     *   n_tokens >  1: default sorted-pairs expert-tile path groups token/expert
     *                  pairs by expert and uses Q4_K tile8 gate/up + down kernels
     *                  (`DS4_CUDA_MOE_NO_Q4_SORTED=1` restores the older
     *                  token-indexed decode-style prefill kernels). */
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_bytes > model_size - gate_offset ||
        gate_bytes > model_size - up_offset ||
        down_bytes > model_size - down_offset) {
        if (getenv("DS4_CUDA_MOE_BRANCH_LOG")) {
            fprintf(stderr,
                    "ds4: CUDA MoE exit=range gate_bytes=%llu down_bytes=%llu model_size=%llu gate_off=%llu up_off=%llu down_off=%llu layer=%u\n",
                    (unsigned long long)gate_bytes,
                    (unsigned long long)down_bytes,
                    (unsigned long long)model_size,
                    (unsigned long long)gate_offset,
                    (unsigned long long)up_offset,
                    (unsigned long long)down_offset, layer_index);
            fflush(stderr);
        }
        return 0;
    }
    const uint64_t required_slot_count = (uint64_t)n_tokens * n_expert;
    const int logical_tier = ds4_tensor_device_idx(out);
    const int use_stream_selected_cache =
        allow_streaming &&
        g_ssd_streaming_mode &&
        g_stream_selected_cache.valid &&
        g_stream_selected_cache.logical_tier == logical_tier &&
        g_stream_selected_cache.model_map == model_map &&
        g_stream_selected_cache.n_total_expert == n_total_expert &&
        g_stream_selected_cache.slot_count >= required_slot_count &&
        g_stream_selected_cache.gate_expert_bytes == gate_expert_bytes &&
        g_stream_selected_cache.down_expert_bytes == down_expert_bytes &&
        g_stream_selected_cache.gate_ptr &&
        g_stream_selected_cache.up_ptr &&
        g_stream_selected_cache.down_ptr &&
        g_stream_selected_cache.slot_selected_tensor.ptr &&
        g_stream_selected_cache.slot_selected_tensor.bytes >=
            required_slot_count * sizeof(int32_t);
    if (g_ssd_streaming_mode && allow_streaming &&
        !use_stream_selected_cache) {
        fprintf(stderr,
                "ds4: CUDA streaming selected experts are unavailable for layer %u\n",
                layer_index);
        return 0;
    }
    if (use_stream_selected_cache) {
        selected = &g_stream_selected_cache.slot_selected_tensor;
        /* Split-phase pipeline: the Q4K tier reads gate/up/down rows; wait
         * for the upload stream before the kernels launch. */
        if (g_stream_selected_upload_done_event) {
            (void)cudaStreamWaitEvent((cudaStream_t)0,
                                      g_stream_selected_upload_done_event, 0);
        }
    }
    const char *gate_w = use_stream_selected_cache ?
        g_stream_selected_cache.gate_ptr :
        cuda_resolve_weight_ptr(model_map, gate_offset, gate_bytes,
                                logical_tier, "moe_gate");
    const char *up_w = use_stream_selected_cache ?
        g_stream_selected_cache.up_ptr :
        cuda_resolve_weight_ptr(model_map, up_offset, gate_bytes,
                                logical_tier, "moe_up");
    const char *down_w = use_stream_selected_cache ?
        g_stream_selected_cache.down_ptr :
        cuda_resolve_weight_ptr(model_map, down_offset, down_bytes,
                                logical_tier, "moe_down");
    if (!gate_w || !up_w || !down_w) {
        if (getenv("DS4_CUDA_MOE_BRANCH_LOG")) {
            fprintf(stderr,
                    "ds4: CUDA MoE exit=nullw cache=%d g=%p u=%p d=%p layer=%u\n",
                    use_stream_selected_cache, (const void *)gate_w,
                    (const void *)up_w, (const void *)down_w, layer_index);
            fflush(stderr);
        }
        return 0;
    }

    int ok = 1;
    const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint32_t midq_blocks = expert_mid_dim / CUDA_QK_K;
    const uint64_t xq_count = (uint64_t)n_tokens * xq_blocks;
    const uint64_t midq_count = (uint64_t)n_tokens * n_expert * midq_blocks;
    const uint64_t xq_bytes = xq_count * sizeof(cuda_block_q8_K);
    const uint64_t midq_bytes = midq_count * sizeof(cuda_block_q8_K);
    if (down->bytes >= xq_bytes && gate->bytes >= midq_bytes) {
        if (getenv("DS4_CUDA_MOE_BRANCH_LOG")) {
            fprintf(stderr,
                    "ds4: CUDA MoE branch=tile tokens=%u down_bytes=%llu xq_bytes=%llu gate_bytes=%llu midq_bytes=%llu streaming=%d layer=%u\n",
                    n_tokens, (unsigned long long)down->bytes,
                    (unsigned long long)xq_bytes, (unsigned long long)gate->bytes,
                    (unsigned long long)midq_bytes, g_ssd_streaming_mode ? 1 : 0,
                    layer_index);
            fflush(stderr);
        }
        cuda_block_q8_K *xq = (cuda_block_q8_K *)down->ptr;
        cuda_block_q8_K *midq = (cuda_block_q8_K *)gate->ptr;
        const uint32_t profile_moe = getenv("DS4_CUDA_MOE_PROFILE") != NULL;
        cudaEvent_t prof_ev[7] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL};
        if (profile_moe) {
            for (uint32_t i = 0; i < 7u; i++) {
                if (cudaEventCreate(&prof_ev[i]) != cudaSuccess) {
                    for (uint32_t j = 0; j < i; j++) (void)cudaEventDestroy(prof_ev[j]);
                    memset(prof_ev, 0, sizeof(prof_ev));
                    break;
                }
            }
            if (prof_ev[0]) (void)cudaEventRecord(prof_ev[0], 0);
        }
        const uint32_t pair_count = n_tokens * n_expert;
        const uint32_t use_q4_sorted_pairs =
            q4k_path && n_tokens > 1u &&
            (owned_filtered ||
             (getenv("DS4_CUDA_MOE_NO_Q4_SORTED") == NULL &&
              getenv("DS4_CUDA_MOE_NO_EXPERT_TILES") == NULL &&
              getenv("DS4_CUDA_MOE_TILE4") == NULL));
        const uint32_t use_sorted_pairs =
            n_tokens > 1u &&
            (owned_filtered || !q4k_path || use_q4_sorted_pairs);
        const uint32_t use_expert_tiles =
            use_sorted_pairs &&
            (owned_filtered || getenv("DS4_CUDA_MOE_NO_EXPERT_TILES") == NULL);
        const uint32_t q4_owned_batch =
            owned_filtered && q4k_path && n_tokens >= 4u && n_tokens <= 16u;
        /* Small batches (DSpark stage chain / verify, n<=8) leave most of an
         * 8-slot expert tile empty (1-2 rows per expert): tile4 halves the
         * wasted dot-slots and measures ~2x faster there. Q4 TP batches use
         * tile8 because its exact tensor-core row-span kernels recover more
         * than the empty slots cost. Large prefill also keeps tile8. */
        const uint32_t expert_tile_m =
            getenv("DS4_CUDA_MOE_TILE4") ? 4u :
            (getenv("DS4_CUDA_MOE_TILE8") ? 8u :
             (q4_owned_batch || n_tokens > 8u ? 8u : 4u));
        const uint32_t write_gate_up = getenv("DS4_CUDA_MOE_WRITE_GATE_UP") != NULL;
        const uint32_t use_p2_sorted =
            use_sorted_pairs && !owned_filtered &&
            getenv("DS4_CUDA_MOE_NO_P2") == NULL;
        const uint32_t use_atomic_down = !q4k_path && use_expert_tiles &&
            (getenv("DS4_CUDA_MOE_ATOMIC_DOWN") != NULL ||
             (n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_ATOMIC_DOWN") == NULL));
        const uint32_t use_owned_sparse_buffers = owned_filtered &&
            getenv("DS4_CUDA_MOE_NO_OWNED_SPARSE_BUFFERS") == NULL;
        const uint32_t use_gate_row2048 = use_expert_tiles && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW128") != NULL ||
             ((q4_owned_batch || n_tokens >= 128u) &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW128") == NULL));
        const uint32_t use_q4_mma_tiles16 = q4k_path && use_expert_tiles &&
            expert_tile_m == 8u && cuda_q4_mma_ok() &&
            getenv("DS4_CUDA_MOE_NO_Q4_MMA_TILE16") == NULL;
        const uint32_t use_down_tile16 = !q4k_path && use_atomic_down && expert_tile_m == 8u &&
            n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_DOWN_TILE16") == NULL;
        const uint32_t use_small_sorted_prep =
            owned_filtered && q4k_path && n_tokens <= 16u && pair_count <= 96u &&
            n_total_expert <= 128u && use_sorted_pairs && use_expert_tiles &&
            getenv("DS4_CUDA_MOE_NO_SMALL_SORTED_PREP") == NULL;
        const uint32_t force_q4_down_rowspan =
            getenv("DS4_CUDA_MOE_DOWN_ROW512") != NULL ||
            getenv("DS4_CUDA_MOE_DOWN_ROW1024") != NULL ||
            getenv("DS4_CUDA_MOE_DOWN_ROW2048") != NULL;
        const uint32_t use_q4_down_rowspan =
            q4k_path && use_expert_tiles && expert_tile_m == 8u &&
            (q4_owned_batch || n_tokens >= 128u || force_q4_down_rowspan) &&
            getenv("DS4_CUDA_MOE_NO_Q4_DOWN_ROWSPAN") == NULL;
        const uint32_t use_decode_lut_gate =
            n_tokens == 1u && xq_blocks <= 16u &&
            getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") == NULL;
        const uint32_t gate_row_span =
            getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ? 2048u :
            getenv("DS4_CUDA_MOE_GATE_ROW1024") != NULL ? 1024u : 512u;
        const uint32_t down_row_span =
            getenv("DS4_CUDA_MOE_DOWN_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_DOWN_ROW2048") != NULL ? 2048u :
            getenv("DS4_CUDA_MOE_DOWN_ROW1024") != NULL ? 1024u : 512u;
        const uint32_t use_down_row2048 = !q4k_path && use_atomic_down && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_DOWN_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW128") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW64") != NULL ||
             (use_down_tile16 &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW128") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW64") == NULL));
        const uint32_t use_direct_down_sum =
            n_tokens == 1u && (n_expert == 6u || n_expert == 3u) &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
        const uint32_t use_direct_midq =
            q4k_path && use_direct_down_sum && !write_gate_up &&
            getenv("DS4_CUDA_MOE_DIRECT_MIDQ") != NULL &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_MIDQ") == NULL;
        const uint32_t use_q4_gate_h16r8 =
            q4k_path && !use_direct_midq &&
            getenv("DS4_CUDA_MOE_Q4_GATE_H16R8") != NULL &&
            getenv("DS4_CUDA_MOE_NO_Q4_GATE_H16R8") == NULL;
        const uint32_t use_q4_gate_h16 =
            q4k_path && !use_direct_midq && !use_q4_gate_h16r8 &&
            getenv("DS4_CUDA_MOE_Q4_GATE_H16") != NULL &&
            getenv("DS4_CUDA_MOE_NO_Q4_GATE_H16") == NULL;
        const uint32_t use_q4_gate_w32r16 =
            q4k_path && !use_direct_midq && !use_q4_gate_h16r8 && !use_q4_gate_h16 &&
            getenv("DS4_CUDA_MOE_Q4_GATE_W32R16") != NULL &&
            getenv("DS4_CUDA_MOE_NO_Q4_GATE_W32R16") == NULL;
        const uint32_t use_q4_gate_w32 =
            q4k_path && !use_direct_midq && !use_q4_gate_h16r8 && !use_q4_gate_h16 &&
            !use_q4_gate_w32r16 &&
            getenv("DS4_CUDA_MOE_NO_Q4_GATE_W32") == NULL;
        const uint32_t use_q4_gate_w32_noaux =
            use_q4_gate_w32 && !write_gate_up &&
            getenv("DS4_CUDA_MOE_NO_Q4_GATE_W32_NOAUX") == NULL;
        const uint32_t use_q4_down_slot3 =
            q4k_path && use_direct_down_sum && n_expert == 3u &&
            getenv("DS4_CUDA_MOE_Q4_DOWN_SLOT3") != NULL &&
            getenv("DS4_CUDA_MOE_NO_Q4_DOWN_SLOT3") == NULL;
        const uint32_t use_q4_midq_sidecar =
            q4k_path && use_direct_down_sum && use_q4_gate_w32_noaux &&
            !use_direct_midq && !write_gate_up &&
            (expert_mid_dim % CUDA_QK_K) == 0u &&
            getenv("DS4_CUDA_MOE_MIDQ_SIDECAR") != NULL &&
            getenv("DS4_CUDA_MOE_NO_MIDQ_SIDECAR") == NULL;
        float *midq_sidecar = use_q4_midq_sidecar ? (float *)up->ptr : NULL;
        if (g_cuda_moe_decode_graph &&
            !owned_filtered &&
            !profile_moe &&
            q4k_path &&
            n_tokens == 1u &&
            use_direct_down_sum &&
            use_q4_gate_w32 &&
            !use_q4_gate_w32r16 &&
            !use_q4_down_slot3 &&
            !use_direct_midq &&
            !use_q4_midq_sidecar &&
            (n_expert == 3u || n_expert == 6u)) {
            int grc = routed_moe_decode_q4_graph_launch(
                    logical_tier,
                    (float *)out->ptr,
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    down_w,
                    xq,
                    midq,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    down_expert_bytes,
                    down_row_bytes,
                    expert_in_dim,
                    expert_mid_dim,
                    out_dim,
                    n_expert,
                    write_gate_up,
                    clamp,
                    (const float *)x->ptr);
            if (grc == 1) return 1;
            if (grc < 0) return 0;
        }
        uint32_t *sorted_pairs = NULL;
        uint32_t *sorted_offsets = NULL;
        uint32_t *sorted_counts = NULL;
        uint32_t *tile_total = NULL;
        uint32_t *tile_experts = NULL;
        uint32_t *tile_starts = NULL;
        uint32_t *tile16_total = NULL;
        uint32_t *tile16_experts = NULL;
        uint32_t *tile16_starts = NULL;
        uint32_t tile_capacity = 0;
        uint32_t tile16_capacity = 0;
        dim3 xq_grid(xq_blocks, n_tokens, 1);
        q8_K_quantize_kernel<<<xq_grid, 256, 0, cuda_decode_stream()>>>(xq, (const float *)x->ptr, expert_in_dim, n_tokens);
        ok = cuda_ok(cudaGetLastError(), "routed_moe x quantize launch");
        if (prof_ev[1]) (void)cudaEventRecord(prof_ev[1], 0);
        if (ok && use_sorted_pairs) {
            const uint64_t counts_bytes = (uint64_t)n_total_expert * sizeof(uint32_t);
            const uint64_t offsets_bytes = ((uint64_t)n_total_expert + 1ull) * sizeof(uint32_t);
            const uint64_t cursors_bytes = (uint64_t)n_total_expert * sizeof(uint32_t);
            const uint64_t sorted_bytes = (uint64_t)pair_count * sizeof(uint32_t);
            tile_capacity = (pair_count + expert_tile_m - 1u) / expert_tile_m + n_total_expert;
            tile16_capacity = (use_down_tile16 || use_q4_mma_tiles16) ? ((pair_count + 15u) / 16u + n_total_expert) : 0u;
            const uint64_t tile_offsets_bytes = ((uint64_t)n_total_expert + 1ull) * sizeof(uint32_t);
            const uint64_t tile_total_bytes = sizeof(uint32_t);
            const uint64_t tile_experts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile_starts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile16_offsets_bytes = (use_down_tile16 || use_q4_mma_tiles16) ? (((uint64_t)n_total_expert + 1ull) * sizeof(uint32_t)) : 0u;
            const uint64_t tile16_total_bytes = (use_down_tile16 || use_q4_mma_tiles16) ? sizeof(uint32_t) : 0u;
            const uint64_t tile16_experts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile16_starts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile_offsets_off = counts_bytes + offsets_bytes + cursors_bytes + sorted_bytes;
            const uint64_t tile_total_off = tile_offsets_off + tile_offsets_bytes;
            const uint64_t tile_experts_off = tile_total_off + tile_total_bytes;
            const uint64_t tile_starts_off = tile_experts_off + tile_experts_bytes;
            const uint64_t tile16_offsets_off = tile_starts_off + tile_starts_bytes;
            const uint64_t tile16_total_off = tile16_offsets_off + tile16_offsets_bytes;
            const uint64_t tile16_experts_off = tile16_total_off + tile16_total_bytes;
            const uint64_t tile16_starts_off = tile16_experts_off + tile16_experts_bytes;
            const uint64_t scratch_bytes = tile16_starts_off + tile16_starts_bytes;
            uint8_t *scratch = (uint8_t *)cuda_tmp_alloc_on(logical_tier, scratch_bytes,
                                                             "routed_moe sorted pairs");
            if (!scratch) {
                ok = 0;
            } else {
                uint32_t *counts = (uint32_t *)scratch;
                uint32_t *offsets = (uint32_t *)(scratch + counts_bytes);
                uint32_t *cursors = (uint32_t *)(scratch + counts_bytes + offsets_bytes);
                sorted_pairs = (uint32_t *)(scratch + counts_bytes + offsets_bytes + cursors_bytes);
                sorted_offsets = offsets;
                sorted_counts = counts;
                uint32_t *tile_offsets = (uint32_t *)(scratch + tile_offsets_off);
                tile_total = (uint32_t *)(scratch + tile_total_off);
                tile_experts = (uint32_t *)(scratch + tile_experts_off);
                tile_starts = (uint32_t *)(scratch + tile_starts_off);
                uint32_t *tile16_offsets = (use_down_tile16 || use_q4_mma_tiles16) ? (uint32_t *)(scratch + tile16_offsets_off) : NULL;
                tile16_total = (use_down_tile16 || use_q4_mma_tiles16) ? (uint32_t *)(scratch + tile16_total_off) : NULL;
                tile16_experts = (use_down_tile16 || use_q4_mma_tiles16) ? (uint32_t *)(scratch + tile16_experts_off) : NULL;
                tile16_starts = (use_down_tile16 || use_q4_mma_tiles16) ? (uint32_t *)(scratch + tile16_starts_off) : NULL;
                if (use_small_sorted_prep) {
                    moe_prepare_sorted_tiles_small_kernel<<<1, 128, 0, cuda_decode_stream()>>>(
                        counts, offsets, cursors, sorted_pairs,
                        tile_offsets, tile_total, tile_experts, tile_starts,
                        tile16_offsets, tile16_total, tile16_experts, tile16_starts,
                        (const int32_t *)selected->ptr, pair_count, n_total_expert,
                        expert_tile_m, use_down_tile16 || use_q4_mma_tiles16);
                    ok = cuda_ok(cudaGetLastError(),
                                 "routed_moe small sorted setup launch");
                } else {
                    ok = ds4_gpu_memset_zero(counts, counts_bytes, cuda_decode_stream());
                    if (!ok) {
                        fprintf(stderr, "ds4: routed_moe sorted counts clear failed\n");
                    }
                }
                if (ok && !use_small_sorted_prep) {
                    moe_count_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256, 0, cuda_decode_stream()>>>(
                        counts,
                        (const int32_t *)selected->ptr,
                        pair_count,
                        n_total_expert);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted count launch");
                }
                if (ok && !use_small_sorted_prep) {
                    moe_prefix_sorted_pairs_kernel<<<1, 1, 0, cuda_decode_stream()>>>(offsets, cursors, counts, n_total_expert);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted prefix launch");
                }
                if (ok && !use_small_sorted_prep) {
                    moe_scatter_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256, 0, cuda_decode_stream()>>>(
                        sorted_pairs,
                        cursors,
                        (const int32_t *)selected->ptr,
                        pair_count,
                        n_total_expert);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted scatter launch");
                }
                if (ok && use_expert_tiles && !use_small_sorted_prep) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1, 0, cuda_decode_stream()>>>(tile_offsets, tile_total, counts, expert_tile_m, n_total_expert);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile offsets launch");
                }
                if (ok && use_expert_tiles && !use_small_sorted_prep) {
                    moe_build_expert_tiles_kernel<<<(n_total_expert + 255u) / 256u, 256, 0, cuda_decode_stream()>>>(
                        tile_experts, tile_starts, tile_offsets, counts, expert_tile_m, n_total_expert);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tiles launch");
                }
                if (ok && use_expert_tiles && !use_small_sorted_prep &&
                    (use_down_tile16 || use_q4_mma_tiles16)) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1, 0, cuda_decode_stream()>>>(tile16_offsets, tile16_total, counts, 16u, n_total_expert);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 offsets launch");
                }
                if (ok && use_expert_tiles && !use_small_sorted_prep &&
                    (use_down_tile16 || use_q4_mma_tiles16)) {
                    moe_build_expert_tiles_kernel<<<(n_total_expert + 255u) / 256u, 256, 0, cuda_decode_stream()>>>(
                        tile16_experts, tile16_starts, tile16_offsets, counts, 16u, n_total_expert);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 launch");
                }
            }
        }
        if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
        if (ok && owned_filtered && use_sorted_pairs &&
            !use_owned_sparse_buffers) {
            const uint64_t mid_bytes =
                (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float);
            ok = ds4_gpu_memset_zero(mid->ptr, (size_t)mid_bytes,
                                     cuda_decode_stream());
            if (!ok) {
                fprintf(stderr, "ds4: owned routed_moe mid clear failed\n");
            }
        }
        if (ok) {
            dim3 mgrid((expert_mid_dim + 31u) / 32u, n_tokens * n_expert, 1);
            if (ok && sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts && tile_total && tile_experts && tile_starts) {
                if (q4k_path) {
                    const int use_q4_mma = cuda_q4_mma_ok() &&
                        ((((uintptr_t)gate_w | (uintptr_t)up_w |
                           gate_row_bytes | gate_expert_bytes) & 15u) == 0u) &&
                        xq_blocks <= 16u && (expert_mid_dim & 7u) == 0u;
                    const int use_q4_mma_t16 = use_q4_mma && use_q4_mma_tiles16 &&
                        tile16_total && tile16_experts && tile16_starts &&
                        xq_blocks == 16u && cuda_q4_mma_tile16_shmem_ok(0);
                    if (use_q4_mma_t16 && use_gate_row2048) {
                        const unsigned t16cap = (unsigned)((pair_count + 15u) / 16u + n_total_expert);
                        const size_t t16sh = 16u * 16u * sizeof(cuda_block_q8_K);
                        if (gate_row_span == 512u) {
                            dim3 tgrid((expert_mid_dim + 511u) / 512u, t16cap, 1);
                            moe_gate_up_mid_q4K_tile16_mma_kernel<512><<<tgrid, 256, t16sh, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile16_total, tile16_experts, tile16_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        } else if (gate_row_span == 1024u) {
                            dim3 tgrid((expert_mid_dim + 1023u) / 1024u, t16cap, 1);
                            moe_gate_up_mid_q4K_tile16_mma_kernel<1024><<<tgrid, 256, t16sh, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile16_total, tile16_experts, tile16_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        } else {
                            dim3 tgrid((expert_mid_dim + 2047u) / 2048u, t16cap, 1);
                            moe_gate_up_mid_q4K_tile16_mma_kernel<2048><<<tgrid, 256, t16sh, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile16_total, tile16_experts, tile16_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        }
                    } else if (use_q4_mma && use_gate_row2048) {
                        if (gate_row_span == 512u) {
                            dim3 tgrid((expert_mid_dim + 511u) / 512u, tile_capacity, 1);
                            moe_gate_up_mid_q4K_tile8_mma_kernel<512><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        } else if (gate_row_span == 1024u) {
                            dim3 tgrid((expert_mid_dim + 1023u) / 1024u, tile_capacity, 1);
                            moe_gate_up_mid_q4K_tile8_mma_kernel<1024><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        } else {
                            dim3 tgrid((expert_mid_dim + 2047u) / 2048u, tile_capacity, 1);
                            moe_gate_up_mid_q4K_tile8_mma_kernel<2048><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        }
                    } else if (use_gate_row2048) {
                        if (gate_row_span == 512u) {
                            dim3 tgrid((expert_mid_dim + 511u) / 512u, tile_capacity, 1);
                            moe_gate_up_mid_q4K_expert_tile8_rowspan_kernel<512><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        } else if (gate_row_span == 1024u) {
                            dim3 tgrid((expert_mid_dim + 1023u) / 1024u, tile_capacity, 1);
                            moe_gate_up_mid_q4K_expert_tile8_rowspan_kernel<1024><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        } else {
                            dim3 tgrid((expert_mid_dim + 2047u) / 2048u, tile_capacity, 1);
                            moe_gate_up_mid_q4K_expert_tile8_rowspan_kernel<2048><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                                (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                                gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                                tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                                gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                                write_gate_up, clamp);
                        }
                    } else {
                        dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                        moe_gate_up_mid_q4K_expert_tile8_rowspan_kernel<32><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    }
                } else if (use_gate_row2048) {
                    if (gate_row_span == 512u) {
                        dim3 tgrid((expert_mid_dim + 511u) / 512u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<512><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else if (gate_row_span == 1024u) {
                        dim3 tgrid((expert_mid_dim + 1023u) / 1024u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<1024><<<tgrid, 256, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else {
                        dim3 tgrid((expert_mid_dim + 2047u) / 2048u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_row2048_kernel<<<tgrid, 256, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    }
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile8_row32_kernel<<<tgrid, 256, 0, cuda_decode_stream()>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                } else {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile4_row32_kernel<<<tgrid, 256, 0, cuda_decode_stream()>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                }
            } else if (ok && sorted_pairs && use_p2_sorted) {
                dim3 p2_mgrid((expert_mid_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_gate_up_mid_sorted_p2_qwarp32_kernel<<<p2_mgrid, 256, 0, cuda_decode_stream()>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
            } else if (ok && sorted_pairs) {
                moe_gate_up_mid_sorted_qwarp32_kernel<<<mgrid, 256, 0, cuda_decode_stream()>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    clamp);
            } else if (ok) {
                dim3 qgrid((expert_mid_dim + MOE_DECODE_ROWS_PER_BLOCK - 1u) / MOE_DECODE_ROWS_PER_BLOCK, n_tokens * n_expert, 1);
                if (q4k_path) {
                    /* Q4_K gate/up: the decode kernel is token-indexed via
                     * pair = blockIdx.y; tok = pair / n_expert, so the same
                     * launch covers both n_tokens == 1 (decode) and n_tokens > 1
                     * (prefill). q4k_path is steered here by use_sorted_pairs = 0
                     * cascading the IQ2 sorted/expert-tile branches off. */
                    if (use_direct_midq) {
                        dim3 mqgrid(midq_blocks, n_tokens * n_expert, 1);
                        moe_gate_up_midq_decode_q4K_qwarp32_kernel<<<mqgrid, 256, 0, cuda_decode_stream()>>>(
                            (float *)mid->ptr,
                            midq,
                            gate_w,
                            up_w,
                            xq,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate_expert_bytes,
                            gate_row_bytes,
                            xq_blocks,
                            expert_mid_dim,
                            n_expert,
                            clamp);
                    } else if (use_q4_gate_h16r8) {
                        dim3 h8grid((expert_mid_dim + 7u) / 8u, n_tokens * n_expert, 1);
                        moe_gate_up_mid_decode_q4K_hwarp16_row8_kernel<<<h8grid, 256, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr,
                            (float *)up->ptr,
                            (float *)mid->ptr,
                            gate_w,
                            up_w,
                            xq,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate_expert_bytes,
                            gate_row_bytes,
                            xq_blocks,
                            expert_mid_dim,
                            n_expert,
                            write_gate_up,
                            clamp);
                    } else if (use_q4_gate_w32r16) {
                        dim3 w16grid((expert_mid_dim + 15u) / 16u, n_tokens * n_expert, 1);
                        moe_gate_up_mid_decode_q4K_warp32_row16_kernel<<<w16grid, 512, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr,
                            (float *)up->ptr,
                            (float *)mid->ptr,
                            gate_w,
                            up_w,
                            xq,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate_expert_bytes,
                            gate_row_bytes,
                            xq_blocks,
                            expert_mid_dim,
                            n_expert,
                            write_gate_up,
                            clamp);
                    } else if (use_q4_gate_w32) {
                        dim3 wgrid((expert_mid_dim + 7u) / 8u, n_tokens * n_expert, 1);
                        if (use_q4_gate_w32_noaux) {
                            if (use_q4_midq_sidecar) {
                                moe_gate_up_mid_decode_q4K_warp32_noaux_sidecar_kernel<<<wgrid, 256, 0, cuda_decode_stream()>>>(
                                    (float *)mid->ptr,
                                    midq_sidecar,
                                    gate_w,
                                    up_w,
                                    xq,
                                    (const int32_t *)selected->ptr,
                                    (const float *)weights->ptr,
                                    gate_expert_bytes,
                                    gate_row_bytes,
                                    xq_blocks,
                                    expert_mid_dim,
                                    n_expert,
                                    clamp);
                            } else {
                                moe_gate_up_mid_decode_q4K_warp32_noaux_kernel<<<wgrid, 256, 0, cuda_decode_stream()>>>(
                                    (float *)mid->ptr,
                                    gate_w,
                                    up_w,
                                    xq,
                                    (const int32_t *)selected->ptr,
                                    (const float *)weights->ptr,
                                    gate_expert_bytes,
                                    gate_row_bytes,
                                    xq_blocks,
                                    expert_mid_dim,
                                    n_expert,
                                    clamp);
                            }
                        } else {
                            moe_gate_up_mid_decode_q4K_warp32_kernel<<<wgrid, 256, 0, cuda_decode_stream()>>>(
                                (float *)gate->ptr,
                                (float *)up->ptr,
                                (float *)mid->ptr,
                                gate_w,
                                up_w,
                                xq,
                                (const int32_t *)selected->ptr,
                                (const float *)weights->ptr,
                                gate_expert_bytes,
                                gate_row_bytes,
                                xq_blocks,
                                expert_mid_dim,
                                n_expert,
                                write_gate_up,
                                clamp);
                        }
                    } else if (use_q4_gate_h16) {
                        dim3 hgrid((expert_mid_dim + 15u) / 16u, n_tokens * n_expert, 1);
                        moe_gate_up_mid_decode_q4K_hwarp16_kernel<<<hgrid, 256, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr,
                            (float *)up->ptr,
                            (float *)mid->ptr,
                            gate_w,
                            up_w,
                            xq,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate_expert_bytes,
                            gate_row_bytes,
                            xq_blocks,
                            expert_mid_dim,
                            n_expert,
                            write_gate_up,
                            clamp);
                    } else {
                        moe_gate_up_mid_decode_q4K_qwarp32_kernel<<<qgrid, 256, 0, cuda_decode_stream()>>>(
                            (float *)gate->ptr,
                            (float *)up->ptr,
                            (float *)mid->ptr,
                            gate_w,
                            up_w,
                            xq,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate_expert_bytes,
                            gate_row_bytes,
                            xq_blocks,
                            expert_mid_dim,
                            n_expert,
                            write_gate_up,
                            clamp);
                    }
                } else if (use_decode_lut_gate) {
                    moe_gate_up_mid_decode_lut_qwarp32_kernel<<<qgrid, 256, 0, cuda_decode_stream()>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp);
                } else {
                    moe_gate_up_mid_qwarp32_kernel<<<qgrid, 256, 0, cuda_decode_stream()>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        clamp);
