            NULL,
            NULL,
            home_slots,
            peer_packed,
            selected,
            expert_split,
            residual_hc,
            split,
            n_embd,
            n_hc,
            "shared_down_hc_expand_owned");
}

extern "C" int ds4_gpu_matmul_q8_0_hc_expand_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, block_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        x,
                                                        NULL,
                                                        NULL,
                                                        NULL, NULL, NULL, 0,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "q8_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(block_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim, x, 1) &&
           ds4_gpu_hc_expand_split_tensor(out_hc, block_out, residual_hc,
                                            split, n_embd, n_hc);
}

/* --gpu-vram auto probe. Defined here (in the .cu unit) so the
 * C-side parser (ds4_gpu_args.c) does not need to include
 * <cuda_runtime.h>. Returns 0 on success, nonzero on error
 * (errbuf populated). See ds4_gpu_args.h.
 *
 * Side-effect-light: changes cudaSetDevice during probing; callers
 * that care about the active device should reset it themselves
 * before continuing. (The mgpu init path resets it anyway.) */
extern "C" int ds4_gpu_args_probe_auto_cuda(const int      *device_filter,
                                              int             filter_len,
                                              ds4_gpu_config *out,
                                              size_t          safety_margin_bytes,
                                              char           *errbuf,
                                              size_t          errbuflen) {
    if (!out) {
        if (errbuf && errbuflen) snprintf(errbuf, errbuflen, "internal: NULL out");
        return 1;
    }
    int visible = 0;
    cudaError_t rc = cudaGetDeviceCount(&visible);
    if (rc != cudaSuccess || visible <= 0) {
        if (errbuf && errbuflen) {
            snprintf(errbuf, errbuflen,
                     "cudaGetDeviceCount failed: %s",
                     rc == cudaSuccess ? "no devices" : cudaGetErrorString(rc));
        }
        return 1;
    }
    /* Build the device list: either the explicit filter or 0..visible-1. */
    int devs[DS4_MAX_GPUS];
    int n_dev = 0;
    if (device_filter && filter_len > 0) {
        if (filter_len > DS4_MAX_GPUS) {
            if (errbuf && errbuflen) {
                snprintf(errbuf, errbuflen,
                         "--gpu-devices filter has %d entries (max %d)",
                         filter_len, DS4_MAX_GPUS);
            }
            return 1;
        }
        for (int i = 0; i < filter_len; i++) {
            int d = device_filter[i];
            if (d < 0 || d >= visible) {
                if (errbuf && errbuflen) {
                    snprintf(errbuf, errbuflen,
                             "--gpu-devices: device %d not in 0..%d",
                             d, visible - 1);
                }
                return 1;
            }
            devs[n_dev++] = d;
        }
    } else {
        int cap = visible < DS4_MAX_GPUS ? visible : DS4_MAX_GPUS;
        for (int i = 0; i < cap; i++) devs[n_dev++] = i;
    }
    out->n_gpus = n_dev;
    out->safety_margin_bytes = safety_margin_bytes;
    for (int i = 0; i < n_dev; i++) {
        int d = devs[i];
        rc = cudaSetDevice(d);
        if (rc != cudaSuccess) {
            if (errbuf && errbuflen) {
                snprintf(errbuf, errbuflen,
                         "cudaSetDevice(%d) failed: %s",
                         d, cudaGetErrorString(rc));
            }
            return 1;
        }
        size_t free_b = 0, total_b = 0;
        rc = cudaMemGetInfo(&free_b, &total_b);
        if (rc != cudaSuccess) {
            if (errbuf && errbuflen) {
                snprintf(errbuf, errbuflen,
                         "cudaMemGetInfo on device %d failed: %s",
                         d, cudaGetErrorString(rc));
            }
            return 1;
        }
        /* Auto-mode reserve. Auto-probe is the only place we override
         * the user's stated budget, so this is where the conservative-
         * on-the-user's-behalf reserve belongs. The
         * engine path (engine_classify_multi_tier) still subtracts the
         * user-supplied safety_margin_bytes + the cuBLAS workspace from
         * whatever budget we hand back; that math is unchanged and
         * applies on top of the reserve we trim here.
         *
         * Reserve = max(2 GiB, 5 % of free). Why these numbers:
         *   - 2 GiB floor covers runtime scratch / Q8 dequant caches /
         *     MTP optional state on small GPUs (8-12 GB cards) where
         *     5 % is < 1 GiB and not enough headroom.
         *   - 5 % of free scales the reserve up on larger cards where
         *     workspace + KV growth needs proportionally more room.
         * Explicit --gpu-vram 47,37 budgets do not go through this
         * probe and are unaffected. */
        const size_t reserve_floor = (size_t)2ull * 1024ull * 1024ull * 1024ull;
        const size_t reserve_pct = free_b / 20u;
        const size_t reserve = reserve_floor > reserve_pct ? reserve_floor : reserve_pct;
        const size_t budget = free_b > reserve ? (free_b - reserve) : 0;
        (void)safety_margin_bytes;
        out->device_indices[i] = d;
        out->vram_bytes[i] = budget;
    }
    return 0;
}

typedef struct ds4_gpu_stream_expert_table {
    const void *model_map;
    uint64_t    model_size;
    uint32_t    layer;
    uint32_t    n_total_expert;
    uint64_t    gate_offset;
    uint64_t    up_offset;
    uint64_t    down_offset;
    uint64_t    gate_expert_bytes;
    uint64_t    down_expert_bytes;
} ds4_gpu_stream_expert_table;

static int cuda_stream_selected_ensure_bytes(
        char **ptr, uint64_t *capacity, uint64_t bytes, const char *label) {
    if (*ptr && *capacity >= bytes) return 1;
    if (*ptr) {
        (void)cudaFree(*ptr);
        *ptr = NULL;
        *capacity = 0;
    }
    if (bytes == 0 || bytes > (uint64_t)SIZE_MAX) return 0;
    cudaError_t err = cudaMalloc((void **)ptr, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA streaming %s allocation failed for %.2f MiB: %s\n",
                label, (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    *capacity = bytes;
    return 1;
}

/* Pinned-slot allocation: driver pinned pool (cudaHostAllocMapped), returns
 * host pointer via *host_out and device pointer via *ptr_out. Falls back to
 * plain VRAM allocation when the WDDM locked-page pool is exhausted. */
static int cuda_stream_selected_alloc_pinned(
        char **ptr_out, char **host_out, uint64_t bytes, const char *label) {
    *ptr_out = NULL;
    *host_out = NULL;
    if (bytes == 0 || bytes > (uint64_t)SIZE_MAX) return 0;
    char *host = NULL;
    cudaError_t err = cudaHostAlloc((void **)&host, (size_t)bytes,
                                    cudaHostAllocMapped);
    if (err == cudaSuccess) {
        void *dev = NULL;
        err = cudaHostGetDevicePointer(&dev, host, 0);
        if (err == cudaSuccess && dev) {
            *host_out = host;
            *ptr_out = (char *)dev;
            return 1;
        }
        (void)cudaFreeHost(host);
        (void)cudaGetLastError();
    } else {
        (void)cudaGetLastError();
    }
    fprintf(stderr,
            "ds4: CUDA streaming %s pinned alloc failed for %.2f MiB "
            "(locked-page pool exhausted); falling back to VRAM\n",
            label, (double)bytes / 1048576.0);
    char *dev = NULL;
    err = cudaMalloc((void **)&dev, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA streaming %s alloc failed for %.2f MiB: %s\n",
                label, (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    *ptr_out = dev;
    *host_out = NULL;
    return 1;
}

/* Grow a device allocation while preserving its existing contents
 * (incremental slot residency appends expert rows to the live table). */
static int cuda_stream_selected_ensure_bytes_keep(
        char **ptr, uint64_t *capacity, uint64_t bytes, const char *label) {
    if (*ptr && *capacity >= bytes) return 1;
    char *old = *ptr;
    const uint64_t old_cap = old ? *capacity : 0;
    char *np = NULL;
    if (bytes == 0 || bytes > (uint64_t)SIZE_MAX) return 0;
    cudaError_t err = cudaMalloc((void **)&np, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA streaming %s keep-alloc failed for %.2f MiB: %s\n",
                label, (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    if (old && old_cap != 0) {
        err = cudaMemcpy(np, old, (size_t)old_cap, cudaMemcpyDeviceToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA streaming %s keep-copy failed: %s\n",
                    label, cudaGetErrorString(err));
            (void)cudaGetLastError();
            (void)cudaFree(np);
            return 0;
        }
        (void)cudaFree(old);
    }
    *ptr = np;
    *capacity = bytes;
    return 1;
}

/* Pinned grow-in-place: new host block, memcpy old contents, free old. */
static int cuda_stream_selected_ensure_pinned_keep(
        char **ptr, char **host, uint64_t *capacity,
        uint64_t bytes, const char *label) {
    if (*ptr && *capacity >= bytes) return 1;
    char *old_host = *host;
    const uint64_t old_cap = old_host ? *capacity : 0;
    char *new_host = NULL, *new_dev = NULL;
    if (!cuda_stream_selected_alloc_pinned(&new_dev, &new_host, bytes, label)) {
        return 0;
    }
    if (old_host && old_cap != 0) {
        memcpy(new_host, old_host, (size_t)old_cap);
        (void)cudaFreeHost(old_host);
    }
    *host = new_host;
    *ptr = new_dev;
    *capacity = bytes;
    return 1;
}

static int cuda_stream_selected_ensure_i32(uint64_t count) {
    if (count == 0 || count > UINT64_MAX / sizeof(int32_t)) return 0;
    const uint64_t bytes = count * sizeof(int32_t);
    if (cuda_slot_pinned()) {
        if (g_stream_selected_cache.slot_selected_ptr &&
            g_stream_selected_cache.slot_selected_capacity >= bytes) return 1;
        if (g_stream_selected_cache.slot_selected_host) {
            (void)cudaFreeHost(g_stream_selected_cache.slot_selected_host);
            g_stream_selected_cache.slot_selected_host = NULL;
            g_stream_selected_cache.slot_selected_ptr = NULL;
            g_stream_selected_cache.slot_selected_capacity = 0;
        }
        char *dev = NULL, *host = NULL;
        if (!cuda_stream_selected_alloc_pinned(&dev, &host, bytes,
                                               "selected-id remap")) {
            return 0;
        }
        g_stream_selected_cache.slot_selected_host = (int32_t *)host;
        g_stream_selected_cache.slot_selected_ptr = (int32_t *)dev;
        g_stream_selected_cache.slot_selected_capacity = bytes;
        return 1;
    }
    return cuda_stream_selected_ensure_bytes(
            (char **)&g_stream_selected_cache.slot_selected_ptr,
            &g_stream_selected_cache.slot_selected_capacity,
            bytes,
            "selected-id remap");
}

static int cuda_stream_selected_ranges_valid(
        const ds4_gpu_stream_expert_table *table) {
    if (!table || !table->model_map || table->model_size == 0 ||
        table->n_total_expert == 0 || table->gate_expert_bytes == 0 ||
        table->down_expert_bytes == 0) {
        return 0;
    }
    if ((uint64_t)table->n_total_expert >
            UINT64_MAX / table->gate_expert_bytes ||
        (uint64_t)table->n_total_expert >
            UINT64_MAX / table->down_expert_bytes) {
        return 0;
    }
    const uint64_t gate_bytes =
        (uint64_t)table->n_total_expert * table->gate_expert_bytes;
    const uint64_t down_bytes =
        (uint64_t)table->n_total_expert * table->down_expert_bytes;
    return table->gate_offset <= table->model_size &&
           gate_bytes <= table->model_size - table->gate_offset &&
           table->up_offset <= table->model_size &&
           gate_bytes <= table->model_size - table->up_offset &&
           table->down_offset <= table->model_size &&
           down_bytes <= table->model_size - table->down_offset;
}

static int cuda_stream_selected_cache_begin_load(
        const ds4_gpu_stream_expert_table *table,
        const int32_t *selected_ids,
        uint32_t slot_count) {
    if (!g_ssd_streaming_mode) {
        cuda_stream_selected_cache_invalidate();
        return 1;
    }
    if (!cuda_stream_selected_ranges_valid(table) || !selected_ids ||
        slot_count == 0) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    if (g_n_gpus != 1) {
        fprintf(stderr,
                "ds4: CUDA SSD streaming requires single-GPU placement\n");
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    if ((uint64_t)table->n_total_expert > DS4_SLOT_MAX_EXPERT) {
        fprintf(stderr,
                "ds4: CUDA streaming expert count %u exceeds slot map %d\n",
                table->n_total_expert, (int)DS4_SLOT_MAX_EXPERT);
        cuda_stream_selected_cache_invalidate();
        return 0;
    }

    /* Phase profile (DS4_CUDA_SLOT_PHASE_PROFILE): host-wall split of the
     * per-layer slot-cache work — sync (deferred join + upload drain), map
     * (id classification + map ensure), submit (alloc + both copy waves),
     * tail (remap copy + events + compute-stream wait). */
    const bool ph_prof = getenv("DS4_CUDA_SLOT_PHASE_PROFILE") != NULL;
    const double ph0 = ph_prof ? cuda_wall_sec() : 0.0;

    /* Deferred compute-stream join (DS4_CUDA_DEFER_SYNC=1): the previous
     * layer's kernels must be finished before this layer's uploads overwrite
     * the slot table.  It runs after the routing read-back and the previous
     * staging window, so it normally costs ~0; in other sync modes it is a
     * no-op. */
    if (ds4_gpu_join_pending_commands() == 0) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    /* SSD paging pipeline: the upload stream is asynchronous (the per-copy
     * tail sync was replaced by the upload-done event). Before any free /
     * realloc / keep-copy of the table buffers, drain the upload stream so
     * the previous layer's in-flight uploads cannot race the host-side
     * buffer management. Steady-state cost is ~0: the previous layer's FFN
     * already waited for those uploads on the compute stream. */
    if (g_stream_selected_upload_stream) {
        (void)cudaStreamSynchronize(g_stream_selected_upload_stream);
        (void)cudaGetLastError();
    }
    const double ph1 = ph_prof ? cuda_wall_sec() : 0.0;

    /* Predictive prefetch: record this layer's routed ids + table offsets
     * for the next chunk's prediction (the worker-thread job for the NEXT
     * layer is submitted at the end of this call, after the copies).  The
     * router near-miss ids (④-(a)) are appended so the prediction covers
     * the selection drift between chunks. */
    if (ds4_pf_enabled() && table->layer < DS4_PF_MAX_LAYERS &&
        slot_count <= DS4_PF_MAX_IDS) {
        uint32_t nrec = slot_count;
        for (uint32_t i = 0; i < slot_count; i++) {
            g_pf_prev_ids[table->layer][i] = selected_ids[i];
        }
        if (g_router_prefetch_ids &&
            g_router_prefetch_ids->bytes >= 8u * sizeof(int32_t)) {
            /* token count from the slot count (6 ids per token); the tensor
             * is sized by prefill_cap so its byte size cannot tell. */
            const uint32_t ntok = slot_count / 6u;
            const uint32_t copy_tok = ntok > 12u ? 12u : ntok;
            if (copy_tok != 0u &&
                nrec + 8u * copy_tok <= DS4_PF_MAX_IDS) {
                int32_t extras[96];
                if (cudaMemcpy(extras, g_router_prefetch_ids->ptr,
                               (size_t)copy_tok * 8u * sizeof(int32_t),
                               cudaMemcpyDeviceToHost) == cudaSuccess) {
                    for (uint32_t t = 0; t < copy_tok; t++) {
                        for (uint32_t j = 0; j < 8u; j++) {
                            g_pf_prev_ids[table->layer][nrec++] =
                                extras[t * 8u + j];
                        }
                    }
                }
            }
        }
        g_pf_prev_count[table->layer] = nrec;
        g_pf_table[table->layer].gate_offset = table->gate_offset;
        g_pf_table[table->layer].up_offset = table->up_offset;
        g_pf_table[table->layer].down_offset = table->down_offset;
        g_pf_table[table->layer].gate_expert_bytes = table->gate_expert_bytes;
        g_pf_table[table->layer].down_expert_bytes = table->down_expert_bytes;
    }

    const int logical_tier = 0;

    /* Determinism: the previous layer's MMQ kernels may still be reading
     * the compact table.  Order EVERY upload wave — incremental appends and
     * full rebuilds alike — after the compute stream's last consumption
     * (the compute_done event is recorded after the routed-MoE kernels), so
     * no copy can overlap the readers regardless of the host's pacing. */
    if (g_stream_selected_compute_done_event &&
        g_stream_selected_upload_stream) {
        (void)cudaStreamWaitEvent(g_stream_selected_upload_stream,
                                  g_stream_selected_compute_done_event, 0);
    }

    /* Incremental residency: keep the compact table across layers and only
     * copy newly routed experts. The table is rebuilt when its shape/model
     * changes, when the resident budget is exceeded, or when disabled. */
    const bool incremental_ok =
        g_stream_selected_cache.valid &&
        g_stream_selected_cache.logical_tier == logical_tier &&
        g_stream_selected_cache.model_map == table->model_map &&
        g_stream_selected_cache.n_total_expert == table->n_total_expert &&
        g_stream_selected_cache.gate_expert_bytes == table->gate_expert_bytes &&
        g_stream_selected_cache.down_expert_bytes == table->down_expert_bytes &&
        g_stream_selected_cache.gate_ptr &&
        g_stream_selected_cache.up_ptr &&
        g_stream_selected_cache.down_ptr &&
        g_stream_selected_cache.slot_selected_ptr &&
        getenv("DS4_CUDA_NO_SLOT_INCREMENTAL") == NULL;

    uint64_t resident_budget = 1300ull * 1048576ull; /* 1300 MiB default:
        * measured best on this 8GB laptop (26.4s median prefill). The
        * expert-id collision that used to corrupt big tables is fixed
        * (global (layer, expert) keying), and WDDM page-out of the table's
        * overflow into shared GPU memory is verified safe, so the budget
        * may exceed the physically free VRAM. env-tunable. */
    const char *rb_env = getenv("DS4_CUDA_SLOT_RESIDENT_MB");
    if (rb_env && rb_env[0]) {
        char *end = NULL;
        const unsigned long mb = strtoul(rb_env, &end, 10);
        if (end != rb_env && mb > 0) resident_budget = (uint64_t)mb * 1048576ull;
    }
    const uint64_t expert_bytes =
        table->gate_expert_bytes * 2ull + table->down_expert_bytes;

    bool map_reset_pending = false;
    if (!incremental_ok) {
        cuda_stream_selected_cache_invalidate();
        g_stream_selected_cache.resident_experts = 0;
        map_reset_pending = true;
    }

    /* Build this layer's unique expert set and classify resident vs new. */
    std::vector<int32_t> compact_ids;
    std::vector<int32_t> slot_ids;
    try {
        compact_ids.reserve(slot_count < table->n_total_expert ?
                            slot_count : table->n_total_expert);
        slot_ids.resize(slot_count);
    } catch (...) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    int32_t layer_expert_to_slot[DS4_SLOT_MAX_EXPERT];
    for (uint32_t e = 0; e < table->n_total_expert; e++) {
        layer_expert_to_slot[e] = -1;
    }
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t expert = selected_ids[i];
        if (expert < 0 || (uint32_t)expert >= table->n_total_expert) {
            fprintf(stderr,
                    "ds4: CUDA streaming expert id %d is outside 0..%u at layer %u\n",
                    expert, table->n_total_expert, table->layer);
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        const uint32_t eu = (uint32_t)expert;
        if (layer_expert_to_slot[eu] < 0) {
            layer_expert_to_slot[eu] = (int32_t)compact_ids.size();
            compact_ids.push_back(expert);
        }
        slot_ids[i] = layer_expert_to_slot[eu];
    }
    if (compact_ids.empty()) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    const uint64_t compact_count = compact_ids.size();
    if (compact_count > UINT64_MAX / table->gate_expert_bytes ||
        compact_count > UINT64_MAX / table->down_expert_bytes) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    /* Scheduler telemetry: peak union footprint since the last reset. */
    {
        const uint64_t union_bytes = compact_count * expert_bytes;
        if (union_bytes > g_stream_selected_cache.peak_union_bytes) {
            g_stream_selected_cache.peak_union_bytes = union_bytes;
        }
    }
    /* Size/keep the GLOBAL expert->slot map for this layer before any
     * classification or remap reads it. */
    if (!stream_selected_map_ensure(table->layer + 1u,
                                    table->n_total_expert)) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    if (map_reset_pending) stream_selected_map_reset();

    /* Classify: already resident (mapping exists) vs new experts to copy. */
    uint32_t new_count = 0;
    for (uint32_t i = 0; i < compact_ids.size(); i++) {
        const uint32_t eu = (uint32_t)compact_ids[i];
        uint64_t gidx = 0;
        stream_selected_global_idx(table->layer, eu,
                                   table->n_total_expert, &gidx);
        if (g_stream_selected_cache.host_expert_to_slot[gidx] < 0) new_count++;
    }
    const uint64_t resident_after =
        (uint64_t)g_stream_selected_cache.resident_experts + new_count;
    if (resident_after > 0x1000000ull ||
        !stream_selected_src_ensure((uint32_t)resident_after)) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    const bool budget_ok =
        expert_bytes == 0 || resident_after <= UINT64_MAX / expert_bytes;
    bool incremental =
        incremental_ok && budget_ok &&
        resident_after <= UINT32_MAX &&
        resident_after * expert_bytes <= resident_budget;
    if (getenv("DS4_LM_DEBUG")) {
        fprintf(stderr,
                "ds4: slot layer=%u unique=%u new=%u resident=%u after=%llu "
                "expert_bytes=%llu budget=%llu append_ok=%d ok=%d\n",
                table->layer, (uint32_t)compact_ids.size(), new_count,
                g_stream_selected_cache.resident_experts,
                (unsigned long long)resident_after,
                (unsigned long long)expert_bytes,
                (unsigned long long)resident_budget,
                incremental ? 1 : 0, incremental_ok ? 1 : 0);
    }
    const double ph2 = ph_prof ? cuda_wall_sec() : 0.0;
    if (incremental) {
        /* VRAM headroom guard (Windows/8GB fusion port): WDDM can page
         * overflowing allocations out to shared system memory — evicted
         * pages are read/written correctly by SM and DMA paths (verified by
         * the test_pinned probe series and the eviction-forcing slot-table
         * test), so the guard is now only a small floor against running the
         * GPU completely dry (cuBLAS workspaces). Growth proceeds into
         * shared GPU memory when free VRAM is low. DS4_CUDA_SLOT_NO_GUARD=1
         * disables the check entirely. */
        if (getenv("DS4_CUDA_SLOT_NO_GUARD") == NULL) {
            size_t free_bytes = 0, total_bytes = 0;
            if (cudaMemGetInfo(&free_bytes, &total_bytes) == cudaSuccess &&
                (uint64_t)free_bytes < 128ull * 1048576ull) {
                incremental = false;
                if (getenv("DS4_LM_DEBUG")) {
                    fprintf(stderr,
                            "ds4: slot incremental skipped at layer %u: free=%.1f MiB grow=%.1f MiB\n",
                            table->layer,
                            (double)free_bytes / 1048576.0,
                            (double)((uint64_t)new_count * expert_bytes) / 1048576.0);
                }
            }
        }
    }

    if (incremental) {
        /* Grow the table in place, append only the new experts. */
        const uint64_t gate_need = resident_after * table->gate_expert_bytes;
        const uint64_t down_need = resident_after * table->down_expert_bytes;
        /* pg graph liveness guard: a captured graph bakes the table base
         * pointers, so growth that moves the buffers must retire the graph
         * first.  Sync the pg stream so the in-flight replay finishes
         * reading the old buffers before any realloc can free them. */
        if (g_pg_exec && !g_pg_disabled &&
            ((uint64_t)g_stream_selected_cache.gate_capacity < gate_need ||
             (uint64_t)g_stream_selected_cache.up_capacity < gate_need ||
             (uint64_t)g_stream_selected_cache.down_capacity < down_need)) {
            if (g_pg_stream) (void)cudaStreamSynchronize(g_pg_stream);
            g_pg_disabled = 1;
            fprintf(stderr,
                    "ds4: pg graph disabled: slot table growth needed mid-request\n");
        }
        /* Pinned mode allocates the whole budget up front (grow-free
         * cycles fragment the WDDM locked-page pool until it reports
         * "exhausted" far below the real limit — verified: a single 8GB
         * pinned block works while grow/free churn dies at ~1GB). */
        uint64_t budget_gate_bytes = 0, budget_down_bytes = 0;
        if (expert_bytes != 0) {
            const uint64_t max_slots = resident_budget / expert_bytes;
            budget_gate_bytes = max_slots * table->gate_expert_bytes;
            budget_down_bytes = max_slots * table->down_expert_bytes;
        }
        const bool alloc_ok = cuda_slot_pinned() ?
            (ds4_gpu_set_current_device(logical_tier) == 0 &&
             cuda_stream_selected_ensure_pinned_keep(
                     &g_stream_selected_cache.gate_ptr,
                     &g_stream_selected_cache.gate_host,
                     &g_stream_selected_cache.gate_capacity,
                     budget_gate_bytes ? budget_gate_bytes : gate_need,
                     "gate experts") &&
             cuda_stream_selected_ensure_pinned_keep(
                     &g_stream_selected_cache.up_ptr,
                     &g_stream_selected_cache.up_host,
                     &g_stream_selected_cache.up_capacity,
                     budget_gate_bytes ? budget_gate_bytes : gate_need,
                     "up experts") &&
             cuda_stream_selected_ensure_pinned_keep(
                     &g_stream_selected_cache.down_ptr,
                     &g_stream_selected_cache.down_host,
                     &g_stream_selected_cache.down_capacity,
                     budget_down_bytes ? budget_down_bytes : down_need,
                     "down experts") &&
             cuda_stream_selected_ensure_i32(slot_count)) :
            (ds4_gpu_set_current_device(logical_tier) == 0 &&
             cuda_stream_selected_ensure_bytes_keep(
                     &g_stream_selected_cache.gate_ptr,
                     &g_stream_selected_cache.gate_capacity,
                     gate_need, "gate experts") &&
             cuda_stream_selected_ensure_bytes_keep(
                     &g_stream_selected_cache.up_ptr,
                     &g_stream_selected_cache.up_capacity,
                     gate_need, "up experts") &&
             cuda_stream_selected_ensure_bytes_keep(
                     &g_stream_selected_cache.down_ptr,
                     &g_stream_selected_cache.down_capacity,
                     down_need, "down experts") &&
             cuda_stream_selected_ensure_i32(slot_count));
        if (!alloc_ok) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        /* Split-phase pipeline bookkeeping: down rows deferred so their DMA
         * overlaps the FFN gate/up compute. */
        std::vector<ds4_stream_copy_job> gateup_jobs;
        std::vector<ds4_stream_copy_job> down_jobs;
        try {
            gateup_jobs.reserve(compact_ids.size() * 2u);
            down_jobs.reserve(compact_ids.size());
        } catch (...) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        for (uint32_t i = 0; i < compact_ids.size(); i++) {
            const uint32_t eu = (uint32_t)compact_ids[i];
            uint64_t gidx = 0;
            stream_selected_global_idx(table->layer, eu,
                                       table->n_total_expert, &gidx);
            if (g_stream_selected_cache.host_expert_to_slot[gidx] >= 0) continue;
            const uint64_t slot = g_stream_selected_cache.resident_experts++;
            const uint64_t gate_src =
                table->gate_offset + (uint64_t)eu * table->gate_expert_bytes;
            const uint64_t up_src =
                table->up_offset + (uint64_t)eu * table->gate_expert_bytes;
            const uint64_t down_src =
                table->down_offset + (uint64_t)eu * table->down_expert_bytes;
            const uint64_t gate_dst = slot * table->gate_expert_bytes;
            const uint64_t down_dst = slot * table->down_expert_bytes;
            /* Split-phase pipeline: gate/up first (the FFN pair kernels
             * only need these), the down rows are copied afterwards so
             * their DMA overlaps the pair compute. */
            gateup_jobs.push_back({g_stream_selected_cache.gate_ptr + gate_dst,
                                   gate_src, table->gate_expert_bytes});
            gateup_jobs.push_back({g_stream_selected_cache.up_ptr + gate_dst,
                                   up_src, table->gate_expert_bytes});
            down_jobs.push_back({g_stream_selected_cache.down_ptr + down_dst,
                                 down_src, table->down_expert_bytes});
            if (getenv("DS4_CUDA_SLOT_VERIFY")) {
                /* Debug-mode verify reads the just-uploaded rows; drain the
                 * async upload stream first (production paths never sync). */
                (void)cudaStreamSynchronize(g_stream_selected_upload_stream);
                (void)cudaGetLastError();
                static char vbuf[64];
                static char fbuf[64];
                memset(vbuf, 0x7e, sizeof(vbuf));
                memset(fbuf, 0x3c, sizeof(fbuf));
                /* model_map only maps the embedding span under streaming;
                 * compare against a direct file read instead. */
                const bool fread_ok =
                    g_model_fd >= 0 &&
                    cuda_pread_full(g_model_fd, fbuf, sizeof(fbuf), gate_src);
                if (fread_ok &&
                    cudaMemcpy(vbuf, g_stream_selected_cache.gate_ptr + gate_dst,
                               sizeof(vbuf), cudaMemcpyDeviceToHost) == cudaSuccess &&
                    memcmp(vbuf, fbuf, sizeof(vbuf)) != 0) {
                    fprintf(stderr,
                            "ds4: SLOT VERIFY MISMATCH layer=%u expert=%u slot=%llu\n",
                            table->layer, eu, (unsigned long long)slot);
                }
                /* Whole-row verify of the LAST appended expert's gate table
                 * (catches mid-row corruption that a 64-byte spot check
                 * cannot see). */
                static char *big_v = NULL;
                static char *big_f = NULL;
                static uint64_t big_cap = 0;
                if (!big_v) {
                    big_cap = 8ull * 1048576ull;
                    big_v = (char *)malloc((size_t)big_cap);
                    big_f = (char *)malloc((size_t)big_cap);
                }
                if (big_v && big_f && table->gate_expert_bytes <= big_cap &&
                    g_model_fd >= 0 &&
                    cuda_pread_full(g_model_fd, big_f,
                                    (uint64_t)table->gate_expert_bytes,
                                    gate_src) &&
                    cudaMemcpy(big_v,
                               g_stream_selected_cache.gate_ptr + gate_dst,
                               (size_t)table->gate_expert_bytes,
                               cudaMemcpyDeviceToHost) == cudaSuccess) {
                    const uint64_t words = table->gate_expert_bytes / 4;
                    uint64_t mismatches = 0;
                    for (uint64_t w = 0; w < words; w++) {
                        if (((const uint32_t *)big_v)[w] !=
                            ((const uint32_t *)big_f)[w]) {
                            if (mismatches < 4) {
                                fprintf(stderr,
                                        "ds4: SLOT VERIFY ROW MISMATCH layer=%u "
                                        "expert=%u slot=%llu word=%llu dev=%08x file=%08x\n",
                                        table->layer, eu, (unsigned long long)slot,
                                        (unsigned long long)w,
                                        ((const uint32_t *)big_v)[w],
                                        ((const uint32_t *)big_f)[w]);
                            }
                            mismatches++;
                        }
                    }
                    if (mismatches) {
                        fprintf(stderr,
                                "ds4: SLOT VERIFY ROW layer=%u expert=%u slot=%llu "
                                "mismatched_words=%llu/%llu\n",
                                table->layer, eu, (unsigned long long)slot,
                                (unsigned long long)mismatches,
                                (unsigned long long)words);
                    }
                }
            }
            g_stream_selected_cache.slot_gate_src[slot] = gate_src;
            g_stream_selected_cache.host_expert_to_slot[gidx] = (int32_t)slot;
        }
        /* Fan the gate/up copies across staging workers (each with its own
         * pinned staging pool; parallel OVERLAPPED preads), then record the
         * gateup event on the main thread so the FFN pair kernels wait only
         * those.  The down rows follow as a second parallel wave so their
         * DMA overlaps the pair compute on the compute stream.
         * NOTE: offset-sorted waves re-applied 09-12 for the 8.5s stall
         * localization build (FUSION_REPORT ㉑). */
        std::sort(gateup_jobs.begin(), gateup_jobs.end(),
                  [](const ds4_stream_copy_job &x, const ds4_stream_copy_job &y) {
                      return x.offset < y.offset;
                  });
        std::sort(down_jobs.begin(), down_jobs.end(),
                  [](const ds4_stream_copy_job &x, const ds4_stream_copy_job &y) {
                      return x.offset < y.offset;
                  });
        if (!cuda_stream_copy_jobs_parallel(gateup_jobs.data(),
                                            (uint32_t)gateup_jobs.size(),
                                            table->model_map,
                                            table->model_size)) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        if (g_stream_selected_upload_gateup_event) {
            (void)cudaEventRecord(g_stream_selected_upload_gateup_event,
                                  g_stream_selected_upload_stream);
        }
        if (!cuda_stream_copy_jobs_parallel(down_jobs.data(),
                                            (uint32_t)down_jobs.size(),
                                            table->model_map,
                                            table->model_size)) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        if (getenv("DS4_CUDA_SLOT_VERIFY")) {
            /* Whole-table FULL-ROW check: every resident row compared
             * byte-for-byte against its recorded file source (the earlier
             * 64-byte spot check could not see mid-row corruption). */
            (void)cudaStreamSynchronize(g_stream_selected_upload_stream);
            (void)cudaGetLastError();
            static char *big_v = NULL;
            static char *big_f = NULL;
            static uint64_t big_cap = 0;
            if (!big_v || big_cap < table->gate_expert_bytes) {
                big_cap = table->gate_expert_bytes + 4096;
                free(big_v);
                free(big_f);
                big_v = (char *)malloc((size_t)big_cap);
                big_f = (char *)malloc((size_t)big_cap);
            }
            if (big_v && big_f) {
                for (uint32_t s = 0; s < g_stream_selected_cache.resident_experts; s++) {
                    const uint64_t src = g_stream_selected_cache.slot_gate_src[s];
                    if (src == 0) continue;
                    const bool fread_ok =
                        g_model_fd >= 0 &&
                        cuda_pread_full(g_model_fd, big_f,
                                        table->gate_expert_bytes, src);
                    if (fread_ok &&
                        cudaMemcpy(big_v,
                                   g_stream_selected_cache.gate_ptr +
                                       (uint64_t)s * table->gate_expert_bytes,
                                   (size_t)table->gate_expert_bytes,
                                   cudaMemcpyDeviceToHost) == cudaSuccess &&
                        memcmp(big_v, big_f, (size_t)table->gate_expert_bytes) != 0) {
                        const uint64_t words = table->gate_expert_bytes / 4;
                        uint64_t mism = 0;
                        for (uint64_t w = 0; w < words; w++) {
                            if (((const uint32_t *)big_v)[w] !=
                                ((const uint32_t *)big_f)[w]) {
                                if (mism < 3) {
                                    fprintf(stderr,
                                            "ds4: SLOT VERIFY FULLROW MISMATCH layer=%u slot=%u src=%llu word=%llu dev=%08x file=%08x\n",
                                            table->layer, s, (unsigned long long)src,
                                            (unsigned long long)w,
                                            ((const uint32_t *)big_v)[w],
                                            ((const uint32_t *)big_f)[w]);
                                }
                                mism++;
                            }
                        }
                        fprintf(stderr,
                                "ds4: SLOT VERIFY FULLROW layer=%u slot=%u mismatched=%llu/%llu\n",
                                table->layer, s, (unsigned long long)mism,
                                (unsigned long long)words);
                        break;
                    }
                }
            }
        }
        /* Remap the layer's selected ids to persistent slot ids. */
        for (uint32_t i = 0; i < slot_count; i++) {
            const uint32_t eu = (uint32_t)selected_ids[i];
            uint64_t gidx = 0;
            stream_selected_global_idx(table->layer, eu,
                                       table->n_total_expert, &gidx);
            const int32_t slot =
                g_stream_selected_cache.host_expert_to_slot[gidx];
            if (slot < 0) {
                cuda_stream_selected_cache_invalidate();
                return 0;
            }
            slot_ids[i] = slot;
        }
    } else {
        /* Full rebuild of the compact table for this layer's unique set. */
        cuda_stream_selected_cache_invalidate();
        /* pg prealloc: when the request will capture the prefill graph
         * (gate 4096 assignments, graph not yet captured/disabled), size
         * the table for the FULL expert set up front.  Per-layer unions
         * fluctuate (227..258 measured on a 118-token batch) and every
         * mid-request realloc moves the baked-in pointers; the full-table
         * allocation makes every later rebuild a keep-in-place. */
        const bool pg_prealloc =
            getenv("DS4_CUDA_PREFILL_GRAPH") != NULL &&
            !g_pg_disabled && !g_pg_tried &&
            g_pg_request_assign <= 4096u &&
            table->n_total_expert > 0;
        uint64_t gate_bytes = compact_count * table->gate_expert_bytes;
        uint64_t down_bytes = compact_count * table->down_expert_bytes;
        if (pg_prealloc) {
            gate_bytes = (uint64_t)table->n_total_expert *
                         table->gate_expert_bytes;
            down_bytes = (uint64_t)table->n_total_expert *
                         table->down_expert_bytes;
        }
        /* pg graph liveness guard (mirrors the incremental branch): never
         * let a rebuild move the buffers under a live captured graph. */
        if (g_pg_exec && !g_pg_disabled &&
            ((uint64_t)g_stream_selected_cache.gate_capacity < gate_bytes ||
             (uint64_t)g_stream_selected_cache.up_capacity < gate_bytes ||
             (uint64_t)g_stream_selected_cache.down_capacity < down_bytes)) {
            if (g_pg_stream) (void)cudaStreamSynchronize(g_pg_stream);
            g_pg_disabled = 1;
            fprintf(stderr,
                    "ds4: pg graph disabled: slot table rebuild would move buffers\n");
        }
        if (g_stream_selected_cache.logical_tier != logical_tier &&
            (g_stream_selected_cache.gate_ptr ||
             g_stream_selected_cache.up_ptr ||
             g_stream_selected_cache.down_ptr ||
             g_stream_selected_cache.slot_selected_ptr)) {
            cuda_stream_selected_cache_release();
        }
        stream_selected_map_reset();
        g_stream_selected_cache.resident_experts = 0;
        /* Pinned mode: keep the existing allocation (no free/alloc churn);
         * first allocation takes the whole budget up front. */
        uint64_t rbudget_gate_bytes = 0, rbudget_down_bytes = 0;
        if (expert_bytes != 0) {
            const uint64_t max_slots = resident_budget / expert_bytes;
            rbudget_gate_bytes = max_slots * table->gate_expert_bytes;
            rbudget_down_bytes = max_slots * table->down_expert_bytes;
        }
        const bool pinned_reuse =
            cuda_slot_pinned() &&
            g_stream_selected_cache.gate_host &&
            g_stream_selected_cache.up_host &&
            g_stream_selected_cache.down_host &&
            g_stream_selected_cache.gate_capacity >= gate_bytes &&
            g_stream_selected_cache.up_capacity >= gate_bytes &&
            g_stream_selected_cache.down_capacity >= down_bytes;
        const bool ralloc_ok = cuda_slot_pinned() ?
            (ds4_gpu_set_current_device(logical_tier) == 0 &&
             (pinned_reuse ||
              (cuda_stream_selected_alloc_pinned(
                       &g_stream_selected_cache.gate_ptr,
                       &g_stream_selected_cache.gate_host,
                       rbudget_gate_bytes ? rbudget_gate_bytes : gate_bytes,
                       "gate experts") &&
               cuda_stream_selected_alloc_pinned(
                       &g_stream_selected_cache.up_ptr,
                       &g_stream_selected_cache.up_host,
                       rbudget_gate_bytes ? rbudget_gate_bytes : gate_bytes,
                       "up experts") &&
               cuda_stream_selected_alloc_pinned(
                       &g_stream_selected_cache.down_ptr,
                       &g_stream_selected_cache.down_host,
                       rbudget_down_bytes ? rbudget_down_bytes : down_bytes,
                       "down experts"))) &&
             cuda_stream_selected_ensure_i32(slot_count)) :
            (ds4_gpu_set_current_device(logical_tier) == 0 &&
             cuda_stream_selected_ensure_bytes(
                     &g_stream_selected_cache.gate_ptr,
                     &g_stream_selected_cache.gate_capacity,
                     gate_bytes, "gate experts") &&
             cuda_stream_selected_ensure_bytes(
                     &g_stream_selected_cache.up_ptr,
                     &g_stream_selected_cache.up_capacity,
                     gate_bytes, "up experts") &&
             cuda_stream_selected_ensure_bytes(
                     &g_stream_selected_cache.down_ptr,
                     &g_stream_selected_cache.down_capacity,
                     down_bytes, "down experts") &&
             cuda_stream_selected_ensure_i32(slot_count));
        if (cuda_slot_pinned() && !pinned_reuse && ralloc_ok) {
            g_stream_selected_cache.gate_capacity =
                rbudget_gate_bytes ? rbudget_gate_bytes : gate_bytes;
            g_stream_selected_cache.up_capacity =
                rbudget_gate_bytes ? rbudget_gate_bytes : gate_bytes;
            g_stream_selected_cache.down_capacity =
                rbudget_down_bytes ? rbudget_down_bytes : down_bytes;
        }
        if (!ralloc_ok) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        std::vector<ds4_stream_copy_job> rb_gateup_jobs;
        std::vector<ds4_stream_copy_job> rb_down_jobs;
        try {
            rb_gateup_jobs.reserve(compact_ids.size() * 2u);
            rb_down_jobs.reserve(compact_ids.size());
        } catch (...) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        for (uint32_t i = 0; i < compact_ids.size(); i++) {
            const uint64_t expert = (uint32_t)compact_ids[i];
            const uint64_t gate_src =
                table->gate_offset + expert * table->gate_expert_bytes;
            const uint64_t up_src =
                table->up_offset + expert * table->gate_expert_bytes;
            const uint64_t down_src =
                table->down_offset + expert * table->down_expert_bytes;
            const uint64_t gate_dst = (uint64_t)i * table->gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * table->down_expert_bytes;
            /* Split-phase pipeline: gate/up first, down rows deferred. */
            rb_gateup_jobs.push_back({g_stream_selected_cache.gate_ptr + gate_dst,
                                      gate_src, table->gate_expert_bytes});
            rb_gateup_jobs.push_back({g_stream_selected_cache.up_ptr + gate_dst,
                                      up_src, table->gate_expert_bytes});
            rb_down_jobs.push_back({g_stream_selected_cache.down_ptr + down_dst,
                                    down_src, table->down_expert_bytes});
            g_stream_selected_cache.slot_gate_src[i] = gate_src;
            uint64_t gidx = 0;
            stream_selected_global_idx(table->layer, (uint32_t)expert,
                                       table->n_total_expert, &gidx);
            g_stream_selected_cache.host_expert_to_slot[gidx] = (int32_t)i;
        }
        /* Determinism: the previous layer's MMQ kernels may still be
         * reading the compact table while this rebuild overwrites it in
         * place.  Order the upload stream after the compute stream's last
         * consumption (g_stream_selected_compute_done_event, recorded on
         * the compute stream after the routed-MoE kernels) so no copy
         * lands before the readers drain. */
        if (g_stream_selected_compute_done_event &&
            g_stream_selected_upload_stream) {
            (void)cudaStreamWaitEvent(g_stream_selected_upload_stream,
                                      g_stream_selected_compute_done_event, 0);
        }
        /* NOTE: offset-sorted waves re-applied 09-12 (stall localization). */
        std::sort(rb_gateup_jobs.begin(), rb_gateup_jobs.end(),
                  [](const ds4_stream_copy_job &x, const ds4_stream_copy_job &y) {
                      return x.offset < y.offset;
                  });
        std::sort(rb_down_jobs.begin(), rb_down_jobs.end(),
                  [](const ds4_stream_copy_job &x, const ds4_stream_copy_job &y) {
                      return x.offset < y.offset;
                  });
        if (!cuda_stream_copy_jobs_parallel(rb_gateup_jobs.data(),
                                            (uint32_t)rb_gateup_jobs.size(),
                                            table->model_map,
                                            table->model_size)) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        if (g_stream_selected_upload_gateup_event) {
            (void)cudaEventRecord(g_stream_selected_upload_gateup_event,
                                  g_stream_selected_upload_stream);
        }
        if (!cuda_stream_copy_jobs_parallel(rb_down_jobs.data(),
                                            (uint32_t)rb_down_jobs.size(),
                                            table->model_map,
                                            table->model_size)) {
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
        g_stream_selected_cache.resident_experts = (uint32_t)compact_count;
    }

    const double ph3 = ph_prof ? cuda_wall_sec() : 0.0;
    const bool remap_ok = cuda_slot_pinned() ?
        (g_stream_selected_cache.slot_selected_host != NULL &&
         (memcpy(g_stream_selected_cache.slot_selected_host,
                 slot_ids.data(),
                 (size_t)slot_count * sizeof(int32_t)), true)) :
        cuda_ok(cudaMemcpy(g_stream_selected_cache.slot_selected_ptr,
                           slot_ids.data(),
                           (size_t)slot_count * sizeof(int32_t),
                           cudaMemcpyHostToDevice),
                "stream selected-id remap copy");
    if (!remap_ok) {
        cuda_stream_selected_cache_invalidate();
        return 0;
    }
    if (getenv("DS4_CUDA_SLOT_VERIFY")) {
        std::vector<int32_t> check_ids(slot_count);
        if (cudaMemcpy(check_ids.data(), g_stream_selected_cache.slot_selected_ptr,
                       (size_t)slot_count * sizeof(int32_t),
                       cudaMemcpyDeviceToHost) == cudaSuccess &&
            memcmp(check_ids.data(), slot_ids.data(),
                   (size_t)slot_count * sizeof(int32_t)) != 0) {
            fprintf(stderr,
                    "ds4: SLOT VERIFY IDS MISMATCH layer=%u slot_count=%u\n",
                    table->layer, slot_count);
        }
    }

    g_stream_selected_cache.logical_tier = logical_tier;
    g_stream_selected_cache.model_map = table->model_map;
    g_stream_selected_cache.layer = table->layer;
    g_stream_selected_cache.n_total_expert = table->n_total_expert;
    g_stream_selected_cache.slot_count = slot_count;
    g_stream_selected_cache.compact_count = g_stream_selected_cache.resident_experts;
    g_stream_selected_cache.gate_offset = table->gate_offset;
    g_stream_selected_cache.up_offset = table->up_offset;
    g_stream_selected_cache.down_offset = table->down_offset;
    g_stream_selected_cache.gate_expert_bytes = table->gate_expert_bytes;
    g_stream_selected_cache.down_expert_bytes = table->down_expert_bytes;
    g_stream_selected_cache.slot_selected_tensor.ptr =
        g_stream_selected_cache.slot_selected_ptr;
    g_stream_selected_cache.slot_selected_tensor.bytes =
        (uint64_t)slot_count * sizeof(int32_t);
    g_stream_selected_cache.slot_selected_tensor.owner = 0;
    g_stream_selected_cache.slot_selected_tensor.device_id = logical_tier;
    g_stream_selected_cache.valid = 1;
    /* SSD paging pipeline: order the compute stream after this layer's
     * gate/up uploads — the FFN pair kernels can start while the down DMA
     * is still in flight; the down kernels wait the upload-done event
     * themselves (see the FFN tiers). */
    if (g_stream_selected_upload_gateup_event) {
        if (cudaStreamWaitEvent((cudaStream_t)0,
                                g_stream_selected_upload_gateup_event, 0) !=
            cudaSuccess) {
            (void)cudaGetLastError();
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
    } else if (g_stream_selected_upload_done_event) {
        if (cudaStreamWaitEvent((cudaStream_t)0,
                                g_stream_selected_upload_done_event, 0) !=
            cudaSuccess) {
            (void)cudaGetLastError();
            cuda_stream_selected_cache_invalidate();
            return 0;
        }
    }
    /* Predictive prefetch: this layer's copies are issued; ask the worker
     * thread to pin the NEXT layer's predicted rows (from the previous
     * chunk's routing) while the FFN runs. */
    if (ds4_pf_enabled() && table->layer + 1u < DS4_PF_MAX_LAYERS &&
        g_pf_prev_count[table->layer + 1u] != 0) {
        ds4_pf_submit_job(table->layer + 1u);
    }
    if (ph_prof) {
        const double ph4 = cuda_wall_sec();
        fprintf(stderr,
                "ds4: slot phase layer=%u sync=%.1f map=%.1f submit=%.1f "
                "tail=%.1f ms\n",
                table->layer,
                (ph1 - ph0) * 1e3,
                (ph2 - ph1) * 1e3,
                (ph3 - ph2) * 1e3,
                (ph4 - ph3) * 1e3);
        fflush(stderr);
    }
    return 1;
}

__device__ __forceinline__ static float glm_rope_yarn_corr_factor_dev(
        int n_dims, int n_ctx_orig, float n_rot, float base) {
    return n_dims * logf(n_ctx_orig / (n_rot * 2.0f * (float)M_PI)) /
           (2.0f * logf(base));
}
__device__ __forceinline__ static float glm_rope_yarn_ramp_dev(
        float low, float high, int i0) {
    const float y = (i0 / 2 - low) / fmaxf(0.001f, high - low);
    return 1.0f - fminf(1.0f, fmaxf(0.0f, y));
}
__device__ __forceinline__ static void glm_rope_yarn_dev(
        float theta_extrap, float freq_scale, const float corr_dims[2],
        int i0, float ext_factor, float mscale,
        float *cos_theta, float *sin_theta) {
    float theta_interp = freq_scale * theta_extrap;
    float theta = theta_interp;
    if (ext_factor != 0.0f) {
        float ramp_mix = glm_rope_yarn_ramp_dev(corr_dims[0], corr_dims[1], i0) *
                         ext_factor;
        theta = theta_interp * (1.0f - ramp_mix) + theta_extrap * ramp_mix;
        mscale *= 1.0f + 0.1f * logf(1.0f / freq_scale);
    }
    *cos_theta = cosf(theta) * mscale;
    *sin_theta = sinf(theta) * mscale;
}

static int cuda_current_tier(void) {
    int dev = 0;
    if (cudaGetDevice(&dev) != cudaSuccess) return 0;
    return dev;
}

